    struct BudgetMutationProvider {
        calls: std::sync::atomic::AtomicUsize,
    }

    #[async_trait::async_trait]
    impl crate::summarize::provider::SummarizerProvider for BudgetMutationProvider {
        fn id(&self) -> &str {
            "budget-mutation-spy"
        }

        async fn availability(&self) -> crate::summarize::provider::Availability {
            crate::summarize::provider::Availability::Available
        }

        async fn summarize(
            &self,
            _request: &crate::summarize::provider::SummarizeRequest,
        ) -> crate::error::Result<String> {
            Ok(String::new())
        }

        async fn complete(&self, _system: &str, _user: &str) -> crate::error::Result<String> {
            self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Ok("stale answer".into())
        }
    }

    fn block_on<F: std::future::Future>(f: F) -> F::Output {
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap()
            .block_on(f)
    }

    /// C2 (lifecycle-helper contract): `stop_all_capture` must clear EVERY capture slot to `None`
    /// (deterministic `take()`) and be panic-free on an empty state. Combined with the C1 Drop tests
    /// (which prove a taken recorder finalizes + reaps its helper), this is the exit-hook safety net:
    /// after it runs, no capture path is left owned by `AppState`. The real SIGTERM of the Swift
    /// helper only truly verifies on a signed build, so this asserts the DETERMINISTIC slot-clearing —
    /// the seam the exit hook depends on.
    #[test]
    fn stop_all_capture_clears_every_capture_slot() {
        let state = build_state("stop-all-capture");
        // Sanity: fresh state has no recorders (a real recording would populate these).
        assert!(state.recorder.lock().unwrap().is_none());

        // Must not panic, and must leave every slot None.
        stop_all_capture(&state);

        assert!(
            state.recorder.lock().unwrap().is_none(),
            "mic recorder slot cleared"
        );
    }

    /// PHASE-4 lock gate (RED-before-GREEN): `verify_note_sources` + `apply_note_verify_markers` on a
    /// SEALED-and-not-session-unlocked meeting MUST refuse with `AppError::Locked` BEFORE any note
    /// read / connector egress — a locked note can neither be verified nor marker-written. Runs with
    /// NO Jira configured, so once session-unlocked the verify falls through to the fail-closed
    /// connector gate (`Unavailable`), proving `Locked` was the FIRST gate, not a downstream error.
    #[test]
    fn verify_commands_refuse_a_sealed_meeting() {
        let state = build_state("verify-lockgate");
        make_open_folder(&state.db, "f-vlock", "Secret");
        state
            .db
            .insert_meeting(&Meeting {
                id: "m-vlock".to_string(),
                started_at: "2026-07-05T09:00:00Z".to_string(),
                ended_at: None,
                title: Some("Sprint".to_string()),
                duration_s: 600,
                audio_path: None,
                status: MeetingStatus::Summarized,
                folder_id: Some("f-vlock".to_string()),
            })
            .unwrap();
        state
            .db
            .upsert_note(&NoteRecord {
                meeting_id: "m-vlock".to_string(),
                provider_id: "claude_code".to_string(),
                markdown: "# N\n- Ship PROJ-1 by 2026-07-08\n".to_string(),
                created_at: "2026-07-05T09:10:00Z".to_string(),
                exported_path: None,
                model_requested: None,
                model_served: None,
                gateway_host: None,
            })
            .unwrap();
        state
            .db
            .set_note_folder("m-vlock", Some("f-vlock"))
            .unwrap();
        state
            .db
            .set_folder_locked("f-vlock", true, Some(&b"wrapped"[..]))
            .unwrap();
        // NOT session-unlocked: both commands fail closed with Locked.
        let e1 = block_on(verify_note_sources_inner(&state, "m-vlock".to_string())).unwrap_err();
        assert!(
            matches!(e1, AppError::Locked(_)),
            "verify must fail Locked, got: {e1:?}"
        );
        let finding = crate::verify::VerifyFinding {
            line_no: 2,
            key: "PROJ-1".into(),
            verdict: crate::verify::Verdict::NotFound,
            detail: "PROJ-1 not found in Jira".into(),
            url: String::new(),
        };
        let e2 =
            apply_note_verify_markers_inner(&state, "m-vlock".to_string(), vec![finding]).unwrap_err();
        assert!(
            matches!(e2, AppError::Locked(_)),
            "apply must fail Locked, got: {e2:?}"
        );

        // Session-unlock → the lock gate passes; verify now falls to the fail-closed connector gate
        // (no Jira configured ⇒ jira_lookup NeedsConsent ⇒ Unavailable), proving Locked was the gate.
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-vlock".to_string());
        let e3 = block_on(verify_note_sources_inner(&state, "m-vlock".to_string())).unwrap_err();
        assert!(
            matches!(e3, AppError::Unavailable(_)),
            "past the lock gate, an unconfigured Jira verify fails Unavailable, got: {e3:?}"
        );
    }

    /// Brain v2 L5 — the SESSION verify cache: a cached meeting returns its findings WITHOUT a
    /// second connector egress (RED-able: with the cache check removed, this call falls through
    /// to `jira_lookup` on an unexposed connector and errors `Unavailable`), and a RELOCK clears
    /// the cache (the next call is back on the connector path).
    #[test]
    fn verify_cache_returns_findings_and_relock_clears_it() {
        let state = build_state("verify-cache");
        state
            .db
            .insert_meeting(&Meeting {
                id: "m-vc".to_string(),
                started_at: "2026-07-10T09:00:00Z".to_string(),
                ended_at: None,
                title: Some("Sprint".to_string()),
                duration_s: 600,
                audio_path: None,
                status: MeetingStatus::Summarized,
                folder_id: None,
            })
            .unwrap();
        state
            .db
            .upsert_note(&NoteRecord {
                meeting_id: "m-vc".to_string(),
                provider_id: "claude_code".to_string(),
                markdown: "# N\n- Ship PROJ-1 by 2026-07-08\n".to_string(),
                created_at: "2026-07-10T09:10:00Z".to_string(),
                exported_path: None,
                model_requested: None,
                model_served: None,
                gateway_host: None,
            })
            .unwrap();

        let finding = crate::verify::VerifyFinding {
            line_no: 2,
            key: "PROJ-1".into(),
            verdict: crate::verify::Verdict::Confirmed,
            detail: "PROJ-1 · Status: Done".into(),
            url: String::new(),
        };
        state
            .verify_cache
            .lock()
            .unwrap()
            .insert("m-vc".to_string(), vec![finding.clone()]);

        // Cache HIT: findings return WITHOUT touching the (unexposed) Jira connector.
        let got = block_on(verify_note_sources_inner(&state, "m-vc".to_string())).unwrap();
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].key, "PROJ-1");
        assert_eq!(got[0].detail, "PROJ-1 · Status: Done");

        // RELOCK-ALL clears the session cache → the next call is back on the connector path,
        // which fails closed Unavailable (no Jira exposed) — proving the cache is gone.
        relock_all_inner(&state).unwrap();
        assert!(
            state.verify_cache.lock().unwrap().is_empty(),
            "relock_all must clear the verify cache"
        );
        let e = block_on(verify_note_sources_inner(&state, "m-vc".to_string())).unwrap_err();
        assert!(
            matches!(e, AppError::Unavailable(_)),
            "post-relock the cache is empty ⇒ the connector gate speaks again, got: {e:?}"
        );
    }

    /// Lock-security NIT promotion (the adversarial verifier's probe A, 2026-07-10): a SEALED and
    /// NOT-session-unlocked meeting with a POISONED verify-cache entry must still refuse
    /// `Err(Locked)` — the gate runs BEFORE the cache is read, so a cache hit can never leak
    /// findings for a locked meeting. RED-able: hoisting the cache check above the lock gate in
    /// `verify_note_sources_inner` returns the poisoned findings here instead of `Locked`.
    #[test]
    fn verify_cache_is_never_read_for_a_sealed_meeting() {
        let state = build_state("verify-cache-lockgate");
        make_open_folder(&state.db, "f-vcl", "Secret");
        state
            .db
            .insert_meeting(&Meeting {
                id: "m-vcl".to_string(),
                started_at: "2026-07-10T09:00:00Z".to_string(),
                ended_at: None,
                title: Some("Sprint".to_string()),
                duration_s: 600,
                audio_path: None,
                status: MeetingStatus::Summarized,
                folder_id: Some("f-vcl".to_string()),
            })
            .unwrap();
        state
            .db
            .upsert_note(&NoteRecord {
                meeting_id: "m-vcl".to_string(),
                provider_id: "claude_code".to_string(),
                markdown: "# N\n- Ship PROJ-1 by 2026-07-08\n".to_string(),
                created_at: "2026-07-10T09:10:00Z".to_string(),
                exported_path: None,
                model_requested: None,
                model_served: None,
                gateway_host: None,
            })
            .unwrap();
        state.db.set_note_folder("m-vcl", Some("f-vcl")).unwrap();
        state
            .db
            .set_folder_locked("f-vcl", true, Some(&b"wrapped"[..]))
            .unwrap();
        // Poison the cache as if an earlier (unlocked) session had populated it and a relock's
        // cache-clear were somehow missed.
        state.verify_cache.lock().unwrap().insert(
            "m-vcl".to_string(),
            vec![crate::verify::VerifyFinding {
                line_no: 2,
                key: "PROJ-1".into(),
                verdict: crate::verify::Verdict::Confirmed,
                detail: "POISONED — must never surface for a locked meeting".into(),
                url: String::new(),
            }],
        );
        let e = block_on(verify_note_sources_inner(&state, "m-vcl".to_string())).unwrap_err();
        assert!(
            matches!(e, AppError::Locked(_)),
            "the lock gate must speak BEFORE the cache is consulted, got: {e:?}"
        );
        // The poisoned entry is untouched — proof the refusal came from the gate, not from a
        // cache miss/clear (relock_folder/relock_all own the clearing in real flows).
        assert!(
            state.verify_cache.lock().unwrap().contains_key("m-vcl"),
            "the entry must still be present: the gate refused without reading the cache"
        );
    }

    /// Brain v2 L5 — `apply_note_verify_markers` persists the inline markers AND the consolidated
    /// `> [!verify]-` callout into the CANONICAL DB note markdown, idempotently (re-applying never
    /// stacks either region), and an empty-findings apply restores the original note byte-exact.
    #[test]
    fn apply_verify_markers_persists_callout_idempotently_and_undoes() {
        let state = build_state("verify-callout-persist");
        let original = "# N\n- Ship PROJ-1 by 2026-07-08\n- other line\n";
        state
            .db
            .insert_meeting(&Meeting {
                id: "m-cb".to_string(),
                started_at: "2026-07-10T09:00:00Z".to_string(),
                ended_at: None,
                title: Some("Sprint".to_string()),
                duration_s: 600,
                audio_path: None,
                status: MeetingStatus::Summarized,
                folder_id: None,
            })
            .unwrap();
        state
            .db
            .upsert_note(&NoteRecord {
                meeting_id: "m-cb".to_string(),
                provider_id: "claude_code".to_string(),
                markdown: original.to_string(),
                created_at: "2026-07-10T09:10:00Z".to_string(),
                exported_path: None,
                model_requested: None,
                model_served: None,
                gateway_host: None,
            })
            .unwrap();

        let finding = crate::verify::VerifyFinding {
            line_no: 2,
            key: "PROJ-1".into(),
            verdict: crate::verify::Verdict::Conflict,
            detail: "note says 2026-07-08, PROJ-1 due 2026-07-10".into(),
            url: "https://x/browse/PROJ-1".into(),
        };
        let once =
            apply_note_verify_markers_inner(&state, "m-cb".to_string(), vec![finding.clone()]).unwrap();
        assert!(
            once.markdown.contains("> ⧗ note says"),
            "inline marker present"
        );
        assert!(once.markdown.contains("> [!verify]- Source check (as of "));
        assert!(once.markdown.contains(
                                "> - ⧗ Conflict — note says 2026-07-08, PROJ-1 due 2026-07-10 (via Jira) — https://x/browse/PROJ-1"
                            ));
        // Persisted CANONICALLY (upsert_note): the DB row carries the callout, so it seals with
        // the note under a folder lock.
        let db_md = state
            .db
            .get_latest_note_for_meeting("m-cb")
            .unwrap()
            .unwrap()
            .markdown;
        assert_eq!(db_md, once.markdown);

        // Re-apply: neither region stacks (one inline marker, one fenced callout).
        let twice = apply_note_verify_markers_inner(&state, "m-cb".to_string(), vec![finding]).unwrap();
        assert_eq!(
            twice.markdown.matches("(via Jira)").count(),
            2,
            "1 marker + 1 callout line"
        );
        assert_eq!(twice.markdown.matches("[!verify]-").count(), 1);
        assert_eq!(twice.markdown.matches("<!-- murmur:verify -->").count(), 1);

        // Empty findings: markers + callout stripped, the ORIGINAL note restored byte-exact.
        let undone = apply_note_verify_markers_inner(&state, "m-cb".to_string(), Vec::new()).unwrap();
        assert_eq!(
            undone.markdown, original,
            "byte-exact undo through the command"
        );
    }

    /// `get_mcp_config` must emit a ready-to-paste Claude Code config: `type: "http"`, the
    /// localhost url, and — when `mcp_require_token` is ON (the default the server enforces) — an
    /// `Authorization: Bearer <token>` header with a NON-EMPTY token (fixes the `-32001 unauthorized`
    /// handshake). When the flag is OFF the server serves unauthenticated, so NO `headers` block is
    /// emitted (no stale/placeholder header). Runs in a debug/test build, so `get_or_create_mcp_token`
    /// mints into the dev-secrets file store — no Keychain, no `security` CLI.
    #[test]
    /// The wire contract for the status Settings branches on.
    ///
    /// `rust-tauri.md` §2b exists because a snake_case field arrives as `undefined` on the FE and
    /// the template silently takes the other branch. Here that branch is "the server is running" —
    /// so a naming slip would restore the exact lie this command was added to remove.
    fn mcp_status_dto_is_camel_case_on_the_wire() {
        let dto = super::McpStatusDto {
            state: crate::mcp::McpListenerState::PortInUse.as_wire().to_string(),
            port: crate::mcp::MCP_PORT,
        };
        let value = serde_json::to_value(&dto).unwrap();
        let object = value.as_object().unwrap();
        for key in object.keys() {
            assert!(
                !key.contains('_'),
                "IPC DTO key {key} must be camelCase, never snake_case"
            );
        }
        assert_eq!(object["state"], "portInUse");
        assert_eq!(object["port"], crate::mcp::MCP_PORT);
    }

    /// Each listener state has a DISTINCT wire value, and the round-trip through the atomic
    /// encoding preserves it.
    ///
    /// `portInUse` and `unavailable` must never collapse into one: they carry different
    /// instructions ("quit the other app" vs "restart Murmur"), and the first one recovers by
    /// itself while the second does not.
    #[test]
    fn every_mcp_listener_state_has_its_own_wire_value() {
        use crate::mcp::McpListenerState::*;
        let all = [Starting, Listening, PortInUse, Unavailable];
        let wires: Vec<&str> = all.iter().map(|s| s.as_wire()).collect();
        let mut unique = wires.clone();
        unique.sort_unstable();
        unique.dedup();
        assert_eq!(unique.len(), all.len(), "wire values collided: {wires:?}");

        let status = crate::mcp::McpListenerStatus::default();
        assert_eq!(status.get(), Starting, "an unwritten status is never Listening");
    }

    #[test]
    fn get_mcp_config_carries_token_when_required_and_omits_it_when_off() {
        let state = build_state("mcp-config");

        // require_token ON (default) → type/url present + a real bearer token in headers.
        state.config.lock().unwrap().mcp_require_token = true;
        let on = get_mcp_config_inner(&state).unwrap();
        let v_on: serde_json::Value = serde_json::from_str(&on).expect("config is valid JSON");
        let server = &v_on["mcpServers"]["murmur"];
        assert_eq!(server["type"], "http", "config must declare type: http");
        assert_eq!(
            server["url"],
            format!("http://127.0.0.1:{}", crate::mcp::MCP_PORT),
            "config url must be the localhost MCP address"
        );
        let auth = server["headers"]["Authorization"]
            .as_str()
            .expect("Authorization header present when token required");
        let bearer = auth
            .strip_prefix("Bearer ")
            .expect("Authorization is a Bearer header");
        assert!(
            !bearer.is_empty(),
            "the bearer token must be non-empty (never a placeholder), got: {auth:?}"
        );

        // require_token OFF → the server is unauthenticated, so NO headers block is emitted.
        state.config.lock().unwrap().mcp_require_token = false;
        let off = get_mcp_config_inner(&state).unwrap();
        let v_off: serde_json::Value = serde_json::from_str(&off).expect("config is valid JSON");
        let server_off = &v_off["mcpServers"]["murmur"];
        assert_eq!(server_off["type"], "http");
        assert!(
            server_off.get("headers").is_none(),
            "no Authorization header when the token flag is off, got: {off}"
        );
    }

    /// The shipped skill catalog must list every tool the server actually registers.
    ///
    /// `vault-skills/murmur-mcp/SKILL.md` is not documentation about the product — the setup guide
    /// tells the user to copy it into `~/.claude/skills/`, where a real agent loads it as operating
    /// instructions. It described nine tools while `tools_spec()` registered twenty, so eleven were
    /// invisible to every agent that followed it: an agent cannot call a tool it was never told
    /// about, and it has no way to discover the omission.
    #[test]
    fn the_shipped_skill_catalog_lists_every_registered_mcp_tool() {
        let repo = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("repo root");
        let skill = std::fs::read_to_string(repo.join("vault-skills/murmur-mcp/SKILL.md"))
            .expect("read the shipped MCP skill");

        let spec = crate::mcp::tools_spec();
        let registered: Vec<String> = spec
            .as_array()
            .expect("tools_spec is an array")
            .iter()
            .map(|tool| {
                tool["name"]
                    .as_str()
                    .expect("every tool has a name")
                    .to_string()
            })
            .collect();
        assert!(
            registered.len() >= 20,
            "tools_spec shrank unexpectedly ({}) — check this test still means what it says",
            registered.len()
        );

        let missing: Vec<&String> = registered
            .iter()
            // `name(` — the invocation-example shape every real catalog entry uses — rather than
            // a bare `name`. Review removed one tool's whole entry, left a stray cross-reference to
            // it in another entry's prose, and the bare-name check accepted that. The file's own
            // convention already cross-references tools by name inside other entries, so a bare
            // mention genuinely cannot distinguish "documented" from "alluded to".
            .filter(|name| !skill.contains(&format!("`{name}(")))
            .collect();
        assert!(
            missing.is_empty(),
            "vault-skills/murmur-mcp/SKILL.md does not mention {missing:?}. That file is COPIED \
             INTO an agent's skills directory and read as instructions, so a tool missing from it \
             is a tool no agent will ever call. Add it to the catalog."
        );
    }

    /// The config we DOCUMENT must be the config we EMIT.
    ///
    /// `get_mcp_config_carries_token_when_required_and_omits_it_when_off` above already pins what
    /// the code produces, and it always passed — the code was never the problem. What drifted was
    /// the prose: README told the reader a bearer token is required by default and then printed a
    /// snippet with no token in it, so the line people copy was the one the server answers `401`
    /// to, and both snippets were also missing `type: http`.
    ///
    /// The assertion is scoped to the SNIPPET, not the file. A first version searched whole files,
    /// and review broke it immediately: revert the real snippet to the broken form, drop the
    /// required words into an HTML comment elsewhere on the page, and the test went green on the
    /// exact bug it exists to catch. A whole-file `contains` in a large, growing document proves
    /// nothing — some other section will eventually mention `Bearer` for unrelated reasons.
    #[test]
    fn the_documented_mcp_snippets_carry_what_the_server_requires() {
        let repo = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("repo root");

        /// Every documented block that configures the MCP server. Markdown fences and the landing
        /// page's `<pre>` are both bounded by their own delimiters.
        ///
        /// Returns ALL of them rather than the first, because first-match-wins was a bypass:
        /// review broke the real snippet and put a satisfying decoy block EARLIER in the same file,
        /// and the check went green on the historical bug. The caller therefore refuses ambiguity
        /// instead of guessing which block the reader will copy.
        fn mcp_blocks<'a>(text: &'a str, open: &str, close: &str) -> Vec<&'a str> {
            let mut found = Vec::new();
            let mut rest = text;
            while let Some(start) = rest.find(open) {
                let after = &rest[start + open.len()..];
                let Some(end) = after.find(close) else {
                    // An opener with no closer anywhere after it is a THIRD kind of ambiguity, and
                    // it gets the same answer as the other two. Breaking here quietly kept whatever
                    // had already been collected, which review turned into a bypass: delete the real
                    // snippet's closing tag, put a well-formed decoy earlier, and the scan never
                    // learns the real region exists.
                    return Vec::new();
                };
                let block = &after[..end];
                if block.contains("mcpServers") {
                    found.push(block);
                }
                rest = &after[end + close.len()..];
            }
            found
        }

        for (relative, open, close, needles) in [
            (
                "README.md",
                "```",
                "```",
                vec!["\"type\": \"http\"", "\"Authorization\": \"Bearer"],
            ),
            (
                "docs/USE-WITH-YOUR-AGENT.md",
                "```",
                "```",
                vec!["\"type\": \"http\"", "\"Authorization\": \"Bearer"],
            ),
            (
                "landing/docs.html",
                "<pre class=\"code-block\">",
                "</pre>",
                vec![">\"type\"<", ">\"http\"<", ">\"Authorization\"<", "Bearer"],
            ),
        ] {
            let path = repo.join(relative);
            let text = std::fs::read_to_string(&path)
                .unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
            let blocks = mcp_blocks(&text, open, close);
            assert_eq!(
                blocks.len(),
                1,
                "{relative} should document exactly ONE `mcpServers` block; found {}. With more \
                 than one there is no way to tell which the reader copies, and a satisfying decoy \
                 would let a broken real snippet pass. With none, the documentation this test \
                 exists to police is gone.",
                blocks.len()
            );
            let block = blocks[0];
            for needle in needles {
                assert!(
                    block.contains(needle),
                    "{relative}'s MCP snippet is missing {needle:?}. The server requires a bearer \
                     token by default and Claude Code needs `type: http`, so a reader who copies \
                     this block gets a 401 or an entry that is never treated as an HTTP server. \
                     Copy what `get_mcp_config_inner` emits."
                );
            }
        }
    }

    /// ENRICH lock gate (RED-before-GREEN): both `enrich_note_context` (read/egress) and
    /// `apply_note_enrichment` (write) MUST refuse a SEALED-and-not-session-unlocked meeting with
    /// `AppError::Locked` BEFORE any note read / connector egress / write. With NO connectors
    /// configured, once unlocked the preview returns an empty vec (nothing to add — graceful),
    /// proving Locked was the FIRST gate.
    #[test]
    fn enrich_commands_refuse_a_sealed_meeting() {
        let state = build_state("enrich-lockgate");
        make_open_folder(&state.db, "f-elock", "Secret");
        state
            .db
            .insert_meeting(&Meeting {
                id: "m-elock".to_string(),
                started_at: "2026-07-05T09:00:00Z".to_string(),
                ended_at: None,
                title: Some("Sprint".to_string()),
                duration_s: 600,
                audio_path: None,
                status: MeetingStatus::Summarized,
                folder_id: Some("f-elock".to_string()),
            })
            .unwrap();
        state
            .db
            .upsert_note(&NoteRecord {
                meeting_id: "m-elock".to_string(),
                provider_id: "claude_code".to_string(),
                markdown: "# N\n- Ship PROJ-1 by 2026-07-08\n".to_string(),
                created_at: "2026-07-05T09:10:00Z".to_string(),
                exported_path: None,
                model_requested: None,
                model_served: None,
                gateway_host: None,
            })
            .unwrap();
        state
            .db
            .set_note_folder("m-elock", Some("f-elock"))
            .unwrap();
        state
            .db
            .set_folder_locked("f-elock", true, Some(&b"wrapped"[..]))
            .unwrap();

        // Sealed → both refuse Locked before any egress/write.
        let e1 = block_on(enrich_note_context_inner(&state, "m-elock".to_string())).unwrap_err();
        assert!(
            matches!(e1, AppError::Locked(_)),
            "preview must fail Locked, got: {e1:?}"
        );
        let hit = crate::enrich::ContextHit {
            source: "Jira".into(),
            detail: "PROJ-1 · Done".into(),
            url: None,
        };
        let e2 = apply_note_enrichment_inner(&state, "m-elock".to_string(), vec![hit]).unwrap_err();
        assert!(
            matches!(e2, AppError::Locked(_)),
            "apply must fail Locked, got: {e2:?}"
        );

        // Session-unlock → the lock gate passes; with no connectors the preview is graceful-empty.
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-elock".to_string());
        let hits = block_on(enrich_note_context_inner(&state, "m-elock".to_string())).unwrap();
        assert!(
            hits.is_empty(),
            "no connectors configured ⇒ nothing to enrich, got: {hits:?}"
        );
    }

    /// The enrich WRITE path persists a reviewed context block into the canonical DB note and
    /// strips it byte-exact on an empty apply — through the real command tail (upsert + re-export).
    #[test]
    fn apply_note_enrichment_writes_then_strips_byte_exact() {
        let state = build_state("enrich-write");
        make_open_folder(&state.db, "f-open", "Project");
        seed_meeting(
            &state.db,
            "m1",
            "# Notes\n- decided to ship\n",
            Some("f-open"),
        );
        let original = state
            .db
            .get_latest_note_for_meeting("m1")
            .unwrap()
            .unwrap()
            .markdown;

        let hits = vec![crate::enrich::ContextHit {
            source: "Jira".into(),
            detail: "PROJ-1 · In Progress".into(),
            url: Some("https://x/browse/PROJ-1".into()),
        }];
        let dto = apply_note_enrichment_inner(&state, "m1".to_string(), hits).unwrap();
        assert!(
            dto.markdown.contains("> [!context]-"),
            "the context callout was written"
        );
        assert!(
            dto.markdown.contains("PROJ-1 · In Progress (via Jira)"),
            "loud attribution present"
        );
        assert!(
            dto.markdown.starts_with(&original),
            "the original note is preserved verbatim"
        );
        // The DB note now carries the block.
        assert!(state
            .db
            .get_latest_note_for_meeting("m1")
            .unwrap()
            .unwrap()
            .markdown
            .contains("[!context]-"));

        // Empty apply strips it byte-exact back to the original.
        let undone = apply_note_enrichment_inner(&state, "m1".to_string(), vec![]).unwrap();
        assert_eq!(
            undone.markdown, original,
            "empty enrichment strips the block byte-for-byte"
        );
    }

    /// Stage 2 / Lane A is now a NO-OP: the machine `murmur:links` block was retired (it went stale +
    /// rendered as raw junk in the editor; the RELATED panel reads the live `links` table instead). So
    /// `link_related_notes_inner` over a FINISHED note in an OPEN folder must leave the note body
    /// EXACTLY as it was — no `> [!related]-` block written. (Was RED before this change: the pass used
    /// to append the block; now it writes nothing.)
    #[test]
    fn link_related_notes_writes_no_body_block() {
        let state = build_state("lanea-noop");
        make_open_folder(&state.db, "f-open", "Project");
        seed_meeting(&state.db, "this", "Apollo migration.\n", Some("f-open"));
        state
            .db
            .set_meeting_title("this", "Apollo Migration")
            .unwrap();
        // A related PRIOR note the OLD pass WOULD have retrieved + rendered into the block.
        seed_meeting(
            &state.db,
            "prior",
            "## Summary\n\nApollo migration groundwork and rollout roadmap.\n",
            Some("f-open"),
        );
        state
            .db
            .set_meeting_title("prior", "Apollo Kickoff")
            .unwrap();

        let before = state
            .db
            .get_latest_note_for_meeting("this")
            .unwrap()
            .unwrap()
            .markdown;
        link_related_notes_inner(&state, "this").unwrap();
        let after = state
            .db
            .get_latest_note_for_meeting("this")
            .unwrap()
            .unwrap()
            .markdown;

        assert_eq!(
            after, before,
            "Lane A is a no-op — the note body is unchanged"
        );
        assert!(
            !after.contains("murmur:links"),
            "no managed links block is written into the note body; got: {after}"
        );
        assert!(
            !after.contains("> [!related]-"),
            "no Related-notes callout is written; got: {after}"
        );
    }

    /// SEAL-SAFETY: Lane A is a no-op AND never touches a SEALED note's transient `markdown` column
    /// even when the session has its folder unlocked (so the `meeting_is_unlocked` read gate passes).
    /// The sealed column stays blank and `content_blob` stays intact.
    #[test]
    fn link_related_notes_never_touches_a_sealed_note() {
        let state = build_state("lanea-sealsafe");
        make_open_folder(&state.db, "f-lock", "Secret");
        seed_meeting(&state.db, "sealed", "# Secret body\n", Some("f-lock"));
        state
            .db
            .set_meeting_title("sealed", "Atlas Acquisition Roadmap")
            .unwrap();
        // A visible related note in an OPEN folder that the sealed meeting's title WOULD retrieve.
        make_open_folder(&state.db, "f-open", "Open");
        seed_meeting(
            &state.db,
            "prior",
            "## Summary\n\nAtlas acquisition roadmap groundwork.\n",
            Some("f-open"),
        );
        state
            .db
            .set_meeting_title("prior", "Atlas Kickoff")
            .unwrap();

        // Seal the note (content_blob present, markdown blanked), lock the folder, and SESSION-UNLOCK it
        // so the read gate passes.
        state
            .db
            .seal_note("sealed", "claude_code", &b"ciphertext-blob"[..])
            .unwrap();
        state
            .db
            .set_folder_locked("f-lock", true, Some(&b"wrapped"[..]))
            .unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-lock".to_string());

        assert!(
            meeting_is_unlocked(&state, "sealed").unwrap(),
            "precondition: the sealed meeting is session-unlocked (so meeting_is_unlocked passes)"
        );
        link_related_notes_inner(&state, "sealed").unwrap();

        // The sealed note's transient markdown column is untouched (still blank) — no plaintext links.
        let md = state
            .db
            .get_latest_note_for_meeting("sealed")
            .unwrap()
            .unwrap()
            .markdown;
        assert_eq!(
            md, "",
            "a sealed note's transient markdown column must NEVER be written by Lane A"
        );
        // The seal (content_blob) is intact.
        assert!(
            state
                .db
                .sealable_notes_for_meeting("sealed")
                .unwrap()
                .iter()
                .any(|n| n.content_blob.is_some()),
            "the seal (content_blob) is left intact"
        );
    }

    // ── note↔meeting-links PR-1 — MANUAL linking (command layer) ─────────────────────────────────

    /// Seed a standalone note-doc (`kind='note'`) in a folder for the manual-link command tests. The
    /// folder must already exist in the `folders` table (via `make_open_folder`) so the read gates
    /// (`get_note_row` → `folder_is_unlocked`) resolve it.
    fn seed_note_doc_cmd(db: &Db, id: &str, folder_id: &str, title: &str, body: &str) {
        db.insert_note(id, folder_id, title, title, body, 1_700_000_000_000)
            .unwrap();
    }

    /// Count the `manual` rows incident on `(kind, id)` (either endpoint).
    fn manual_link_count(state: &AppState, kind: &str, id: &str) -> i64 {
        state.db.link_edge_count(kind, id, "manual")
    }

    #[test]
    fn link_items_command_allows_org_to_org_except_exact_self() {
        const SECOND_ORG_ID: &str = "22222222-2222-4222-8222-222222222222";
        const SAME_ORG_DOC_ID: &str = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
        const CROSS_ORG_DOC_ID: &str = "cccccccc-cccc-4ccc-8ccc-cccccccccccc";

        fn seed_current_head(state: &AppState, item_id: &str, org_id: &str, doc_id: &str, title: &str) {
            state
                .db
                .upsert_org_item(
                    item_id,
                    org_id,
                    1,
                    "colleague",
                    title,
                    "visible shared body",
                    "2026-08-13T00:00:00Z",
                    1,
                    1,
                    &[9u8; 32],
                    Some("document"),
                    Some("colleague-user-id"),
                    None,
                )
                .unwrap();
            state
                .db
                .set_org_item_document_metadata(
                    item_id,
                    Some(doc_id),
                    "view",
                    Some("colleague-user-id"),
                )
                .unwrap();
            state
                .db
                .repair_org_reconcile_metadata(
                    item_id,
                    org_id,
                    1,
                    Some(doc_id),
                    "view",
                    Some("colleague-user-id"),
                    true,
                )
                .unwrap();
        }

        let state = build_state("link-org-to-org-command");
        seed_org(&state.db, STABLE_ORG_ID, "Alpha org", "member", 1);
        seed_org(&state.db, SECOND_ORG_ID, "Beta org", "member", 1);
        seed_current_head(
            &state,
            "item-org-source",
            STABLE_ORG_ID,
            STABLE_DOC_ID,
            "Org source",
        );
        seed_current_head(
            &state,
            "item-org-same-target",
            STABLE_ORG_ID,
            SAME_ORG_DOC_ID,
            "Same-org target",
        );
        seed_current_head(
            &state,
            "item-org-cross-target",
            SECOND_ORG_ID,
            CROSS_ORG_DOC_ID,
            "Cross-org target",
        );

        let source = format!("{STABLE_ORG_ID}:{STABLE_DOC_ID}");
        let same_org_target = format!("{STABLE_ORG_ID}:{SAME_ORG_DOC_ID}");
        let cross_org_target = format!("{SECOND_ORG_ID}:{CROSS_ORG_DOC_ID}");
        link_items_inner(&state, "org", &source, "org", &same_org_target).unwrap();
        link_items_inner(&state, "org", &source, "org", &cross_org_target).unwrap();

        let exact_directed_count = |src_id: &str, dst_id: &str| -> i64 {
            state
                .db
                .lock()
                .query_row(
                    "SELECT COUNT(*) FROM links
                          WHERE src_kind = 'org' AND src_id = ?1
                            AND dst_kind = 'org' AND dst_id = ?2
                            AND edge_type = 'manual' AND status = 'active'",
                    rusqlite::params![src_id, dst_id],
                    |row| row.get(0),
                )
                .unwrap()
        };
        assert_eq!(exact_directed_count(&source, &same_org_target), 1);
        assert_eq!(exact_directed_count(&source, &cross_org_target), 1);
        assert_eq!(exact_directed_count(&same_org_target, &source), 0);
        assert_eq!(exact_directed_count(&cross_org_target, &source), 0);

        assert!(matches!(
            link_items_inner(&state, "org", &source, "org", &source),
            Err(AppError::InvalidArg(_))
        ));
        assert_eq!(manual_link_count(&state, "org", &source), 2);
    }

    /// A MEETING source creates a `manual` row but writes NO markdown into the meeting's note (a
    /// meeting has no owned editable body — row only, per fork #2).
    #[test]
    fn link_from_meeting_creates_row_but_no_markdown() {
        let state = build_state("link-from-meeting");
        make_open_folder(&state.db, "f-open", "Project");
        seed_meeting(&state.db, "m1", "# Meeting note body\n", Some("f-open"));
        state.db.set_meeting_title("m1", "Kickoff").unwrap();
        seed_note_doc_cmd(&state.db, "n1", "f-open", "Design Doc", "the design body");

        let before = state
            .db
            .get_latest_note_for_meeting("m1")
            .unwrap()
            .unwrap()
            .markdown;

        // Link meeting m1 → note n1.
        link_items_inner(&state, "meeting", "m1", "note", "n1").unwrap();

        // A manual row exists...
        assert_eq!(
            manual_link_count(&state, "meeting", "m1"),
            1,
            "manual row created"
        );
        // ...and the meeting's note markdown is UNTOUCHED (no injected [[...]] / links block).
        let after = state
            .db
            .get_latest_note_for_meeting("m1")
            .unwrap()
            .unwrap()
            .markdown;
        assert_eq!(after, before, "a meeting source writes no markdown");
        assert!(
            !after.contains("murmur:links"),
            "no managed links block injected into a meeting source"
        );
    }

    /// A NOTE source creates a `manual` edge and writes NO note body (the `murmur:links` block was
    /// retired). The link is GRAPH-ONLY: `links_for_visible` shows ONE manual chip, the source body is
    /// byte-unchanged, and no machine block is injected. (RED before this change: `link_items` used to
    /// materialize `[[Target Note]]` into the body.)
    #[test]
    fn link_from_note_creates_edge_without_body_block() {
        let state = build_state("link-from-note");
        make_open_folder(&state.db, "f-open", "Project");
        seed_note_doc_cmd(&state.db, "src", "f-open", "Source Note", "original body\n");
        seed_note_doc_cmd(&state.db, "dst", "f-open", "Target Note", "target body");

        let before = state.db.get_note_row("src").unwrap().unwrap().text;
        // Link note src → note dst.
        link_items_inner(&state, "note", "src", "note", "dst").unwrap();

        // A manual row exists...
        assert_eq!(
            manual_link_count(&state, "note", "src"),
            1,
            "manual row created"
        );
        // ...and the source note body is UNCHANGED — no [[Target Note]] / links block materialized.
        let body = state.db.get_note_row("src").unwrap().unwrap().text;
        assert_eq!(
            body, before,
            "the note body is byte-unchanged (no materialize); got: {body}"
        );
        assert!(
            !body.contains("murmur:links") && !body.contains("[[Target Note]]"),
            "no managed links block injected into the source note; got: {body}"
        );
        // No `wikilink` edge is derived either (the body block that produced it is gone).
        assert_eq!(
            link_count_in(&state, "note", "src", "wikilink"),
            0,
            "no derived wikilink edge"
        );

        // The manual edge is the visible chip (removable-manual), from the source side.
        let unlocked = unlocked_snapshot(&state).unwrap();
        let edges = state
            .db
            .links_for_visible(crate::links::LinkKind::Note, "src", &unlocked)
            .unwrap();
        let to_dst: Vec<_> = edges.iter().filter(|e| e.other_id == "dst").collect();
        assert_eq!(to_dst.len(), 1, "exactly one chip for the pair");
        assert!(to_dst[0].manual, "the chip is flagged removable-manual");
    }

    /// Exact dashboard history expands visible linked neighbours. The derived-wikilink replacement
    /// must therefore share the lifecycle interval used by dashboard-history authorization and
    /// hydration: it cannot replace the live edge set while that exact witness is being consumed.
    #[test]
    fn derived_wikilink_replacement_waits_for_history_lifecycle_interval() {
        let state = Arc::new(build_state("wikilink-history-lifecycle"));
        make_open_folder(&state.db, "f-open", "Project");
        seed_note_doc_cmd(
            &state.db,
            "src",
            "f-open",
            "Source Note",
            "See [[Target Note]].",
        );
        seed_note_doc_cmd(&state.db, "dst", "f-open", "Target Note", "target body");

        let lifecycle = lifecycle_guard(state.as_ref());
        let worker_state = Arc::clone(&state);
        let (started_tx, started_rx) = std::sync::mpsc::channel();
        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            started_tx.send(()).unwrap();
            index_wikilinks_best_effort(
                worker_state.as_ref(),
                crate::links::LinkKind::Note,
                "src",
                "See [[Target Note]].",
            );
            done_tx.send(()).unwrap();
        });

        started_rx.recv().unwrap();
        assert!(
            done_rx
                .recv_timeout(std::time::Duration::from_millis(100))
                .is_err(),
            "derived link replacement must wait for an active history lifecycle interval"
        );
        assert_eq!(
            link_count_in(&state, "note", "src", "wikilink"),
            0,
            "no linked-neighbour membership may change before history hydration releases the interval"
        );

        drop(lifecycle);
        done_rx.recv().unwrap();
        worker.join().unwrap();
        assert_eq!(
            link_count_in(&state, "note", "src", "wikilink"),
            1,
            "the replacement lands after the history lifecycle interval"
        );
    }

    /// Helper mirroring db.rs `link_count` for the command-test module.
    fn link_count_in(state: &AppState, kind: &str, id: &str, edge_type: &str) -> i64 {
        state.db.link_edge_count(kind, id, edge_type)
    }

    /// UNLINK removes the `manual` row. A fresh link writes NO body marker (block retired), so unlink's
    /// body is byte-unchanged. The legacy-cleanup strip is still wired for a note that carries a
    /// PRE-EXISTING `[[Title]]` marker (imported before the block was retired): unlink removes the row
    /// AND strips that stale marker.
    #[test]
    fn unlink_removes_row_and_strips_legacy_marker() {
        let state = build_state("unlink-strips");
        make_open_folder(&state.db, "f-open", "Project");
        // A SOURCE note that already carries a LEGACY managed links block referencing the target (as an
        // old note would). `apply_link_markers` renders exactly the block the retired path used to.
        let legacy_hit = crate::enrich::ContextHit {
            source: "note".to_string(),
            detail: "[[Target Note]]".to_string(),
            url: None,
        };
        let legacy_body =
            crate::enrich::apply_link_markers("original body\n", std::slice::from_ref(&legacy_hit));
        assert!(
            legacy_body.contains("[[Target Note]]"),
            "precondition: legacy marker seeded"
        );
        seed_note_doc_cmd(&state.db, "src", "f-open", "Source Note", &legacy_body);
        seed_note_doc_cmd(&state.db, "dst", "f-open", "Target Note", "target body");

        link_items_inner(&state, "note", "src", "note", "dst").unwrap();
        assert_eq!(
            manual_link_count(&state, "note", "src"),
            1,
            "precondition: manual row exists"
        );

        // Unlink note src → note dst.
        unlink_items_inner(&state, "note", "src", "note", "dst").unwrap();

        // The manual row is gone...
        assert_eq!(
            manual_link_count(&state, "note", "src"),
            0,
            "manual row deleted"
        );
        // ...and the stale legacy [[Target Note]] marker is stripped from the body (legacy cleanup).
        let body = state.db.get_note_row("src").unwrap().unwrap().text;
        assert!(
            !body.contains("[[Target Note]]") && !body.contains("murmur:links"),
            "the legacy marker + block are stripped on unlink; got: {body}"
        );
        assert_eq!(
            body, "original body\n",
            "the original prose is restored byte-exact after strip; got: {body}"
        );
    }

    /// Lock-review regression: marker scrub + vault-cleanup intent commit before the exact manual
    /// edge disappears. Force a real destination relock immediately after that DB boundary.
    #[test]
    fn unlink_prepares_marker_cleanup_before_destination_relock() {
        let vault = tmp_vault("unlink-marker-relock").canonicalize().unwrap();
        let state = build_state_with_vault("unlink-marker-relock", &vault);
        state
            .db
            .set_setting("vault_path", &vault.to_string_lossy())
            .unwrap();
        let source_folder = create_note_folder_inner(&state, "Open source", None)
            .unwrap()
            .id;
        let destination_folder = create_note_folder_inner(&state, "Locked target", None)
            .unwrap()
            .id;
        let source = create_note_inner(&state, Some(&source_folder), "Source").unwrap();
        let destination = create_note_inner(&state, Some(&destination_folder), "Sealed Title").unwrap();
        update_note_doc_inner(&state, &destination, "Sealed Title", "private target body").unwrap();

        lock_folder_inner(&state, destination_folder.clone()).unwrap();
        let kek = secrets::get_or_create_master_kek().unwrap();
        let wrapped = state
            .db
            .folder_wrapped_key(&destination_folder)
            .unwrap()
            .unwrap();
        let ck_vec =
            crate::crypto::decrypt(&kek, &wrapped, &aad_wrapped_ck(&destination_folder)).unwrap();
        let ck: [u8; 32] = ck_vec.try_into().expect("CK is 32 bytes");
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        unseal_folder_extras(&state, &destination_folder, &ck, None).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(destination_folder.clone());

        let legacy_hit = crate::enrich::ContextHit {
            source: "note".to_string(),
            detail: "[[Sealed Title]]".to_string(),
            url: None,
        };
        let legacy_body = crate::enrich::apply_link_markers(
            "source prose stays\n",
            std::slice::from_ref(&legacy_hit),
        );
        update_note_doc_inner(&state, &source, "Source", &legacy_body).unwrap();
        let exported = state
            .db
            .get_note_row(&source)
            .unwrap()
            .unwrap()
            .exported_path
            .expect("source note exported");
        assert!(std::fs::read_to_string(&exported)
            .unwrap()
            .contains("[[Sealed Title]]"));

        // Model the legacy-marker-only shape from the finding: the managed block remains in the
        // canonical body/export, but there is no derived wikilink row for relock to discover after
        // the last manual edge disappears.
        state
            .db
            .index_wikilinks_for_source(
                crate::links::LinkKind::Note,
                &source,
                "source prose stays\n",
                &std::collections::HashSet::new(),
            )
            .unwrap();
        assert_eq!(state.db.link_edge_count("note", &source, "wikilink"), 0);

        link_items_inner(&state, "note", &source, "note", &destination).unwrap();
        let edge = crate::storage::models::ManualLinkEdge {
            src_kind: "note".into(),
            src_id: source.clone(),
            dst_kind: "note".into(),
            dst_id: destination.clone(),
        };

        // Exact boundary under test: deletion committed, then the destination relocks before a
        // separate unlink cleanup turn. The DB scrub/outbox must already be durable.
        state.db.delete_manual_links(&[edge]).unwrap();
        assert_eq!(manual_link_count(&state, "note", &source), 0);
        relock_all_inner(&state).unwrap();

        let stored = state.db.get_note_row(&source).unwrap().unwrap().text;
        assert!(
            !stored.contains("[[Sealed Title]]"),
            "DB source must be scrubbed before edge deletion: {stored:?}"
        );
        let on_disk = std::fs::read_to_string(&exported).unwrap();
        assert!(
            !on_disk.contains("[[Sealed Title]]"),
            "relock must drain the durable scrub for the exact vault export: {on_disk:?}"
        );
        assert!(state
            .db
            .pending_lock_marker_export_cleanup()
            .unwrap()
            .is_empty());

        let _ = std::fs::remove_dir_all(&vault);
    }

    /// A storage caller without command-layer CK authority cannot mutate a legacy marker in a
    /// durably locked source. The missing verified fresh seal rolls back marker/outbox/edge changes.
    #[test]
    fn unlink_marker_cleanup_without_locked_source_seal_rolls_back() {
        let state = build_state("unlink-marker-locked-source-refusal");
        make_open_folder(&state.db, "f-source", "Source");
        make_open_folder(&state.db, "f-target", "Target");
        let hit = crate::enrich::ContextHit {
            source: "note".into(),
            detail: "[[Target]]".into(),
            url: None,
        };
        let body = crate::enrich::apply_link_markers("source prose\n", &[hit]);
        seed_note_doc_cmd(&state.db, "source", "f-source", "Source", &body);
        seed_note_doc_cmd(&state.db, "target", "f-target", "Target", "target body");
        link_items_inner(&state, "note", "source", "note", "target").unwrap();
        state
            .db
            .set_folder_locked("f-source", true, Some(&b"wrapped"[..]))
            .unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-source".into());
        let edge = crate::storage::models::ManualLinkEdge {
            src_kind: "note".into(),
            src_id: "source".into(),
            dst_kind: "note".into(),
            dst_id: "target".into(),
        };

        let error = state.db.delete_manual_links(&[edge]).unwrap_err();
        assert!(matches!(error, AppError::Locked(_)), "got {error:?}");
        assert_eq!(manual_link_count(&state, "note", "source"), 1);
        assert!(state
            .db
            .get_note_row("source")
            .unwrap()
            .unwrap()
            .text
            .contains("[[Target]]"));
        assert!(state
            .db
            .pending_lock_marker_export_cleanup()
            .unwrap()
            .is_empty());
    }

    /// The command-owned path has CK authority: it verify-seals the scrubbed source text in the same
    /// unlink transaction. Relock + a second unseal restores the scrubbed bytes, not the stale blob.
    #[test]
    fn unlink_reseals_locked_source_marker_before_relock_round_trip() {
        let vault = tmp_vault("unlink-locked-source-roundtrip")
            .canonicalize()
            .unwrap();
        let state = build_state_with_vault("unlink-locked-source-roundtrip", &vault);
        state
            .db
            .set_setting("vault_path", &vault.to_string_lossy())
            .unwrap();
        let source_folder = create_note_folder_inner(&state, "Locked source", None)
            .unwrap()
            .id;
        let target_folder = create_note_folder_inner(&state, "Open target", None)
            .unwrap()
            .id;
        let source = create_note_inner(&state, Some(&source_folder), "Source").unwrap();
        let target = create_note_inner(&state, Some(&target_folder), "Target").unwrap();
        update_note_doc_inner(&state, &source, "Source", "initial source").unwrap();
        update_note_doc_inner(&state, &target, "Target", "target body").unwrap();

        lock_folder_inner(&state, source_folder.clone()).unwrap();
        let kek = secrets::get_or_create_master_kek().unwrap();
        let wrapped = state
            .db
            .folder_wrapped_key(&source_folder)
            .unwrap()
            .unwrap();
        let ck_vec = crate::crypto::decrypt(&kek, &wrapped, &aad_wrapped_ck(&source_folder)).unwrap();
        let ck: [u8; 32] = ck_vec.try_into().expect("CK is 32 bytes");
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        unseal_folder_extras(&state, &source_folder, &ck, None).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(source_folder.clone());
        reexport_notes_in_folder(&state, &source_folder);

        let hit = crate::enrich::ContextHit {
            source: "note".into(),
            detail: "[[Target]]".into(),
            url: None,
        };
        let marked = crate::enrich::apply_link_markers("source prose survives\n", &[hit]);
        update_note_doc_inner(&state, &source, "Source", &marked).unwrap();
        link_items_inner(&state, "note", &source, "note", &target).unwrap();

        unlink_items_inner(&state, "note", &source, "note", &target).unwrap();
        let scrubbed = state.db.get_note_row(&source).unwrap().unwrap();
        assert!(!scrubbed.text.contains("[[Target]]"));
        let scrubbed_export = scrubbed
            .exported_path
            .expect("source export survives unlink");
        assert!(!std::fs::read_to_string(&scrubbed_export)
            .unwrap()
            .contains("[[Target]]"));

        relock_all_inner(&state).unwrap();
        assert_eq!(state.db.get_note_row(&source).unwrap().unwrap().text, "");
        unseal_folder_extras(&state, &source_folder, &ck, None).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(source_folder.clone());
        reexport_notes_in_folder(&state, &source_folder);
        let restored = state.db.get_note_row(&source).unwrap().unwrap();
        assert_eq!(restored.text, "source prose survives\n");
        let restored_export = restored.exported_path.expect("restored source re-exported");
        assert!(!std::fs::read_to_string(restored_export)
            .unwrap()
            .contains("[[Target]]"));

        let _ = std::fs::remove_dir_all(&vault);
    }

    /// One displayed chip can hide an opposite-direction manual row plus a second manual row in the
    /// representative direction. Unlink consumes the exact tuple list atomically, while the derived
    /// wikilink survives and becomes a non-removable chip after refetch.
    #[test]
    fn unlink_collapsed_manual_set_preserves_derived_wikilink() {
        let state = build_state("unlink-collapsed-set");
        make_open_folder(&state.db, "f-open", "Project");
        seed_note_doc_cmd(&state.db, "left", "f-open", "Left", "see [[Right]]");
        seed_note_doc_cmd(&state.db, "right", "f-open", "Right", "right body");
        let unlocked = unlocked_snapshot(&state).unwrap();
        state
            .db
            .index_wikilinks_for_source(
                crate::links::LinkKind::Note,
                "left",
                "see [[Right]]",
                &unlocked,
            )
            .unwrap();
        link_items_inner(&state, "note", "left", "note", "right").unwrap();
        link_items_inner(&state, "note", "right", "note", "left").unwrap();

        let before = state
            .db
            .links_for_visible(crate::links::LinkKind::Note, "left", &unlocked)
            .unwrap();
        let chip = before.iter().find(|edge| edge.other_id == "right").unwrap();
        assert_eq!(chip.edge_type, "wikilink");
        assert_eq!(
            chip.manual_edges.len(),
            2,
            "both manual directions are folded"
        );

        unlink_manual_edges_inner(&state, "note", "left", "note", "right", &chip.manual_edges).unwrap();

        assert_eq!(link_count_in(&state, "note", "left", "manual"), 0);
        assert_eq!(link_count_in(&state, "note", "right", "manual"), 0);
        let after = state
            .db
            .links_for_visible(crate::links::LinkKind::Note, "left", &unlocked)
            .unwrap();
        let derived = after.iter().find(|edge| edge.other_id == "right").unwrap();
        assert_eq!(derived.edge_type, "wikilink", "derived relation survives");
        assert!(!derived.manual, "surviving wikilink is not removable");
        assert!(derived.manual_edges.is_empty());
        assert!(
            state
                .db
                .pending_lock_marker_export_cleanup()
                .unwrap()
                .is_empty(),
            "marker-free two-direction unlink must not enqueue filesystem work"
        );
    }

    /// The multi-edge command keeps the existing both-endpoint lock refusal and performs no delete
    /// when either endpoint is sealed-and-not-session-unlocked.
    #[test]
    fn unlink_collapsed_manual_set_refuses_locked_endpoint_without_partial_delete() {
        let state = build_state("unlink-collapsed-locked");
        make_open_folder(&state.db, "f-left", "Left folder");
        make_open_folder(&state.db, "f-right", "Right folder");
        seed_note_doc_cmd(&state.db, "left", "f-left", "Left", "left body");
        seed_note_doc_cmd(&state.db, "right", "f-right", "Right", "right body");
        link_items_inner(&state, "note", "left", "note", "right").unwrap();
        link_items_inner(&state, "note", "right", "note", "left").unwrap();
        let unlocked = unlocked_snapshot(&state).unwrap();
        let chip = state
            .db
            .links_for_visible(crate::links::LinkKind::Note, "left", &unlocked)
            .unwrap()
            .into_iter()
            .find(|edge| edge.other_id == "right")
            .unwrap();
        assert_eq!(chip.manual_edges.len(), 2);

        state
            .db
            .set_folder_locked("f-right", true, Some(&b"wrapped"[..]))
            .unwrap();
        let error =
            unlink_manual_edges_inner(&state, "note", "left", "note", "right", &chip.manual_edges)
                .unwrap_err();
        assert!(matches!(error, AppError::Locked(_)), "got {error:?}");
        assert_eq!(link_count_in(&state, "note", "left", "manual"), 2);
        assert_eq!(link_count_in(&state, "note", "right", "manual"), 2);
    }

    /// IPC payload hardening: one unordered pair has at most two exact directed rows. Duplicate or
    /// oversized lists are refused before the transaction and cannot turn unlink into an unbounded
    /// delete loop or produce a misleading partial success.
    #[test]
    fn unlink_collapsed_manual_set_rejects_duplicates_and_oversized_payloads() {
        let state = build_state("unlink-collapsed-bounds");
        make_open_folder(&state.db, "f-open", "Project");
        seed_note_doc_cmd(&state.db, "left", "f-open", "Left", "left body");
        seed_note_doc_cmd(&state.db, "right", "f-open", "Right", "right body");
        link_items_inner(&state, "note", "left", "note", "right").unwrap();
        let edge = crate::storage::models::ManualLinkEdge {
            src_kind: "note".into(),
            src_id: "left".into(),
            dst_kind: "note".into(),
            dst_id: "right".into(),
        };

        let duplicate = vec![edge.clone(), edge.clone()];
        let duplicate_error =
            unlink_manual_edges_inner(&state, "note", "left", "note", "right", &duplicate).unwrap_err();
        assert!(matches!(duplicate_error, AppError::InvalidArg(_)));

        let oversized = vec![edge.clone(), edge.clone(), edge];
        let oversized_error =
            unlink_manual_edges_inner(&state, "note", "left", "note", "right", &oversized).unwrap_err();
        assert!(matches!(oversized_error, AppError::InvalidArg(_)));

        let stale_pair = vec![
            crate::storage::models::ManualLinkEdge {
                src_kind: "note".into(),
                src_id: "left".into(),
                dst_kind: "note".into(),
                dst_id: "right".into(),
            },
            crate::storage::models::ManualLinkEdge {
                src_kind: "note".into(),
                src_id: "right".into(),
                dst_kind: "note".into(),
                dst_id: "left".into(),
            },
        ];
        let stale_error =
            unlink_manual_edges_inner(&state, "note", "left", "note", "right", &stale_pair)
                .unwrap_err();
        assert!(matches!(stale_error, AppError::InvalidArg(_)));
        assert_eq!(
            link_count_in(&state, "note", "left", "manual"),
            1,
            "invalid or stale multi-row payloads must roll back the existing row"
        );
    }

    #[test]
    fn unlink_refuses_sealed_not_session_unlocked_note_without_any_cleanup_side_effect() {
        let vault = tmp_vault("unlink-sealed-refusal");
        let state = build_state_with_vault("unlink-sealed-refusal", &vault);
        let folder_id = create_note_folder_inner(&state, "Secret", None).unwrap().id;
        let source_id = create_note_inner(&state, Some(&folder_id), "Source Note").unwrap();
        let target_id = create_note_inner(&state, Some(&folder_id), "Target Note").unwrap();
        let legacy_hit = crate::enrich::ContextHit {
            source: "note".into(),
            detail: "[[Target Note]]".into(),
            url: None,
        };
        let legacy_body =
            crate::enrich::apply_link_markers("original body\n", std::slice::from_ref(&legacy_hit));
        update_note_doc_inner(&state, &source_id, "Source Note", &legacy_body).unwrap();
        state
            .db
            .upsert_manual_link("note", &source_id, "note", &target_id)
            .unwrap();
        let exported_path = state
            .db
            .get_note_row(&source_id)
            .unwrap()
            .unwrap()
            .exported_path
            .unwrap();
        lock_folder_inner(&state, folder_id).unwrap();
        let before: (String, Option<Vec<u8>>) = state
            .db
            .lock()
            .query_row(
                "SELECT text,text_blob FROM documents WHERE id=?1",
                rusqlite::params![source_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert!(before.0.is_empty());
        assert!(before.1.is_some());
        assert!(!std::path::Path::new(&exported_path).exists());
        let links_before = manual_link_count(&state, "note", &source_id);
        let err = unlink_items_inner(&state, "note", &source_id, "note", &target_id).unwrap_err();
        assert!(matches!(err, AppError::Locked(_)));
        let after: (String, Option<Vec<u8>>) = state
            .db
            .lock()
            .query_row(
                "SELECT text,text_blob FROM documents WHERE id=?1",
                rusqlite::params![source_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            after, before,
            "sealed plaintext/blob must remain byte-identical"
        );
        assert_eq!(manual_link_count(&state, "note", &source_id), links_before);
        assert!(state
            .db
            .pending_lock_marker_export_cleanup()
            .unwrap()
            .is_empty());
        assert!(!std::path::Path::new(&exported_path).exists());
    }

    #[test]
