    #[test]
    fn meeting_detail_command_chain_masks_every_sealed_content_channel() {
        let state = build_state("meeting-detail-command-mask");
        make_open_folder(&state.db, "f-detail-secret", "Secret");
        let secret_note = "# PRIVATE DETAIL NOTE\n\n[[PRIVATE WIKILINK TARGET]]\n\n\
                               ![[murmur-attachment:private-image]]";
        seed_meeting(
            &state.db,
            "m-detail-secret",
            secret_note,
            Some("f-detail-secret"),
        );
        let owner = crate::storage::AttachmentOwner::Meeting {
            meeting_id: "m-detail-secret".into(),
            provider_id: "claude_code".into(),
        };
        // A real 1x1 PNG keeps this production-chain oracle focused on the
        // sealed-detail mask instead of failing earlier in attachment validation.
        let data = b"\x89PNG\r\n\x1a\n\x00\x00\x00\x0dIHDR\x00\x00\x00\x01\
                         \x00\x00\x00\x01\x08\x04\x00\x00\x00\xb5\x1c\x0c\x02\
                         \x00\x00\x00\x0bIDAT\x78\xda\x63\x64\xf8\x0f\x00\x01\
                         \x05\x01\x01\x27\x18\xe3\x66\x00\x00\x00\x00IEND\
                         \xae\x42\x60\x82";
        let hash: [u8; 32] = <sha2::Sha256 as sha2::Digest>::digest(data).into();
        state
            .db
            .insert_attachment(&crate::storage::NewAttachment {
                id: "private-image",
                owner: &owner,
                mime_type: "image/png",
                extension: "png",
                width: 1,
                height: 1,
                sha256: &hash,
                byte_len: data.len(),
                data,
                data_blob: None,
                created_at: 1,
            })
            .unwrap();
        lock_folder_inner(&state, "f-detail-secret".into()).unwrap();

        let detail = get_meeting_detail_inner(&state, "m-detail-secret")
            .unwrap()
            .unwrap();
        assert!(detail.locked);
        assert_eq!(detail.meeting.title.as_deref(), Some("🔒 Locked"));
        assert!(detail.meeting.audio_path.is_none());
        assert!(detail.note.is_none());
        assert!(detail.segments.is_empty());
        assert!(detail.assistant_interactions.is_empty());
        let wire = serde_json::to_string(&detail).unwrap();
        for secret in [
            "Quarterly strategy",
            "PRIVATE DETAIL NOTE",
            "PRIVATE WIKILINK TARGET",
            "private-image",
            "PII!",
            "alpha bravo",
        ] {
            assert!(
                !wire.contains(secret),
                "sealed content channel leaked through get_meeting_detail: {secret}"
            );
        }
    }

    struct CanonicalPreNoteHistory {
        folder_id: String,
        meeting_id: String,
        owner: crate::storage::AttachmentOwner,
        note: String,
        segments: [String; 2],
        timeline: String,
        manual_notes: String,
        attachment: Vec<u8>,
        audio: Vec<(std::path::PathBuf, Vec<u8>)>,
    }

    /// Birth the recording in a container before any provider note exists, then let the normal
    /// processing artifacts arrive. This is the exact history `meetings.folder_id` was added to
    /// preserve: placement exists from recording time and every later provider-owned artifact
    /// inherits that one governing lock domain.
    fn seed_canonical_pre_note_history(
        state: &AppState,
        tag: &str,
        with_audio: bool,
    ) -> CanonicalPreNoteHistory {
        let folder_id = format!("f-canonical-{tag}");
        let meeting_id = format!("m-canonical-{tag}");
        make_open_folder(&state.db, &folder_id, &format!("Canonical {tag}"));
        state
            .db
            .insert_meeting(&Meeting {
                id: meeting_id.clone(),
                started_at: "2026-08-26T09:00:00Z".into(),
                ended_at: Some("2026-08-26T09:10:00Z".into()),
                title: Some(format!("PRIVATE canonical title {tag}")),
                duration_s: 600,
                audio_path: None,
                status: MeetingStatus::Draft,
                folder_id: Some(folder_id.clone()),
            })
            .unwrap();
        assert!(
            state
                .db
                .sealable_notes_for_meeting(&meeting_id)
                .unwrap()
                .is_empty(),
            "placement must precede the first provider note"
        );

        let note = format!("# PRIVATE canonical note {tag}\n\nDECISION-{tag}");
        state
            .db
            .upsert_note(&NoteRecord {
                meeting_id: meeting_id.clone(),
                provider_id: "claude_code".into(),
                markdown: note.clone(),
                created_at: "2026-08-26T09:11:00Z".into(),
                exported_path: None,
                model_requested: None,
                model_served: None,
                gateway_host: None,
            })
            .unwrap();
        let inherited_folder: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT folder_id FROM notes WHERE meeting_id=?1 AND provider_id='claude_code'",
                rusqlite::params![meeting_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            inherited_folder.as_deref(),
            Some(folder_id.as_str()),
            "a provider note born after filing inherits canonical recording placement"
        );

        let segments = [
            format!("PRIVATE segment alpha {tag}"),
            format!("PRIVATE segment omega {tag}"),
        ];
        state
            .db
            .insert_segments(
                &meeting_id,
                &[
                    Segment {
                        idx: 0,
                        start_s: 0.0,
                        end_s: 2.0,
                        text: segments[0].clone(),
                        speaker: Some("Me".into()),
                        confidence: Some(0.99),
                    },
                    Segment {
                        idx: 1,
                        start_s: 2.0,
                        end_s: 4.0,
                        text: segments[1].clone(),
                        speaker: Some("Others".into()),
                        confidence: Some(0.98),
                    },
                ],
            )
            .unwrap();
        let timeline = format!(r#"{{"topics":[{{"label":"PRIVATE timeline {tag}"}}]}}"#);
        state.db.set_timeline_data(&meeting_id, &timeline).unwrap();
        let manual_notes = format!("PRIVATE manual notes {tag}");
        state
            .db
            .set_manual_notes(&meeting_id, &manual_notes)
            .unwrap();

        let owner = crate::storage::AttachmentOwner::Meeting {
            meeting_id: meeting_id.clone(),
            provider_id: "claude_code".into(),
        };
        let attachment = b"\x89PNG\r\n\x1a\n\x00\x00\x00\x0dIHDR\x00\x00\x00\x01\
                           \x00\x00\x00\x01\x08\x04\x00\x00\x00\xb5\x1c\x0c\x02\
                           \x00\x00\x00\x0bIDAT\x78\xda\x63\x64\xf8\x0f\x00\x01\
                           \x05\x01\x01\x27\x18\xe3\x66\x00\x00\x00\x00IEND\
                           \xae\x42\x60\x82"
            .to_vec();
        let hash: [u8; 32] = <sha2::Sha256 as sha2::Digest>::digest(&attachment).into();
        state
            .db
            .insert_attachment(&crate::storage::NewAttachment {
                id: &format!("attachment-{tag}"),
                owner: &owner,
                mime_type: "image/png",
                extension: "png",
                width: 1,
                height: 1,
                sha256: &hash,
                byte_len: attachment.len(),
                data: &attachment,
                data_blob: None,
                created_at: 1,
            })
            .unwrap();

        let mut audio = Vec::new();
        if with_audio {
            for (role, bytes) in [
                ("playback", b"RIFF canonical playback bytes".as_slice()),
                ("mic", b"RIFF canonical mic bytes".as_slice()),
                ("sys", b"RIFF canonical system bytes".as_slice()),
            ] {
                let path = crate::storage::db::unique_temp_path(
                    &format!("murmur-canonical-{tag}-{role}"),
                    "wav",
                );
                std::fs::write(&path, bytes).unwrap();
                let path_string = path.to_string_lossy().to_string();
                match role {
                    "playback" => state
                        .db
                        .set_meeting_audio_path(&meeting_id, Some(&path_string))
                        .unwrap(),
                    "mic" => state
                        .db
                        .set_meeting_mic_master_path(&meeting_id, Some(&path_string))
                        .unwrap(),
                    "sys" => state
                        .db
                        .set_meeting_sys_master_path(&meeting_id, Some(&path_string))
                        .unwrap(),
                    _ => unreachable!(),
                }
                audio.push((path, bytes.to_vec()));
            }
        }

        CanonicalPreNoteHistory {
            folder_id,
            meeting_id,
            owner,
            note,
            segments,
            timeline,
            manual_notes,
            attachment,
            audio,
        }
    }

    #[test]
    fn canonical_pre_note_history_round_trips_lock_relock_and_permanent_unlock_byte_identical() {
        let state = build_state("canonical-pre-note-roundtrip");
        let history = seed_canonical_pre_note_history(&state, "roundtrip", true);

        lock_folder_inner(&state, history.folder_id.clone()).unwrap();
        let assert_at_rest = || {
            let note = &state
                .db
                .sealable_notes_for_meeting(&history.meeting_id)
                .unwrap()[0];
            assert_eq!(note.markdown, "");
            assert!(note.content_blob.is_some());
            let segments = state.db.raw_segments(&history.meeting_id).unwrap();
            assert_eq!(segments.len(), 2);
            assert!(segments
                .iter()
                .all(|segment| segment.text.is_empty() && segment.text_blob.is_some()));
            let timeline = state.db.raw_timeline(&history.meeting_id).unwrap().unwrap();
            assert!(timeline.data.is_empty() && timeline.data_blob.is_some());
            let manual = state
                .db
                .raw_manual_notes(&history.meeting_id)
                .unwrap()
                .unwrap();
            assert!(manual.text.is_empty() && manual.blob.is_some());
            let attachment = &state.db.list_attachments(&history.owner).unwrap()[0];
            assert!(attachment.data.is_empty() && attachment.data_blob.is_some());

            let meeting = state.db.get_meeting(&history.meeting_id).unwrap().unwrap();
            let (mic, sys) = state
                .db
                .get_meeting_master_paths(&history.meeting_id)
                .unwrap();
            let stored = [meeting.audio_path, mic, sys];
            for ((plain, _), sealed) in history.audio.iter().zip(stored) {
                let sealed = sealed.expect("all three audio roles stay tracked");
                assert_eq!(sealed, format!("{}.enc", plain.to_string_lossy()));
                assert!(!plain.exists(), "plaintext audio must be absent at rest");
                assert!(std::path::Path::new(&sealed).exists());
            }
        };
        assert_at_rest();

        // Mirror the production unlock closure: restore every provider note first, then all extras,
        // then publish the in-memory folder admission.
        let ck = restore_notes_and_ck(&state, &history.folder_id);
        unseal_folder_extras(&state, &history.folder_id, &ck, None).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(history.folder_id.clone());

        assert_eq!(
            state
                .db
                .get_latest_note_for_meeting(&history.meeting_id)
                .unwrap()
                .unwrap()
                .markdown,
            history.note
        );
        assert_eq!(
            state
                .db
                .get_segments(&history.meeting_id)
                .unwrap()
                .into_iter()
                .map(|segment| segment.text)
                .collect::<Vec<_>>(),
            history.segments
        );
        assert_eq!(
            state
                .db
                .get_timeline_data(&history.meeting_id)
                .unwrap()
                .as_deref(),
            Some(history.timeline.as_str())
        );
        assert_eq!(
            state.db.get_manual_notes(&history.meeting_id).unwrap(),
            history.manual_notes
        );
        let attachment = &state.db.list_attachments(&history.owner).unwrap()[0];
        assert_eq!(attachment.data, history.attachment);
        assert!(
            attachment.data_blob.is_some(),
            "session restore retains recovery blob"
        );
        let meeting = state.db.get_meeting(&history.meeting_id).unwrap().unwrap();
        let (mic, sys) = state
            .db
            .get_meeting_master_paths(&history.meeting_id)
            .unwrap();
        for ((plain, bytes), restored) in history.audio.iter().zip([meeting.audio_path, mic, sys]) {
            assert_eq!(restored.as_deref(), Some(plain.to_string_lossy().as_ref()));
            assert_eq!(std::fs::read(plain).unwrap(), *bytes);
            assert!(std::path::Path::new(&format!("{}.enc", plain.to_string_lossy())).exists());
        }

        // The real lifecycle relock verifies every retained blob against session plaintext before
        // destroying any readable copy, then revokes the session admission.
        relock_all_inner(&state).unwrap();
        assert_at_rest();
        assert!(!state
            .unlocked_folders
            .lock()
            .unwrap()
            .contains(&history.folder_id));

        // Permanent unlock repeats the verified restore but clears blobs and retires `.enc` only
        // after the durable `locked=0` commit.
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        remove_lock_inner(&state, history.folder_id.clone()).unwrap();
        assert!(
            !state
            .db
            .folder_by_id(&history.folder_id)
            .unwrap()
            .unwrap()
                .locked
        );
        let note = &state
            .db
            .sealable_notes_for_meeting(&history.meeting_id)
            .unwrap()[0];
        assert_eq!(note.markdown, history.note);
        assert!(note.content_blob.is_none());
        let segments = state.db.raw_segments(&history.meeting_id).unwrap();
        assert_eq!(
            segments
                .iter()
                .map(|segment| segment.text.as_str())
                .collect::<Vec<_>>(),
            history
                .segments
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>()
        );
        assert!(segments.iter().all(|segment| segment.text_blob.is_none()));
        let timeline = state.db.raw_timeline(&history.meeting_id).unwrap().unwrap();
        assert_eq!(timeline.data, history.timeline);
        assert!(timeline.data_blob.is_none());
        let manual = state
            .db
            .raw_manual_notes(&history.meeting_id)
            .unwrap()
            .unwrap();
        assert_eq!(manual.text, history.manual_notes);
        assert!(manual.blob.is_none());
        let attachment = &state.db.list_attachments(&history.owner).unwrap()[0];
        assert_eq!(attachment.data, history.attachment);
        assert!(attachment.data_blob.is_none());
        let meeting = state.db.get_meeting(&history.meeting_id).unwrap().unwrap();
        let (mic, sys) = state
            .db
            .get_meeting_master_paths(&history.meeting_id)
            .unwrap();
        for ((plain, bytes), restored) in history.audio.iter().zip([meeting.audio_path, mic, sys]) {
            assert_eq!(restored.as_deref(), Some(plain.to_string_lossy().as_ref()));
            assert_eq!(std::fs::read(plain).unwrap(), *bytes);
            assert!(!std::path::Path::new(&format!("{}.enc", plain.to_string_lossy())).exists());
            std::fs::remove_file(plain).unwrap();
        }
    }

    #[test]
    fn canonical_pre_note_permanent_unlock_failure_retains_all_recovery_bytes() {
        let state = build_state("canonical-pre-note-failed-unlock");
        let history = seed_canonical_pre_note_history(&state, "failed-unlock", true);
        lock_folder_inner(&state, history.folder_id.clone()).unwrap();

        let note_blob = state
            .db
            .sealable_notes_for_meeting(&history.meeting_id)
            .unwrap()[0]
            .content_blob
            .clone()
            .unwrap();
        let segments_before = state
            .db
            .raw_segments(&history.meeting_id)
            .unwrap()
            .into_iter()
            .map(|segment| (segment.idx, segment.text, segment.text_blob))
            .collect::<Vec<_>>();
        let timeline_before = state.db.raw_timeline(&history.meeting_id).unwrap().unwrap();
        let manual_before = state
            .db
            .raw_manual_notes(&history.meeting_id)
            .unwrap()
            .unwrap();
        let mut corrupt_attachment_blob = state.db.list_attachments(&history.owner).unwrap()[0]
            .data_blob
            .clone()
            .unwrap();
        let corrupt_at = corrupt_attachment_blob.len() / 2;
        corrupt_attachment_blob[corrupt_at] ^= 0x80;
        state
            .db
            .lock()
            .execute(
                "UPDATE note_attachments SET data_blob=?2 WHERE id=?1",
                rusqlite::params![
                    format!("attachment-{}", "failed-unlock"),
                    corrupt_attachment_blob
                ],
            )
            .unwrap();
        let meeting_before = state.db.get_meeting(&history.meeting_id).unwrap().unwrap();
        let masters_before = state
            .db
            .get_meeting_master_paths(&history.meeting_id)
            .unwrap();
        let audio_ciphertexts = history
            .audio
            .iter()
            .map(|(plain, _)| {
                let sealed = std::path::PathBuf::from(format!("{}.enc", plain.to_string_lossy()));
                (sealed.clone(), std::fs::read(sealed).unwrap())
            })
            .collect::<Vec<_>>();
        let wrapped_before = state
            .db
            .folder_wrapped_key(&history.folder_id)
            .unwrap()
            .unwrap();

        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        let error = remove_lock_inner(&state, history.folder_id.clone())
            .expect_err("corrupt attachment ciphertext must abort permanent unlock");
        assert!(matches!(
            error,
            AppError::Locked(_) | AppError::Storage(_) | AppError::Other(_)
        ));
        assert!(
            state
            .db
            .folder_by_id(&history.folder_id)
            .unwrap()
            .unwrap()
                .locked
        );
        assert_eq!(
            state
                .db
                .folder_wrapped_key(&history.folder_id)
                .unwrap()
                .unwrap(),
            wrapped_before
        );

        // Provider markdown was restored before the deliberately failing attachment step, but its
        // recovery blob is retained. Thus both copies remain valid; failure never creates the fatal
        // blank-plus-NULL shape.
        let note = &state
            .db
            .sealable_notes_for_meeting(&history.meeting_id)
            .unwrap()[0];
        assert_eq!(note.markdown, history.note);
        assert_eq!(note.content_blob.as_deref(), Some(note_blob.as_slice()));
        let segments_after = state
            .db
            .raw_segments(&history.meeting_id)
            .unwrap()
            .into_iter()
            .map(|segment| (segment.idx, segment.text, segment.text_blob))
            .collect::<Vec<_>>();
        assert_eq!(segments_after, segments_before);
        let timeline_after = state.db.raw_timeline(&history.meeting_id).unwrap().unwrap();
        assert_eq!(timeline_after.data, timeline_before.data);
        assert_eq!(timeline_after.data_blob, timeline_before.data_blob);
        let manual_after = state
            .db
            .raw_manual_notes(&history.meeting_id)
            .unwrap()
            .unwrap();
        assert_eq!(manual_after.text, manual_before.text);
        assert_eq!(manual_after.blob, manual_before.blob);
        let attachment = &state.db.list_attachments(&history.owner).unwrap()[0];
        assert!(attachment.data.is_empty());
        assert_eq!(
            attachment.data_blob.as_deref(),
            Some(corrupt_attachment_blob.as_slice()),
            "the failing ciphertext is retained for diagnosis/recovery, never deleted"
        );
        let meeting_after = state.db.get_meeting(&history.meeting_id).unwrap().unwrap();
        assert_eq!(meeting_after.audio_path, meeting_before.audio_path);
        assert_eq!(
            state
                .db
                .get_meeting_master_paths(&history.meeting_id)
                .unwrap(),
            masters_before
        );
        for ((sealed, bytes), (plain, _)) in audio_ciphertexts.iter().zip(&history.audio) {
            assert_eq!(std::fs::read(sealed).unwrap(), *bytes);
            assert!(
                !plain.exists(),
                "failed unlock must not strand plaintext audio"
            );
            std::fs::remove_file(sealed).unwrap();
        }
    }

    // ── The fact ledger's PRODUCTION wiring ──────────────────────────────────────────────────────
    //
    // An adversarial review deleted the relock re-seal loops (`commands/lock.rs`) and the restore
    // inside `unseal_meeting_extras`, ran the WHOLE suite, and everything stayed green. The two
    // headline claims of that change — "an unlock puts the ledger back" and "a relock re-seals
    // before the purge" — were pinned by nothing. These two drive the real lock/unlock/relock
    // commands, so removing either wire fails here.

    /// Seed one entity fact on `mid` and hand back the entity id.
    fn seed_one_fact(db: &Db, mid: &str, predicate: &str, object: &str) -> String {
        let atlas = db
            .upsert_entity("Atlas", crate::storage::models::EntityKind::Project)
            .unwrap();
        db.add_mention(&atlas, mid).unwrap();
        db.apply_fact_ops(&[crate::facts::FactOp::Add(crate::facts::NewFact {
            entity_id: atlas.clone(),
            subject: "Atlas".into(),
            predicate: predicate.into(),
            object: object.into(),
            valid_from: "2026-06-01T00:00:00Z".into(),
            recorded_at: "2026-06-01T00:00:00Z".into(),
            confidence: 1.0,
            meeting_id: Some(mid.to_string()),
        })])
        .unwrap();
        atlas
    }

    /// Unwrap a locked folder's content key the way the unlock command does.
    fn folder_ck(state: &AppState, folder_id: &str) -> [u8; 32] {
        let kek = secrets::get_or_create_master_kek().unwrap();
        let wrapped = state.db.folder_wrapped_key(folder_id).unwrap().unwrap();
        let ck_vec = crate::crypto::decrypt(&kek, &wrapped, &aad_wrapped_ck(folder_id)).unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        ck_vec.try_into().expect("CK is 32 bytes")
    }

    /// LOCK → the facts are gone → UNLOCK → they are back. Through the real commands.
    #[test]
    fn locking_and_unlocking_a_folder_returns_its_facts() {
        let state = std::sync::Arc::new(build_state("ledger-wiring-unlock"));
        make_open_folder(&state.db, "f-facts", "Secret");
        seed_meeting(&state.db, "m-facts", "# Note", Some("f-facts"));
        let atlas = seed_one_fact(&state.db, "m-facts", "status", "shipped");

        lock_folder_inner(state.as_ref(), "f-facts".into()).unwrap();
        assert!(
            state
                .db
                .facts_for_entities(std::slice::from_ref(&atlas))
                .unwrap()
                .is_empty(),
            "the seal still removes the rows — that half is unchanged"
        );

        let ck = folder_ck(state.as_ref(), "f-facts");
        unseal_folder_extras(state.as_ref(), "f-facts", &ck, None).unwrap();
        assert_eq!(
            state
                .db
                .facts_for_entities(std::slice::from_ref(&atlas))
                .unwrap()
                .len(),
            1,
            "an unlock must put the ledger back — this is the wire the review could delete silently"
        );
    }

    /// UNLOCK → learn something → RELOCK → UNLOCK: both facts are there.
    ///
    /// The relock purges before it re-seals, so the re-seal has to happen first. Without it the
    /// relock leaves the ciphertext written at the ORIGINAL lock, and the fact the open session
    /// learned is destroyed with no trace.
    #[test]
    fn a_relock_keeps_the_fact_the_open_session_learned() {
        let state = std::sync::Arc::new(build_state("ledger-wiring-relock"));
        make_open_folder(&state.db, "f-facts", "Secret");
        seed_meeting(&state.db, "m-facts", "# Note", Some("f-facts"));
        let atlas = seed_one_fact(&state.db, "m-facts", "status", "shipped");

        lock_folder_inner(state.as_ref(), "f-facts".into()).unwrap();
        let ck = folder_ck(state.as_ref(), "f-facts");
        unseal_folder_extras(state.as_ref(), "f-facts", &ck, None).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-facts".into());

        // The open session learns a second thing about the same project.
        state
            .db
            .apply_fact_ops(&[crate::facts::FactOp::Add(crate::facts::NewFact {
                entity_id: atlas.clone(),
                subject: "Atlas".into(),
                predicate: "owner".into(),
                object: "Ada".into(),
                valid_from: "2026-08-01T00:00:00Z".into(),
                recorded_at: "2026-08-01T00:00:00Z".into(),
                confidence: 1.0,
                meeting_id: Some("m-facts".to_string()),
            })])
            .unwrap();

        relock_folder_inner_with_visibility_notice(&state, "f-facts", || {}).unwrap();
        assert!(
            state
                .db
                .facts_for_entities(std::slice::from_ref(&atlas))
                .unwrap()
                .is_empty(),
            "the relock purges, as it always did"
        );

        let ck = folder_ck(state.as_ref(), "f-facts");
        unseal_folder_extras(state.as_ref(), "f-facts", &ck, None).unwrap();
        let after = state
            .db
            .facts_for_entities(std::slice::from_ref(&atlas))
            .unwrap();
        assert!(
            after.iter().any(|f| f.predicate == "owner"),
            "the fact the open session learned must survive the relock — got {after:?}"
        );
        assert!(
            after.iter().any(|f| f.predicate == "status"),
            "and so must the one sealed at the original lock — got {after:?}"
        );
    }

    #[test]
    fn conversion_command_relock_during_provider_await_writes_nothing() {
        let state = std::sync::Arc::new(build_state("conversion-command-await-relock"));
        make_open_folder(&state.db, "f-relock", "Secret");
        seed_meeting(&state.db, "m-relock", "# Existing source", Some("f-relock"));
        lock_folder_inner(state.as_ref(), "f-relock".into()).unwrap();
        let kek = secrets::get_or_create_master_kek().unwrap();
        let wrapped = state.db.folder_wrapped_key("f-relock").unwrap().unwrap();
        let ck_vec = crate::crypto::decrypt(&kek, &wrapped, &aad_wrapped_ck("f-relock")).unwrap();
        let ck: [u8; 32] = ck_vec.try_into().expect("CK is 32 bytes");
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        unseal_folder_extras(state.as_ref(), "f-relock", &ck, None).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-relock".into());
        let provider = ConversionProvider::relocking(std::sync::Arc::clone(&state));

        let result = block_on(convert_meeting_to_note_inner_with(
            None,
            state.as_ref(),
            "m-relock".into(),
            None,
            Some(provider.clone()),
        ));
        assert!(matches!(result, Err(AppError::Locked(_))));
        assert_eq!(provider.count(), 1, "provider await actually ran");
        assert!(
            !state.unlocked_folders.lock().unwrap().contains("f-relock"),
            "production relock-all revoked the source folder during provider await"
        );
        let reblanked = state.db.get_segments("m-relock").unwrap();
        assert_eq!(
            reblanked.len(),
            2,
            "sealed transcript rows remain canonical"
        );
        assert!(
            reblanked.iter().all(|segment| segment.text.is_empty()),
            "production relock-all reblanked every transcript row"
        );
        assert_eq!(
            state.db.companion_note_for_meeting("m-relock").unwrap(),
            None
        );
    }

    #[test]
    fn conversion_related_change_during_provider_await_writes_nothing() {
        #[derive(Clone, Copy)]
        enum RelatedMutation {
            Remove,
            Deactivate,
            DeleteSource,
        }

        struct MutatingRelatedProvider {
            state: std::sync::Arc<AppState>,
            mutation: RelatedMutation,
            link_id: i64,
        }

        #[async_trait::async_trait]
        impl crate::summarize::provider::SummarizerProvider for MutatingRelatedProvider {
            fn id(&self) -> &str {
                "conversion-related-race"
            }

            async fn availability(&self) -> crate::summarize::provider::Availability {
                crate::summarize::provider::Availability::Available
            }

            async fn summarize(
                &self,
                request: &crate::summarize::provider::SummarizeRequest,
            ) -> crate::error::Result<String> {
                assert!(
                    request.transcript.contains("RELATED_SECRET_CONTEXT"),
                    "precondition: active visible Related plaintext reached the provider request"
                );
                match self.mutation {
                    RelatedMutation::Remove => self.state.db.delete_manual_link(
                        "meeting",
                        "m-related-race",
                        "note",
                        "n-related-race",
                    )?,
                    RelatedMutation::Deactivate => self.state.db.dismiss_link(self.link_id)?,
                    RelatedMutation::DeleteSource => self.state.db.delete_document("n-related-race")?,
                }
                Ok("---\ntitle: Stale\n---\n\n# Must not persist".into())
            }

            async fn complete(&self, _system: &str, _user: &str) -> crate::error::Result<String> {
                Err(AppError::Unavailable("unused conversion completion".into()))
            }
        }

        for (case, mutation) in [
            ("remove", RelatedMutation::Remove),
            ("deactivate", RelatedMutation::Deactivate),
            ("delete-source", RelatedMutation::DeleteSource),
        ] {
            let state = std::sync::Arc::new(build_state(&format!("conversion-related-race-{case}")));
            seed_meeting(&state.db, "m-related-race", "# Primary transcript", None);
            make_open_folder(&state.db, "f-related-race", "Related");
            seed_note_doc_cmd(
                &state.db,
                "n-related-race",
                "f-related-race",
                "Related source",
                "RELATED_SECRET_CONTEXT",
            );
            let link_id = state.db.insert_link_for_test(
                "meeting",
                "m-related-race",
                "note",
                "n-related-race",
                "manual",
                1.0,
                "user",
                "active",
            );
            let provider = std::sync::Arc::new(MutatingRelatedProvider {
                state: std::sync::Arc::clone(&state),
                mutation,
                link_id,
            });

            let result = block_on(convert_meeting_to_note_inner_with(
                None,
                state.as_ref(),
                "m-related-race".into(),
                None,
                Some(provider),
            ));

            assert!(
                matches!(result, Err(AppError::Locked(_))),
                "{case}: stale Related context must invalidate conversion admission: {result:?}"
            );
            assert_eq!(
                state
                    .db
                    .companion_note_for_meeting("m-related-race")
                    .unwrap(),
                None,
                "{case}: provider output based on stale Related context writes no companion"
            );
            let stale_rows: i64 = state
                .db
                .lock()
                .query_row(
                    "SELECT COUNT(*) FROM documents WHERE text LIKE '%Must not persist%'",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(
                stale_rows, 0,
                "{case}: rejected provider output leaves no orphan document row"
            );
        }
    }

    #[test]
    fn conversion_private_org_links_never_enter_provider_context() {
        const ORG_TITLE_SENTINEL: &str = "ORG_CONVERSION_PRIVATE_TITLE_SENTINEL";
        const ORG_BODY_SENTINEL: &str = "ORG_CONVERSION_PRIVATE_BODY_SENTINEL";

        struct CapturingProvider {
            request: std::sync::Mutex<Option<crate::summarize::provider::SummarizeRequest>>,
        }

        #[async_trait::async_trait]
        impl crate::summarize::provider::SummarizerProvider for CapturingProvider {
            fn id(&self) -> &str {
                "conversion-private-org-capture"
            }

            async fn availability(&self) -> crate::summarize::provider::Availability {
                crate::summarize::provider::Availability::Available
            }

            async fn summarize(
                &self,
                request: &crate::summarize::provider::SummarizeRequest,
            ) -> crate::error::Result<String> {
                *self.request.lock().unwrap() = Some(request.clone());
                Ok("---\ntitle: Private-link-safe conversion\n---\n\n# Converted".into())
            }

            async fn complete(&self, _system: &str, _user: &str) -> crate::error::Result<String> {
                Err(AppError::Unavailable("unused conversion completion".into()))
            }
        }

        let state = build_state("conversion-private-org-context");
        seed_meeting(
            &state.db,
            "m-private-org-context",
            "# Primary meeting note",
            None,
        );
        seed_org(&state.db, STABLE_ORG_ID, "Private org", "member", 1);
        state
            .db
            .upsert_org_item(
                "item-private-org-context",
                STABLE_ORG_ID,
                1,
                "colleague",
                ORG_TITLE_SENTINEL,
                ORG_BODY_SENTINEL,
                "2026-08-13T00:00:00Z",
                1,
                1,
                &[7u8; 32],
                Some("document"),
                Some("colleague-user-id"),
                None,
            )
            .unwrap();
        state
            .db
            .set_org_item_document_metadata(
                "item-private-org-context",
                Some(STABLE_DOC_ID),
                "view",
                Some("colleague-user-id"),
            )
            .unwrap();
        state
            .db
            .repair_org_reconcile_metadata(
                "item-private-org-context",
                STABLE_ORG_ID,
                1,
                Some(STABLE_DOC_ID),
                "view",
                Some("colleague-user-id"),
                true,
            )
            .unwrap();
        let org_link_id = format!("{STABLE_ORG_ID}:{STABLE_DOC_ID}");
        state
            .db
            .upsert_manual_link("meeting", "m-private-org-context", "org", &org_link_id)
            .unwrap();

        let org_item = state
            .db
            .get_org_item("item-private-org-context")
            .unwrap()
            .expect("org item remains visible");
        assert_eq!(org_item.title, ORG_TITLE_SENTINEL);
        assert_eq!(org_item.markdown, ORG_BODY_SENTINEL);
        let unlocked = unlocked_snapshot(&state).unwrap();
        let visible_links = state
            .db
            .links_for_visible(
                crate::links::LinkKind::Meeting,
                "m-private-org-context",
                &unlocked,
            )
            .unwrap();
        assert!(visible_links.iter().any(|edge| {
            edge.other_kind == crate::links::LinkKind::Org.as_str()
                && edge.other_id == org_link_id
                && edge.other_title == ORG_TITLE_SENTINEL
        }));
        assert!(
            capture_meeting_content_snapshot(&state, "m-private-org-context")
                .unwrap()
                .active_related
                .is_empty(),
            "a private org relation must not enter the conversion admission witness"
        );

        let provider = std::sync::Arc::new(CapturingProvider {
            request: std::sync::Mutex::new(None),
        });
        let converted = block_on(convert_meeting_to_note_inner_with(
            None,
            &state,
            "m-private-org-context".into(),
            None,
            Some(provider.clone()),
        ));
        assert!(
            converted.is_ok(),
            "conversion must still succeed: {converted:?}"
        );

        let request = provider
            .request
            .lock()
            .unwrap()
            .clone()
            .expect("conversion provider was called exactly once");
        for sentinel in [ORG_TITLE_SENTINEL, ORG_BODY_SENTINEL] {
            assert!(
                !request.transcript.contains(sentinel),
                "private org content entered conversion transcript: {sentinel}"
            );
            assert!(
                request
                    .vault_titles
                    .iter()
                    .all(|title| !title.contains(sentinel)),
                "private org content entered conversion vault titles: {sentinel}"
            );
        }
    }

    #[test]
    fn conversion_command_provider_and_canonical_write_failures_preserve_existing_bytes() {
        const ATTACHMENT_ID: &str = "10000000-0000-4000-8000-000000000001";
        const ATTACHMENT_BYTES: &[u8] = b"\x89PNG\r\n\x1a\n\x00\x00\x00\x0dIHDR\x00\x00\x00\x01\
            \x00\x00\x00\x01\x08\x04\x00\x00\x00\xb5\x1c\x0c\x02\
            \x00\x00\x00\x0bIDAT\x78\xda\x63\x64\xf8\x0f\x00\x01\
            \x05\x01\x01\x27\x18\xe3\x66\x00\x00\x00\x00IEND\
            \xae\x42\x60\x82";

        let vault = tmp_vault("conversion-command-preserve-failures");
        let state = build_state_with_vault("conversion-command-preserve-failures", &vault);
        seed_meeting(&state.db, "m-existing", "# Existing source", None);
        let snapshot = capture_meeting_content_snapshot(&state, "m-existing").unwrap();
        let companion = persist_converted_companion_under_snapshot_with(
            &state,
            "m-existing",
            &snapshot,
            "Quarterly strategy",
            "---\ntitle: Stable\n---\n\n# Stable\n\nOriginal generated bytes.",
            None,
        )
        .unwrap();
        let owner = crate::storage::AttachmentOwner::Document {
            document_id: companion.note_id.clone(),
        };
        let hash: [u8; 32] = <sha2::Sha256 as sha2::Digest>::digest(ATTACHMENT_BYTES).into();
        state
            .db
            .insert_attachment(&crate::storage::NewAttachment {
                id: ATTACHMENT_ID,
                owner: &owner,
                mime_type: "image/png",
                extension: "png",
                width: 1,
                height: 1,
                sha256: &hash,
                byte_len: ATTACHMENT_BYTES.len(),
                data: ATTACHMENT_BYTES,
                data_blob: None,
                created_at: 1,
            })
            .unwrap();
        let with_attachment = format!(
            "{}\nUser-owned bytes remain outside the managed block.\n![proof](murmur-attachment://{ATTACHMENT_ID})\n",
            state
                .db
                .get_note_row(&companion.note_id)
                .unwrap()
                .unwrap()
                .text
        );
        update_note_doc_inner_with(
            &state,
            &companion.note_id,
            "Quarterly strategy",
            &with_attachment,
            None,
        )
        .unwrap();

        let before = state.db.get_note_row(&companion.note_id).unwrap().unwrap();
        let before_hash = state
            .db
            .get_note_doc_exported_hash(&companion.note_id)
            .unwrap();
        let before_attachment = state.db.list_attachments(&owner).unwrap().remove(0);
        let note_export = std::path::PathBuf::from(
            before
                .exported_path
                .as_deref()
                .expect("real vault tracks the converted note export"),
        );
        let attachment_export = std::path::PathBuf::from(
            before_attachment
                .exported_path
                .as_deref()
                .expect("real vault tracks the converted attachment export"),
        );
        let attachment_twin = attachment_export.with_file_name(format!(".{ATTACHMENT_ID}.murmur.tmp"));
        std::fs::write(&attachment_twin, ATTACHMENT_BYTES)
            .expect("simulate the tracked deterministic attachment twin");
        let note_export_bytes = std::fs::read(&note_export).unwrap();
        let attachment_export_bytes = std::fs::read(&attachment_export).unwrap();
        let attachment_twin_bytes = std::fs::read(&attachment_twin).unwrap();

        let provider_failure = block_on(convert_meeting_to_note_inner_with(
            None,
            &state,
            "m-existing".into(),
            None,
            Some(ConversionProvider::failing()),
        ));
        assert!(matches!(provider_failure, Err(AppError::Unavailable(_))));
        assert_eq!(
            state
                .db
                .get_note_row(&companion.note_id)
                .unwrap()
                .unwrap()
                .text,
            before.text
        );
        assert_eq!(std::fs::read(&note_export).unwrap(), note_export_bytes);
        assert_eq!(
            std::fs::read(&attachment_export).unwrap(),
            attachment_export_bytes
        );
        assert_eq!(
            std::fs::read(&attachment_twin).unwrap(),
            attachment_twin_bytes
        );

        state
            .db
            .lock()
            .execute_batch(&format!(
                "CREATE TRIGGER conversion_write_fault BEFORE UPDATE ON documents \
                     WHEN OLD.id = '{}' BEGIN SELECT RAISE(ABORT, 'conversion write fault'); END;",
                companion.note_id
            ))
            .unwrap();
        let write_failure = block_on(convert_meeting_to_note_inner_with(
            None,
            &state,
            "m-existing".into(),
            None,
            Some(ConversionProvider::fixed(
                "---\ntitle: Replacement\n---\n\n# Replacement\n\nMust not persist.",
            )),
        ));
        assert!(write_failure.is_err());
        let after = state.db.get_note_row(&companion.note_id).unwrap().unwrap();
        assert_eq!(after.id, before.id);
        assert_eq!(after.folder_id, before.folder_id);
        assert_eq!(after.name, before.name);
        assert_eq!(after.title, before.title);
        assert_eq!(after.text, before.text);
        assert_eq!(after.created_at, before.created_at);
        assert_eq!(after.updated_at, before.updated_at);
        assert_eq!(after.exported_path, before.exported_path);
        assert_eq!(after.sealed, before.sealed);
        assert_eq!(
            state
                .db
                .get_note_doc_exported_hash(&companion.note_id)
                .unwrap(),
            before_hash,
            "canonical update failure preserves the Markdown export baseline"
        );
        assert_eq!(
            state.db.list_attachments(&owner).unwrap(),
            vec![before_attachment],
            "canonical update failure preserves the attachment row and tracked path"
        );
        assert_eq!(
            std::fs::read(&note_export).unwrap(),
            note_export_bytes,
            "the tracked Markdown export is restored byte-identical after rollback"
        );
        assert_eq!(
            std::fs::read(&attachment_export).unwrap(),
            attachment_export_bytes,
            "the tracked attachment export is restored byte-identical after rollback"
        );
        assert_eq!(
            std::fs::read(&attachment_twin).unwrap(),
            attachment_twin_bytes,
            "the deterministic attachment twin is restored byte-identical after rollback"
        );
        let _ = std::fs::remove_dir_all(vault);
    }

    #[test]
    fn converted_block_replaces_only_managed_content_and_rejects_broken_markers() {
        let first = compose_converted_companion_markdown(
            "",
            "Project sync",
            "---\ntitle: First\ntags: [meeting]\n---\n\n# First\n\nOld generated body.",
        )
        .unwrap();
        assert!(first.contains("title: First"));
        assert!(first.contains("meeting: \"[[Project sync]]\""));
        assert_eq!(first.matches(CONVERTED_NOTE_START).count(), 1);
        assert_eq!(first.matches(CONVERTED_NOTE_END).count(), 1);

        let with_user_text = format!("{first}\nUser-authored appendix.\n");
        let second = compose_converted_companion_markdown(
            &with_user_text,
            "Project sync",
            "---\ntitle: Replacement\n---\n\n# Replacement\n\nFresh generated body.",
        )
        .unwrap();
        assert!(second.contains("User-authored appendix."));
        assert!(second.contains("Fresh generated body."));
        assert!(!second.contains("Old generated body."));
        assert!(
            second.contains("title: First"),
            "existing front-matter wins"
        );
        assert!(!second.contains("title: Replacement"));
        assert_eq!(second.matches(CONVERTED_NOTE_START).count(), 1);

        let trailing = format!("{first}\nUser-authored appendix.  \n\n\n");
        let replaced = compose_converted_companion_markdown(
            &trailing,
            "Project sync",
            "---\ntitle: Ignored\n---\n\n# Third\n\nThird generated body.",
        )
        .unwrap();
        let (_, trailing_body) = crate::storage::db::split_front_matter(&trailing);
        let (_, replaced_body) = crate::storage::db::split_front_matter(&replaced);
        let trailing_suffix = trailing_body
            .split_once(CONVERTED_NOTE_END)
            .map(|(_, suffix)| suffix)
            .unwrap();
        let replaced_suffix = replaced_body
            .split_once(CONVERTED_NOTE_END)
            .map(|(_, suffix)| suffix)
            .unwrap();
        assert_eq!(
            replaced_suffix, trailing_suffix,
            "bytes outside the managed fence, including trailing whitespace, survive exactly"
        );

        let broken = format!("User text\n\n{CONVERTED_NOTE_START}\npartial");
        assert!(matches!(
            compose_converted_companion_markdown(&broken, "Project sync", "# New"),
            Err(AppError::InvalidArg(_))
        ));
        assert!(matches!(
            compose_converted_companion_markdown("", "Project sync", "---\n---\n"),
            Err(AppError::Unavailable(_))
        ));
        assert!(matches!(
            compose_converted_companion_markdown(
                "",
                "Project sync",
                &format!("# Generated\n\n{CONVERTED_NOTE_START}\nforged block"),
            ),
            Err(AppError::InvalidArg(_))
        ));
        assert!(matches!(
            compose_converted_companion_markdown(
                "",
                "Project sync",
                &format!("# Generated\n\nforged close {CONVERTED_NOTE_END}"),
            ),
            Err(AppError::InvalidArg(_))
        ));
    }

    #[test]
    fn converted_companion_creates_reuses_and_survives_relock_refusal() {
        let state = build_state("converted-companion");
        seed_meeting(&state.db, "m-convert", "# Existing meeting note", None);
        let snapshot = capture_meeting_content_snapshot(&state, "m-convert").unwrap();
        let first = persist_converted_companion_under_snapshot_with(
            &state,
            "m-convert",
            &snapshot,
            "Quarterly strategy",
            "---\ntitle: Quarterly strategy\n---\n\n# Quarterly strategy\n\nFirst generated.",
            None,
        )
        .unwrap();
        let row = state.db.get_note_row(&first.note_id).unwrap().unwrap();
        assert!(row.text.contains("First generated."));
        assert_eq!(
            state.db.companion_note_for_meeting("m-convert").unwrap(),
            Some(first.note_id.clone())
        );
        // The public link reader deliberately collapses a companion edge with the generated
        // `[[Meeting]]` wikilink for the same pair, preferring the wikilink row for display. Check
        // the canonical row directly so this oracle proves atomic persistence rather than a UI
        // dedupe representation.
        let companion_edge_rows: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM links
                      WHERE src_kind = 'note' AND src_id = ?1
                        AND dst_kind = 'meeting' AND dst_id = 'm-convert'
                        AND edge_type = 'companion' AND status = 'active'",
                [&first.note_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            companion_edge_rows, 1,
            "successful conversion must persist its required structured companion edge"
        );
        let unlocked = unlocked_snapshot(&state).unwrap();
        assert!(
            active_conversion_related_edges(&state, "m-convert", &unlocked)
                .unwrap()
                .iter()
                .all(|edge| edge.other_id != first.note_id),
            "the structural companion output must never feed the next conversion as Related input"
        );
        let post_birth_snapshot = capture_meeting_content_snapshot(&state, "m-convert").unwrap();
        assert_eq!(
            post_birth_snapshot.active_related, snapshot.active_related,
            "companion birth must not change the exact conversion-input witness"
        );

        let user_body = format!("{}\nUser-authored follow-up.\n", row.text);
        update_note_doc_inner_with(
            &state,
            &first.note_id,
            "Quarterly strategy",
            &user_body,
            None,
        )
        .unwrap();
        let second_snapshot = capture_meeting_content_snapshot(&state, "m-convert").unwrap();
        let second = persist_converted_companion_under_snapshot_with(
            &state,
            "m-convert",
            &second_snapshot,
            "Quarterly strategy",
            "---\ntitle: Quarterly strategy\n---\n\n# Quarterly strategy\n\nSecond generated.",
            None,
        )
        .unwrap();
        assert_eq!(second.note_id, first.note_id, "one companion is reused");
        let row = state.db.get_note_row(&second.note_id).unwrap().unwrap();
        assert!(row.text.contains("User-authored follow-up."));
        assert!(row.text.contains("Second generated."));
        assert!(!row.text.contains("First generated."));

        let stale_snapshot = capture_meeting_content_snapshot(&state, "m-convert").unwrap();
        bump_seal_epoch(&state);
        let before = row.text;
        assert!(matches!(
            persist_converted_companion_under_snapshot_with(
                &state,
                "m-convert",
                &stale_snapshot,
                "Quarterly strategy",
                "---\ntitle: Bad\n---\n\n# Must not persist",
                None,
            ),
            Err(AppError::Locked(_))
        ));
        assert_eq!(
            state
                .db
                .get_note_row(&second.note_id)
                .unwrap()
                .unwrap()
                .text,
            before,
            "stale provider output writes nothing"
        );
    }

    /// Every refusal the user can ACT ON must carry its `errcode`, so the frontend renders the
    /// sentence that names the next step instead of the deny-by-default "Please try again".
    ///
    /// This is the oracle for the class, not for one message. The convert path had SIX anonymous
    /// refusals; the one that actually fired in production ("a note in this folder is shared")
    /// took a SQLCipher session against the user's own database to identify, because the app
    /// could not say it. A future refactor that drops a tag puts us straight back there, and the
    /// only thing that would notice is this test.
    #[test]
    fn actionable_conversion_refusals_carry_their_error_code() {
        fn code_of(error: &AppError) -> String {
            let rendered = error.to_string();
            let body = rendered.split_once(": ").map_or(rendered.as_str(), |(_, b)| b);
            body.strip_prefix('[')
                .and_then(|rest| rest.split_once(']'))
                .map(|(code, _)| code.to_string())
                .unwrap_or_else(|| format!("UNCODED: {body}"))
        }

        // 1. No transcript — the meeting exists and is unlocked, but there is nothing to summarize.
        let state = build_state("convert-code-no-transcript");
        seed_meeting(&state.db, "m-no-transcript", "# Note", None);
        {
            let conn = state.db.lock();
            conn.execute("DELETE FROM segments WHERE meeting_id='m-no-transcript'", [])
                .unwrap();
        }
        let error = block_on(convert_meeting_to_note_inner_with(
            None,
            &state,
            "m-no-transcript".into(),
            None,
            Some(ConversionProvider::fixed("---\ntitle: x\n---\n\n# x\n\nBody.")),
        ))
        .unwrap_err();
        assert_eq!(code_of(&error), "convert-no-transcript");

        // 2. A template id that no longer exists.
        let error = resolve_conversion_template(Some("no-such-template"), "standard", vec![])
            .map(|_| ())
            .unwrap_err();
        assert_eq!(code_of(&error), "note-template-missing");

        // 3. An empty provider body must not blank a note — and must say which knob to turn.
        let error = compose_converted_companion_markdown("", "Meeting", "---\ntitle: x\n---\n\n")
            .map(|_| ())
            .unwrap_err();
        assert_eq!(code_of(&error), "note-provider-empty");

        // 4. The companion's OWN live share — the guard that survives, and the exact shape of the
        //    refusal the reporting user hit before the folder-wide guards were removed.
        let state = build_state("convert-code-share-active");
        seed_meeting(&state.db, "m-shared", "# Existing", None);
        let snapshot = capture_meeting_content_snapshot(&state, "m-shared").unwrap();
        let first = persist_converted_companion_under_snapshot_with(
            &state,
            "m-shared",
            &snapshot,
            "Shared",
            "---\ntitle: Shared\n---\n\n# Shared\n\nOriginal.",
            None,
        )
        .unwrap();
        state
            .db
            .insert_outbound_note_share(
                "convert-code-share",
                &first.note_id,
                "link",
                1,
                "2026-08-25T20:00:00Z",
            )
            .unwrap();
        let snapshot = capture_meeting_content_snapshot(&state, "m-shared").unwrap();
        let error = persist_converted_companion_under_snapshot_with(
            &state,
            "m-shared",
            &snapshot,
            "Shared",
            "---\ntitle: Shared\n---\n\n# Shared\n\nReplacement.",
            None,
        )
        .unwrap_err();
        assert_eq!(code_of(&error), "share-active");
    }

