    /// Brain v3 audit gap #2 — the startup REPAIR TICK is complete and IDEMPOTENT:
    /// - model-ABSENT pass: documents with no chunks get a chunk-only backfill (keyword retrieval
    ///   works on a default install); meetings untouched (no chunk-only mode → stub vectors).
    /// - model-PRESENT pass: chunked-but-vectorless docs re-embed, note-carrying meetings with no
    ///   chunks index (note + transcript + vectors), kind-routing keeps front-matter out.
    /// - re-run: full coverage ⇒ `(0, 0)` — a no-op.
    #[test]
    fn repair_tick_backfills_missing_indexes_idempotently() {
        let state = build_state("repair-tick-idempotent");
        make_open_folder(&state.db, "f-open", "Team");
        seed_meeting(
            &state.db,
            "m1",
            "# Plan\n\nquarterly zzmeetingtoken details",
            Some("f-open"),
        );
        state
            .db
            .insert_document(
                "d1",
                "f-open",
                "spec.md",
                "spec zzdoctoken body",
                "document",
                1,
            )
            .unwrap();
        state
            .db
            .insert_note(
                "n1",
                "f-open",
                "note",
                "Note",
                "---\ntags: [zztickfmtag]\n---\n\nnote zznotetoken body",
                1,
            )
            .unwrap();
        // Fix 3c: a permanently-EMPTY note (zero chunks forever) rides along — it must never be
        // counted as backfilled work in ANY pass (pre-fix it re-counted on every run, so the
        // pass-1/2 doc counts read 3 and the tick never became a reported no-op: RED).
        state
            .db
            .insert_note("n-empty", "f-open", "empty", "Empty", "", 1)
            .unwrap();

        // PASS 1 — MODEL ABSENT.
        let (meetings, docs) =
            backfill_missing_brain_indexes(&state.db, true, false, &crate::embed::StubEmbedder)
                .unwrap();
        assert_eq!(
            meetings, 0,
            "model absent: no meeting indexing (no stub vectors)"
        );
        assert_eq!(
                            docs, 2,
                            "model absent: both non-empty documents chunk-only backfilled (the empty row is zero-yield, never counted)"
                        );
        let (d_chunks, d_vecs) = state.db.doc_chunk_vector_counts("d1").unwrap();
        assert!(d_chunks > 0, "doc chunks present after the chunk-only pass");
        assert_eq!(d_vecs, 0, "no vectors without the model");
        assert_eq!(state.db.note_chunk_count("m1").unwrap(), 0);

        // PASS 2 — MODEL PRESENT (the model-arrived-later recovery the audit gap describes).
        let (meetings, docs) =
            backfill_missing_brain_indexes(&state.db, true, true, &crate::embed::StubEmbedder).unwrap();
        assert_eq!(meetings, 1, "the note-carrying meeting is indexed");
        assert_eq!(
            docs, 2,
            "chunked-but-vectorless docs re-embed once the model arrives"
        );
        assert!(state.db.doc_chunk_vector_counts("d1").unwrap().1 > 0);
        assert!(state.db.note_chunk_count("m1").unwrap() > 0);
        assert!(state.db.note_vec_count("m1").unwrap() > 0);
        // Kind routing respected (audit gap #3): the authored note's chunks carry no front-matter.
        let note_chunks = state.db.doc_chunk_texts("n1").unwrap().join("\n");
        assert!(note_chunks.contains("zznotetoken"));
        assert!(!note_chunks.contains("zztickfmtag"));

        // PASS 3 — IDEMPOTENT: full coverage ⇒ a re-run touches nothing.
        let (meetings, docs) =
            backfill_missing_brain_indexes(&state.db, true, true, &crate::embed::StubEmbedder).unwrap();
        assert_eq!((meetings, docs), (0, 0), "re-run is a no-op");
    }

    /// Brain v3 audit gap #2, the FLAG leg: the tick is an AUTOMATIC index, so its meeting half
    /// respects `semantic_search_enabled` exactly like the pipeline's `should_auto_index` and the
    /// topic backfill — flag OFF ⇒ no meeting indexing even with the model present.
    #[test]
    fn repair_tick_meeting_half_respects_semantic_flag() {
        let state = build_state("repair-tick-flag-off");
        make_open_folder(&state.db, "f-open", "Team");
        seed_meeting(&state.db, "m1", "# Plan\n\nnotes", Some("f-open"));
        let (meetings, _docs) =
            backfill_missing_brain_indexes(&state.db, false, true, &crate::embed::StubEmbedder)
                .unwrap();
        assert_eq!(
            meetings, 0,
            "flag OFF: an automatic tick never indexes meetings (should_auto_index posture)"
        );
        assert_eq!(state.db.note_chunk_count("m1").unwrap(), 0);
    }

    /// Brain v3 audit gap #2, the LOCK-DISCIPLINE leg (the consolidation invariant): the repair tick
    /// reads with the EMPTY unlock set, so a SEALED folder's meeting is never touched — even in the
    /// worst case where the folder is session-unlocked and its note plaintext is restored (a
    /// live-unlock-set bug would index that plaintext; the empty set must not).
    #[test]
    fn repair_tick_never_touches_sealed_folder_even_mid_session_unlock() {
        let state = build_state("repair-tick-sealed");
        make_open_folder(&state.db, "f-lock", "Secret");
        seed_meeting(
            &state.db,
            "m1",
            "# Secret\n\nzzsealedtoken plan",
            Some("f-lock"),
        );
        lock_folder_inner(&state, "f-lock".to_string()).unwrap();
        assert_eq!(
            state.db.note_chunk_count("m1").unwrap(),
            0,
            "purged on lock"
        );

        // Session-unlock (folder in the LIVE unlock set) + restore the note plaintext.
        let ck = session_unlock(&state, "f-lock");
        for n in state.db.notes_in_folder("f-lock").unwrap() {
            if let Some(blob) = &n.content_blob {
                let aad = aad_content("f-lock", &n.meeting_id, &n.provider_id, "note");
                let pt = crate::crypto::decrypt(&ck, blob, &aad).unwrap();
                state
                    .db
                    .restore_note_markdown(
                        &n.meeting_id,
                        &n.provider_id,
                        &String::from_utf8(pt).unwrap(),
                    )
                    .unwrap();
            }
        }

        let (meetings, docs) =
            backfill_missing_brain_indexes(&state.db, true, true, &crate::embed::StubEmbedder).unwrap();
        assert_eq!(
            (meetings, docs),
            (0, 0),
            "a sealed folder's content is never touched — even while session-unlocked"
        );
        assert_eq!(
            state.db.note_chunk_count("m1").unwrap(),
            0,
            "no chunks materialize for the sealed meeting"
        );
    }

    /// Brain v3 perf audit fix 3 (RED-before-GREEN): the repair tick had NO per-run cap — a vault
    /// with hundreds of missing rows re-embedded EVERYTHING on one launch (the class the 2026-07-13
    /// launch freeze pinned on the topic backfill, whose `TOPIC_BACKFILL_MAX_REEMBED_PER_RUN` this
    /// mirrors). With the cap forced small, one run performs exactly `cap` REAL index ops and the
    /// next run RESUMES where it left off (the needs-probe is the cursor — no state carried).
    /// Pre-fix everything indexed in one pass: RED.
    #[test]
    fn repair_tick_caps_real_index_ops_per_run_and_resumes_next_launch() {
        let state = build_state("repair-tick-cap");
        make_open_folder(&state.db, "f-open", "Team");
        for i in 0..4 {
            state
                .db
                .insert_document(
                    &format!("d{i}"),
                    "f-open",
                    &format!("doc{i}.md"),
                    &format!("doc {i} body paragraph"),
                    "document",
                    (i + 1) as i64,
                )
                .unwrap();
        }
        seed_meeting(&state.db, "m1", "# Plan\n\nbudget line", Some("f-open"));

        // RUN 1 (cap 2): exactly two docs (oldest-first) — no budget left for the meeting half.
        let (m, d) = backfill_missing_brain_indexes_capped(
            &state.db,
            true,
            true,
            &crate::embed::StubEmbedder,
            2,
            None,
        )
        .unwrap();
        assert_eq!(
            (m, d),
            (0, 2),
            "run 1 spends the whole cap on the first two docs"
        );
        let covered = (0..4)
            .filter(|i| {
                state
                    .db
                    .doc_chunk_vector_counts(&format!("d{i}"))
                    .unwrap()
                    .0
                    > 0
            })
            .count();
        assert_eq!(covered, 2, "exactly cap-many docs are indexed in one run");
        assert_eq!(
            state.db.note_chunk_count("m1").unwrap(),
            0,
            "the meeting half gets no leftover budget in run 1"
        );

        // RUN 2: resumes with the remaining two docs (the needs-probe skips the covered ones).
        let (m, d) = backfill_missing_brain_indexes_capped(
            &state.db,
            true,
            true,
            &crate::embed::StubEmbedder,
            2,
            None,
        )
        .unwrap();
        assert_eq!((m, d), (0, 2), "run 2 continues from where run 1 stopped");

        // RUN 3: docs covered → the leftover budget finally reaches the meeting half.
        let (m, d) = backfill_missing_brain_indexes_capped(
            &state.db,
            true,
            true,
            &crate::embed::StubEmbedder,
            2,
            None,
        )
        .unwrap();
        assert_eq!(
            (m, d),
            (1, 0),
            "run 3 indexes the meeting with the freed budget"
        );
        assert!(state.db.note_chunk_count("m1").unwrap() > 0);

        // RUN 4: full coverage ⇒ a no-op (idempotence preserved under the cap).
        let (m, d) = backfill_missing_brain_indexes_capped(
            &state.db,
            true,
            true,
            &crate::embed::StubEmbedder,
            2,
            None,
        )
        .unwrap();
        assert_eq!((m, d), (0, 0), "a capped tick still converges to the no-op");
    }

    /// Fix 3c (RED-before-GREEN): a row that yields NOTHING (an empty-bodied note produces zero
    /// chunks, forever) must neither consume the per-run cap nor count as backfilled work —
    /// otherwise a vault with permanently-empty rows re-burns the cap on every launch and the
    /// tail of REAL missing rows behind them never gets indexed. Pre-fix every attempted row was
    /// counted: RED.
    #[test]
    fn repair_tick_zero_yield_rows_never_consume_the_cap() {
        let state = build_state("repair-tick-zero-yield");
        make_open_folder(&state.db, "f-open", "Team");
        // Oldest row first: an EMPTY note (zero chunks forever), then a real doc behind it.
        state
            .db
            .insert_note("n-empty", "f-open", "empty", "Empty", "", 1)
            .unwrap();
        state
            .db
            .insert_document(
                "d-real",
                "f-open",
                "doc.md",
                "real doc body paragraph",
                "document",
                2,
            )
            .unwrap();

        // Cap 1: the empty note is probed first but yields nothing — the ONE budget slot must
        // still reach the real doc behind it.
        let (m, d) = backfill_missing_brain_indexes_capped(
            &state.db,
            true,
            true,
            &crate::embed::StubEmbedder,
            1,
            None,
        )
        .unwrap();
        assert_eq!(
            (m, d),
            (0, 1),
            "only the REAL doc counts as backfilled work"
        );
        assert!(
            state.db.doc_chunk_vector_counts("d-real").unwrap().0 > 0,
            "the real doc got the cap slot despite the zero-yield row ahead of it"
        );

        // Re-run: the empty row is re-probed (still zero-yield) — never counted, so the tick
        // reports the honest no-op.
        let (m, d) = backfill_missing_brain_indexes_capped(
            &state.db,
            true,
            true,
            &crate::embed::StubEmbedder,
            1,
            None,
        )
        .unwrap();
        assert_eq!(
            (m, d),
            (0, 0),
            "zero-yield rows are not 'work' — the re-run is a no-op"
        );
    }

    /// RELOCK re-purges the freshly-rebuilt meeting chunks: a lock → unlock (re-index) → relock cycle
    /// must leave ZERO meeting chunks/vectors at rest — `relock_folder` → `blank_sealed_notes_in_folders`
    /// → `purge_chunks_tx` covers the rows the unlock re-index rebuilt, so a re-sealed folder never
    /// leaves a meeting vector at rest.
    #[test]
    fn lock_unlock_relock_leaves_zero_meeting_chunks() {
        let state = build_state("relock-repurge-meetings");
        make_open_folder(&state.db, "f-lock", "Secret");
        seed_meeting(
            &state.db,
            "m1",
            "# Notes\n\nlaunch on the 14th; hire two engineers",
            Some("f-lock"),
        );
        state
            .db
            .index_meeting_chunks("m1", &[], &crate::embed::StubEmbedder)
            .unwrap();

        // Lock → purge.
        lock_folder_inner(&state, "f-lock".to_string()).unwrap();
        assert_eq!(
            state.db.note_chunk_count("m1").unwrap(),
            0,
            "purged on lock"
        );

        // Session-unlock: restore markdown + the PRODUCTION unseal with a present (stub) model, which
        // rebuilds the meeting chunks — so the relock below has something to re-purge.
        let ck = restore_notes_and_ck(&state, "f-lock");
        unseal_folder_extras(&state, "f-lock", &ck, Some(&crate::embed::StubEmbedder)).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-lock".to_string());
        assert!(
            state.db.note_chunk_count("m1").unwrap() > 0,
            "precondition: meeting re-indexed while session-unlocked"
        );
        assert!(
            state.db.note_vec_count("m1").unwrap() > 0,
            "precondition: vectors rebuilt"
        );

        // RELOCK → re-purge. Zero meeting chunks AND zero vectors at rest.
        relock_all_inner(&state).unwrap();
        assert_eq!(
            state.db.note_chunk_count("m1").unwrap(),
            0,
            "relock must re-purge the meeting note_chunks the unlock re-index rebuilt"
        );
        assert_eq!(
            state.db.note_vec_count("m1").unwrap(),
            0,
            "relock must re-purge the rebuilt meeting vec_chunks (no invertible vector at rest)"
        );
    }

    /// REINDEX BACKFILL (PR B): `reindex_embeddings_inner` covers documents. Model ABSENT →
    /// write-only (chunkless) documents gain chunks + FTS reachability with ZERO vectors, while an
    /// already-chunked document's existing vectors are NOT purged (no downgrade). Model PRESENT →
    /// the chunkless document is re-embedded with vectors too.
    #[test]
    fn reindex_backfills_documents_regardless_of_model() {
        let state = build_state("reindex-docs");
        make_open_folder(&state.db, "f-open", "Project");
        // A write-only legacy row: document stored, never chunked (the pre-PR-B model-less ingest).
        state
            .db
            .insert_document(
                "d-legacy",
                "f-open",
                "legacy.md",
                "szmaragdowy raport roczny",
                "document",
                100,
            )
            .unwrap();
        // An already-indexed document WITH vectors (stub-deterministic).
        state
            .db
            .insert_document(
                "d-vec",
                "f-open",
                "vec.md",
                "vectored content here",
                "document",
                200,
            )
            .unwrap();
        state
            .db
            .index_document_chunks("d-vec", Some(&crate::embed::StubEmbedder))
            .unwrap();
        let vec_before = state.db.doc_vec_count("d-vec").unwrap();
        assert!(vec_before >= 1, "precondition: d-vec has vectors");
        assert_eq!(
            state.db.doc_chunk_count("d-legacy").unwrap(),
            0,
            "precondition: d-legacy chunkless"
        );

        // Model ABSENT: chunk/FTS backfill only.
        let nothing = HashSet::new();
        let stub = crate::embed::StubEmbedder;
        let res = reindex_embeddings_inner(&state.db, &nothing, false, &stub, |_, _| {}).unwrap();
        assert_eq!(res.status, "model_missing", "meeting semantics unchanged");
        assert!(
            state.db.doc_chunk_count("d-legacy").unwrap() >= 1,
            "legacy doc backfilled"
        );
        assert_eq!(
            state.db.doc_vec_count("d-legacy").unwrap(),
            0,
            "no stub vectors on backfill"
        );
        assert_eq!(
            state.db.doc_vec_count("d-vec").unwrap(),
            vec_before,
            "model-absent reindex must NOT purge an indexed document's vectors"
        );
        assert!(
            state
                .db
                .search_doc_chunks_fts_visible("szmaragdowy", 10, &nothing)
                .unwrap()
                .iter()
                .any(|h| h.document_id == "d-legacy"),
            "backfilled document must be keyword-findable"
        );

        // Model PRESENT: the full purge-then-reinsert re-embed covers documents.
        let res2 = reindex_embeddings_inner(&state.db, &nothing, true, &stub, |_, _| {}).unwrap();
        assert_eq!(res2.status, "indexed");
        assert!(
            state.db.doc_vec_count("d-legacy").unwrap() >= 1,
            "model-present reindex must (re)embed document chunks"
        );
    }

    /// BLK-1: hammer the off-thread `relock_all_inner` (the blanker) WHILE `remove_lock_inner` runs
    /// its restore→clear sequence, across many seal/remove cycles, and assert the IRREVERSIBLE-LOSS
    /// state — a note with `markdown=''` AND `content_blob=NULL` — NEVER occurs. The coarse
    /// `AppState::lifecycle` mutex serializes the two so the blank can never land between
    /// `remove_lock`'s Step 1 (restore plaintext) and Step 2 (clear blob).
    #[test]
    fn relock_all_never_destroys_a_note_being_remove_locked() {
        const MID: &str = "m-blk1";
        const FOLDER: &str = "f-blk1";
        const ORIGINAL_MD: &str = "# Board notes\n\n- launch on the 14th\n- hire two engineers";

        let state = Arc::new(build_state("blk1"));
        make_open_folder(&state.db, FOLDER, "Confidential");
        seed_meeting(&state.db, MID, ORIGINAL_MD, Some(FOLDER));

        // A background thread that spams the off-thread blanker continuously.
        let stop = Arc::new(AtomicBool::new(false));
        let spammer = {
            let state = Arc::clone(&state);
            let stop = Arc::clone(&stop);
            std::thread::spawn(move || {
                while !stop.load(Ordering::Relaxed) {
                    // Ignore errors — a busy WAL checkpoint etc. is non-fatal to the invariant.
                    let _ = relock_all_inner(&state);
                }
            })
        };

        const ITERS: usize = 60;
        for i in 0..ITERS {
            // Seal the folder (note markdown → '' + content_blob set), then permanently remove the
            // lock (restore plaintext, clear blob). The blanker is racing the whole time.
            lock_folder_inner(&state, FOLDER.to_string()).unwrap();
            remove_lock_inner(&state, FOLDER.to_string()).unwrap();

            // The load-bearing invariant: no provider row is ever blanked-AND-blob-cleared, and the
            // restore put the ORIGINAL content back with the blob gone (folder fully open again).
            for n in state.db.sealable_notes_for_meeting(MID).unwrap() {
                assert!(
                    !(n.markdown.is_empty() && n.content_blob.is_none()),
                    "IRREVERSIBLE DATA LOSS at iter {i}: markdown='' AND content_blob=NULL"
                );
                assert_eq!(
                    n.markdown, ORIGINAL_MD,
                    "note restored to original at iter {i}"
                );
                assert!(
                    n.content_blob.is_none(),
                    "content_blob cleared after remove_lock at iter {i}"
                );
            }
        }

        stop.store(true, Ordering::Relaxed);
        spammer.join().unwrap();

        // Final state: open folder, original content, no residual blob anywhere.
        assert!(!state.db.folder_by_id(FOLDER).unwrap().unwrap().locked);
        let note = state.db.get_latest_note_for_meeting(MID).unwrap().unwrap();
        assert_eq!(note.markdown, ORIGINAL_MD);
    }

    /// BLK-2 (reject half): moving a note INTO a locked folder that is NOT session-unlocked must be
    /// REJECTED (`AppError::Locked`) and leave the note untouched — never reassigned, never blanked.
    #[test]
    fn move_into_locked_not_unlocked_folder_rejects_and_leaves_note_intact() {
        const MID: &str = "m-blk2r";
        const TARGET: &str = "f-blk2r";
        const MD: &str = "# secret meeting\n\nplaintext that must not move into a locked folder";

        let state = build_state("blk2r");
        seed_meeting(&state.db, MID, MD, None); // at the vault root (open)
        make_open_folder(&state.db, TARGET, "Locked-Target-R");
        lock_folder_inner(&state, TARGET.to_string()).unwrap(); // seal it; NOT session-unlocked

        let res = move_into_locked_folder(&state, MID, TARGET);
        assert!(
            matches!(res, Err(AppError::Locked(_))),
            "must reject with Locked, got {res:?}"
        );

        // Untouched: still at the root, still plaintext, no blob.
        assert_eq!(
            state.db.folder_for_meeting(MID).unwrap(),
            None,
            "note was NOT reassigned"
        );
        let n = &state.db.sealable_notes_for_meeting(MID).unwrap()[0];
        assert_eq!(n.markdown, MD, "plaintext preserved");
        assert!(n.content_blob.is_none(), "never sealed");
    }

    /// The automatic update check is the only network call Murmur makes on its own initiative, so
    /// turning it off must mean NOTHING leaves the machine — and leaving it on must leave a trace.
    ///
    /// Both halves matter and they fail differently. A gate that lives only in the frontend is not a
    /// gate: the command is reachable over IPC regardless of what the UI decides, which is why the
    /// refusal is in `check_for_update_inner` before a request is built. And an unlogged call is one
    /// the user cannot audit after the fact, which is the whole point of the egress ledger.
    ///
    /// The refusal is asserted by its ERROR, not by counting packets — the check returns before any
    /// client exists, so there is no request to observe. What the ledger count proves is the
    /// converse: with the flag off, not even the intent-to-send was recorded, because there was no
    /// intent.
    #[test]
    fn the_automatic_update_check_is_refused_and_unledgered_when_it_is_turned_off() {
        let state = build_state("update-consent-off");
        state.config.lock().unwrap().update_check_enabled = false;

        let err = block_on(crate::update::check_for_update_inner(&state, false))
            .expect_err("an automatic check must refuse when the flag is off");
        assert!(
            matches!(err, AppError::Unavailable(ref m) if m.contains("turned off")),
            "the refusal must name itself rather than look like a network failure, got: {err:?}"
        );
        assert_eq!(
            state.db.count_share_egress_by_kind("update_check").unwrap(),
            0,
            "a refused check must leave NO egress row — nothing was sent, so nothing is logged"
        );
    }

    /// The toggle must SHOW what is actually stored, not a constant.
    ///
    /// Its sibling test covers the inbound direction only: it strips the key before deserializing,
    /// so it never looks at what `config_to_dto` put there. Review demonstrated the consequence by
    /// hardcoding `Some(true)` on the way out — all five update-check tests stayed green.
    ///
    /// The enforcement gate reads `AppConfig` directly rather than through the DTO, so a regression
    /// here would not re-enable the network call. It would do something subtler and arguably worse:
    /// show a user who turned the check OFF a switch that says ON, while the check stays off. A
    /// privacy control that misreports its own state is not a control.
    #[test]
    fn the_config_the_ui_reads_reports_the_stored_update_flag() {
        for stored in [false, true] {
            let cfg = crate::settings::config::AppConfig {
                update_check_enabled: stored,
                ..crate::settings::config::AppConfig::default()
            };
            assert_eq!(
                config_to_dto(&cfg).update_check_enabled,
                Some(stored),
                "the DTO must carry the stored value, not a constant"
            );
        }
    }

    /// A save that omits the field must NOT re-enable a check the user turned off.
    ///
    /// This is the test review wrote to disprove the doc comment I had written, and it was right:
    /// the field was a bare `bool` defaulted `true` by serde, passed straight through, so a DTO
    /// missing it flipped a stored `false` to `true`. The comment promised a guarantee the code did
    /// not deliver, which is worse than no comment.
    ///
    /// The neighbouring `mcp_require_token` really is a bare `bool` defaulting to `true`, and that
    /// is correct THERE: for a security requirement `true` is the safe direction. Here `true` means
    /// "call home", so the same default is the unsafe one. Copying the wrong sibling is how this
    /// happened, and it is why the field is now `Option<bool>` preserved against the live config.
    #[test]
    fn a_config_save_that_omits_the_update_flag_preserves_the_users_choice() {
        let current = crate::settings::config::AppConfig {
            update_check_enabled: false,
            ..crate::settings::config::AppConfig::default()
        };

        let mut json = serde_json::to_value(config_to_dto(&current)).unwrap();
        assert!(
            json.as_object_mut()
                .unwrap()
                .remove("updateCheckEnabled")
                .is_some(),
            "precondition: the field is present under this exact camelCase name before removal"
        );
        let omitted: AppConfigDto = serde_json::from_value(json).unwrap();

        assert!(
            !dto_to_config(omitted, &current).update_check_enabled,
            "an omitted field means 'the client said nothing', not 'turn it back on'"
        );
    }

    /// The ledger row survives a FAILED request, which is the whole reason it is written first.
    ///
    /// Review moved the `ledger_row` call to after the request and the previous test stayed green,
    /// because it hit the real `api.github.com` — which answers, from CI too. An ordering guard that
    /// only ever sees success proves nothing about the case it exists for. Pointing at an unroutable
    /// host makes the failure deterministic, so this pins the property instead of describing it: a
    /// request that left the machine and then failed still left the machine.
    #[test]
    fn a_failed_check_still_leaves_exactly_one_ledger_row() {
        let state = build_state("update-ledger-order");

        let result = block_on(crate::update::check_for_update_against(
            &state,
            true,
            // `.invalid` is reserved by RFC 2606 and never resolves.
            "http://murmur-update-check.invalid/latest",
        ));
        assert!(result.is_err(), "an unroutable host must fail the request");
        assert_eq!(
            state.db.count_share_egress_by_kind("update_check").unwrap(),
            1,
            "exactly one row: the attempt is logged before the request, and a failure neither \
             skips it nor duplicates it"
        );
    }

    /// The default is ON, and the automatic check must actually run under it.
    ///
    /// Both other gate tests set the flag to `false`, so a regression that ignored the stored config
    /// and simply refused every automatic check would pass them — while silently disabling update
    /// checking for every user who never touches the toggle, which is nearly all of them. This is
    /// the only test that would notice.
    #[test]
    fn an_automatic_check_proceeds_under_the_default_flag() {
        let state = build_state("update-consent-default");
        assert!(
            state.config.lock().unwrap().update_check_enabled,
            "precondition: the shipped default is ON"
        );

        let result = block_on(crate::update::check_for_update_against(
            &state,
            false,
            "http://murmur-update-check.invalid/latest",
        ));
        // The network fails by construction; what matters is that it got PAST the gate to try.
        assert!(
            !matches!(result, Err(AppError::Unavailable(ref m)) if m.contains("turned off")),
            "an automatic check must not be refused while the flag is on, got: {result:?}"
        );
        assert_eq!(
            state.db.count_share_egress_by_kind("update_check").unwrap(),
            1,
            "and it must be ledgered like any other egress"
        );
    }

    /// A manual check ignores the flag, and is ledgered like any other egress.
    ///
    /// Pressing a button that says it asks GitHub IS the consent; the flag governs what happens
    /// without the user asking. This test does not assert the network result — CI has no reachable
    /// GitHub and should not — only that the gate let it through and the ledger recorded the attempt
    /// BEFORE the request. A ledger that recorded only successes would hide exactly the calls worth
    /// auditing: one that left the machine and then timed out.
    #[test]
    fn a_manual_update_check_ignores_the_flag_and_is_ledgered_before_the_request() {
        let state = build_state("update-consent-manual");
        state.config.lock().unwrap().update_check_enabled = false;

        // The network call itself may fail in CI; the gate and the ledger are what is under test.
        let _ = block_on(crate::update::check_for_update_inner(&state, true));

        assert_eq!(
            state.db.count_share_egress_by_kind("update_check").unwrap(),
            1,
            "a manual check is consented by the press, so it proceeds past the flag and is logged"
        );
    }

    /// Moving a meeting into a locked folder must revoke the Ask conversations that drew on the
    /// folder it came FROM — the end-to-end oracle for a leak this repo actually shipped a fix for.
    ///
    /// The storage-layer test pins the decision where the bug was introduced (`purge_chunks_for_meetings`
    /// stays global). It structurally cannot see a DIFFERENT future mistake: someone reintroducing
    /// scoping with new logic inside `seal_moved_note` itself. This drives the real command path, so
    /// it would.
    ///
    /// Why it matters more than a storage test. `seal_moved_note` runs AFTER
    /// `move_meeting_with_attachments_sealed` has committed `UPDATE meetings SET folder_id = <dest>`,
    /// so anything deriving a purge scope there reads the DESTINATION and never the source. A
    /// conversation depending on the source folder then survives — still readable, still paraphrasing
    /// content the user has just put behind the biometric gate. The act of protecting it is what
    /// would leave it exposed. Both reviewers asked for this oracle; the lock model treats a
    /// sealed-content leak as a class that must carry one.
    #[test]
    fn moving_a_meeting_into_a_locked_folder_revokes_conversations_from_its_old_folder() {
        use crate::storage::models::AskConversationScope;

        const MID: &str = "m-askmove";
        const SOURCE: &str = "f-askmove-src";
        const TARGET: &str = "f-askmove-dst";

        let state = build_state("askmove");
        make_open_folder(&state.db, SOURCE, "Open-Source");
        seed_meeting(&state.db, MID, "# asked about this", Some(SOURCE));
        make_open_folder(&state.db, TARGET, "Locked-Target");
        lock_folder_inner(&state, TARGET.to_string()).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(TARGET.to_string());
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));

        // A durable conversation whose dependency names the SOURCE folder — what a user gets by
        // asking about this meeting while it still sits in the open folder.
        state
            .db
            .persist_ask_exchange(
                &AskConversationScope::Vault,
                None,
                "what did we decide",
                "a durable answer paraphrasing the meeting",
                &[],
                &[],
                &[],
                &[SOURCE.to_string()],
                "2026-09-03T10:00:00Z",
            )
            .unwrap();
        let unlocked = state.unlocked_folders.lock().unwrap().clone();
        assert_eq!(
            state
                .db
                .list_ask_conversation_ids(&AskConversationScope::Vault, &unlocked)
                .unwrap()
                .len(),
            1,
            "the conversation starts visible"
        );

        move_note_public_inner_impl(&state, MID.into(), Some(TARGET.into())).unwrap();

        assert_eq!(
            state.db.folder_for_meeting(MID).unwrap().as_deref(),
            Some(TARGET),
            "precondition: the move actually happened"
        );
        let unlocked = state.unlocked_folders.lock().unwrap().clone();
        let surviving = state
            .db
            .list_ask_conversation_ids(&AskConversationScope::Vault, &unlocked)
            .unwrap();
        assert!(
            surviving.is_empty(),
            "a conversation that drew on the SOURCE folder must not outlive the meeting's move into              a locked one — it can paraphrase content that is now sealed. Got {surviving:?}"
        );
    }

    /// BLK-2 (seal half): moving a note INTO a locked + SESSION-UNLOCKED folder seals it AT REST
    /// (`content_blob`/`text_blob` set) but keeps it READABLE IN-SESSION — the restored plaintext
    /// markdown + transcript come back exactly like the folder's other unlocked notes, so it never
    /// shows blank under the open padlock, and no vault `.md` is left behind.
    ///
    /// REGRESSION (RED-before-GREEN): before the fix, `seal_moved_note` blanked the plaintext and
    /// nothing restored it, so a note moved into a session-unlocked folder came back EMPTY under the
    /// open padlock (the "private note came back empty" bug the user hit). The OLD assertion
    /// `markdown.is_empty()` enshrined that bug; this asserts the correct in-session-readable state.
    #[test]
    fn public_move_note_into_locked_unlocked_folder_seals_the_moved_note() {
        const MID: &str = "m-blk2s";
        const TARGET: &str = "f-blk2s";
        const MD: &str = "# moving in\n\nthis becomes ciphertext at rest";

        let state = build_state("blk2s");
        seed_meeting(&state.db, MID, MD, None); // at the vault root (open, plaintext)
        make_open_folder(&state.db, TARGET, "Locked-Target-S");
        lock_folder_inner(&state, TARGET.to_string()).unwrap(); // seal the (empty) target

        // Make the target SESSION-UNLOCKED: in the unlock set + KEK cached (as a real unlock would).
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(TARGET.to_string());
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));

        move_note_public_inner_impl(&state, MID.into(), Some(TARGET.into())).unwrap();

        // Reassigned into the target, sealed AT REST (blob set) but READABLE IN-SESSION (plaintext
        // restored — the folder is session-unlocked, so it must read like its folder-mates).
        assert_eq!(
            state.db.folder_for_meeting(MID).unwrap().as_deref(),
            Some(TARGET)
        );
        let n = &state.db.sealable_notes_for_meeting(MID).unwrap()[0];
        assert!(
            n.content_blob.is_some(),
            "moved note must be sealed at rest (content_blob set)"
        );
        assert_eq!(
                            n.markdown, MD,
                            "moved note must stay READABLE in-session (regression: it used to come back empty under the open padlock)"
                        );
        assert!(
            n.exported_path.is_none(),
            "no vault .md for a note in a locked folder"
        );
        // The visible read path (what the meeting-detail UI uses) returns the note, NON-empty.
        let unlocked = state.unlocked_folders.lock().unwrap().clone();
        let visible = state
            .db
            .get_note_if_visible(MID, &unlocked)
            .unwrap()
            .expect("note is visible while its folder is session-unlocked");
        assert_eq!(
            visible.markdown, MD,
            "the meeting-detail read must show the moved note's content, not an empty note"
        );
        // Transcript: blob kept AT REST, but plaintext RESTORED for the session (not left blank).
        let restored_transcript: String = state
            .db
            .raw_segments(MID)
            .unwrap()
            .iter()
            .map(|s| s.text.clone())
            .collect::<Vec<_>>()
            .join(" ");
        assert!(
            !restored_transcript.trim().is_empty(),
            "transcript must be restored for the session (regression: left blank)"
        );
        for s in state.db.raw_segments(MID).unwrap() {
            assert!(s.text_blob.is_some(), "segment text_blob kept at rest");
        }

        // And it round-trips: a permanent remove-lock restores the original plaintext (no loss).
        remove_lock_inner(&state, TARGET.to_string()).unwrap();
        let restored = state.db.get_latest_note_for_meeting(MID).unwrap().unwrap();
        assert_eq!(
            restored.markdown, MD,
            "remove-lock restores the moved note's original content"
        );
    }

    /// A session unlock is not a permanent unseal: retained blobs remain relock authority. Moving
    /// out through the legacy seam would strand those blobs in an open domain and make the next
    /// ordinary move fail. Refuse before mutation and require removing the folder lock first.
    #[test]
    fn public_move_note_out_of_session_unlocked_folder_fails_before_mutation() {
        const MID: &str = "m-public-move-out-sealed";
        const SOURCE: &str = "f-public-move-out-sealed";
        const MD: &str = "# moving out\n\nthese bytes must survive the protection-domain move";

        let state = build_state("public-move-out-sealed");
        make_open_folder(&state.db, SOURCE, "Private source");
        seed_meeting(&state.db, MID, MD, Some(SOURCE));
        lock_folder_inner(&state, SOURCE.to_string()).unwrap();
        let ck = session_unlock(&state, SOURCE);
        for note in state.db.sealable_notes_for_meeting(MID).unwrap() {
            let blob = note.content_blob.as_ref().unwrap();
            let markdown = String::from_utf8(
                crate::crypto::decrypt(
                    &ck,
                    blob,
                    &aad_content(SOURCE, MID, &note.provider_id, "note"),
                )
                .unwrap(),
            )
            .unwrap();
            state
                .db
                .restore_note_markdown(MID, &note.provider_id, &markdown)
                .unwrap();
        }
        let transcript_before = state
            .db
            .get_segments(MID)
            .unwrap()
            .into_iter()
            .map(|segment| segment.text)
            .collect::<Vec<_>>()
            .join(" ");

        let error = move_note_public_inner_impl(&state, MID.into(), None)
            .expect_err("session unlock must not become a partial permanent unseal");

        assert!(matches!(error, AppError::Unavailable(_)), "{error:?}");
        assert_eq!(
            state.db.folder_for_meeting(MID).unwrap().as_deref(),
            Some(SOURCE)
        );
        assert_eq!(
            state
                .db
                .get_latest_note_for_meeting(MID)
                .unwrap()
                .unwrap()
                .markdown,
            MD
        );
        assert_eq!(
            state
                .db
                .get_segments(MID)
                .unwrap()
                .into_iter()
                .map(|segment| segment.text)
                .collect::<Vec<_>>()
                .join(" "),
            transcript_before
        );
    }

    /// The legacy sealed-domain mover does not own the authored companion transaction. Refuse the
    /// whole public move before touching either side instead of sealing only the meeting and leaving
    /// the linked document or its attachments readable in the old open folder.
    #[test]
    fn public_locked_domain_move_with_companion_fails_before_mutation() {
        const MID: &str = "m-public-locked-companion";
        const TARGET: &str = "f-public-locked-companion";

        let state = build_state("public-locked-companion");
        make_open_folder(&state.db, TARGET, "Private target");
        seed_meeting(&state.db, MID, "# Generated note", None);
        let companion = get_or_create_companion_note_inner(&state, MID).unwrap();
        update_note_doc_inner_with(
            &state,
            &companion.note_id,
            "Authored note",
            "# Authored note\n\nMust stay in its original domain.",
            None,
        )
        .unwrap();
        let meeting_before = state.db.get_latest_note_for_meeting(MID).unwrap().unwrap();
        let meeting_seals_before = state
            .db
            .sealable_notes_for_meeting(MID)
            .unwrap()
            .into_iter()
            .map(|note| (note.provider_id, note.markdown, note.content_blob))
            .collect::<Vec<_>>();
        let companion_before = state
            .db
            .get_note_row(&companion.note_id)
            .unwrap()
            .unwrap();

        lock_folder_inner(&state, TARGET.to_string()).unwrap();
        session_unlock(&state, TARGET);
        let error = move_note_public_inner_impl(&state, MID.into(), Some(TARGET.into()))
            .expect_err("a partial meeting-only seal must be refused");

        assert!(matches!(error, AppError::Unavailable(_)), "{error:?}");
        assert_eq!(state.db.folder_for_meeting(MID).unwrap(), None);
        let meeting_after = state.db.get_latest_note_for_meeting(MID).unwrap().unwrap();
        assert_eq!(meeting_after.markdown, meeting_before.markdown);
        assert_eq!(meeting_after.exported_path, meeting_before.exported_path);
        assert_eq!(
            state
                .db
                .sealable_notes_for_meeting(MID)
                .unwrap()
                .into_iter()
                .map(|note| (note.provider_id, note.markdown, note.content_blob))
                .collect::<Vec<_>>(),
            meeting_seals_before
        );
        let companion_after = state
            .db
            .get_note_row(&companion.note_id)
            .unwrap()
            .unwrap();
        assert_eq!(companion_after.folder_id, companion_before.folder_id);
        assert_eq!(companion_after.text, companion_before.text);
        assert_eq!(companion_after.sealed, companion_before.sealed);
        assert_eq!(companion_after.exported_path, companion_before.exported_path);
    }

    /// Auto-organize seam: [`classify_auto_file_target`] maps a classifier-chosen subfolder to the
    /// right BLK-2 outcome — Open for an unmanaged / open subfolder, RejectToRoot for a locked +
    /// not-session-unlocked folder (so plaintext never lands in a sealed dir), and SealInto for a
    /// locked + session-unlocked folder (write then seal, like a manual move).
    #[test]
    fn classify_auto_file_target_covers_open_locked_and_unlocked() {
        let state = build_state("autofile");

        // No subfolder / unmanaged subfolder → Open.
        assert_eq!(
            classify_auto_file_target(&state, None).unwrap(),
            AutoFileTarget::Open
        );
        assert_eq!(
            classify_auto_file_target(&state, Some("Nonexistent")).unwrap(),
            AutoFileTarget::Open,
            "a subfolder with no matching folder row writes as usual"
        );

        // An OPEN folder row → Open.
        make_open_folder(&state.db, "f-open", "Standups");
        assert_eq!(
            classify_auto_file_target(&state, Some("Standups")).unwrap(),
            AutoFileTarget::Open
        );

        // A LOCKED, not-session-unlocked folder → RejectToRoot (no CK to seal with).
        make_open_folder(&state.db, "f-locked", "Confidential");
        lock_folder_inner(&state, "f-locked".to_string()).unwrap();
        assert_eq!(
            classify_auto_file_target(&state, Some("Confidential")).unwrap(),
            AutoFileTarget::RejectToRoot,
            "plaintext must not be written into a locked, not-unlocked folder"
        );

        // Make it SESSION-UNLOCKED (in the set + KEK cached) → SealInto(folder_id).
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-locked".to_string());
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        assert_eq!(
            classify_auto_file_target(&state, Some("Confidential")).unwrap(),
            AutoFileTarget::SealInto("f-locked".to_string()),
            "a session-unlocked locked folder seals the auto-filed note in"
        );
    }

    /// Auto-organize seam (seal half): a note auto-filed into a session-unlocked locked folder via
    /// [`seal_auto_filed_note`] is sealed AT REST (blob set) but stays READABLE IN-SESSION (plaintext
    /// restored) and reassigned — exactly like a manual move. No plaintext `.md` survives in the
    /// sealed dir, and it never comes back empty under the open padlock (same regression as the manual
    /// move: the old `markdown.is_empty()` assertion enshrined the "came back empty" bug).
    #[test]
    fn seal_auto_filed_note_seals_into_unlocked_locked_folder() {
        const MID: &str = "m-autofile";
        const TARGET: &str = "f-autofile";
        const MD: &str = "# auto-filed\n\nthis becomes ciphertext at rest";

        let state = build_state("autofile-seal");
        seed_meeting(&state.db, MID, MD, None);
        make_open_folder(&state.db, TARGET, "AutoLocked");
        lock_folder_inner(&state, TARGET.to_string()).unwrap();
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(TARGET.to_string());
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));

        seal_auto_filed_note(&state, MID, TARGET).unwrap();

        assert_eq!(
            state.db.folder_for_meeting(MID).unwrap().as_deref(),
            Some(TARGET)
        );
        let n = &state.db.sealable_notes_for_meeting(MID).unwrap()[0];
        assert!(
            n.content_blob.is_some(),
            "auto-filed note sealed at rest (content_blob set)"
        );
        assert_eq!(
            n.markdown, MD,
            "auto-filed note must stay READABLE in-session (regression: it used to come back empty)"
        );
        // Visible read path returns the note, non-empty.
        let unlocked = state.unlocked_folders.lock().unwrap().clone();
        assert_eq!(
            state
                .db
                .get_note_if_visible(MID, &unlocked)
                .unwrap()
                .expect("auto-filed note visible while its folder is session-unlocked")
                .markdown,
            MD
        );
    }

    // ── retry_transcription prep gates (salvage-from-disk, 2026-07-16) ──────────────────────────

    struct ReleasedArchivedGenerationFixture {
        key: crate::storage::models::RecordingGenerationKey,
        mic_path: std::path::PathBuf,
        archive_path: std::path::PathBuf,
        archive_bytes: Vec<u8>,
    }

    fn stage_released_archived_generation(
        state: &AppState,
        meeting_id: &str,
        folder_id: Option<&str>,
    ) -> ReleasedArchivedGenerationFixture {
        seed_meeting(&state.db, meeting_id, "# cleanup retry", folder_id);
        let app_dir = crate::pipeline::recording_inflight_dir()
            .unwrap()
            .parent()
            .unwrap()
            .to_path_buf();
        let inflight = crate::pipeline::recording_inflight_dir().unwrap();
        let archive_dir = crate::pipeline::audio_dir().unwrap();
        let legacy = app_dir.join(format!("legacy-{meeting_id}.f32"));
        let mut raw = Vec::new();
        for sample in [0.25f32, -0.5, 0.75, -1.0] {
            raw.extend_from_slice(&sample.to_le_bytes());
        }
        std::fs::write(&legacy, raw).unwrap();
        let recording = crate::audio::source::adopt_legacy_raw_recording(
            &state.db, meeting_id, &legacy, 48_000, None, &inflight,
        )
        .unwrap();
        std::fs::remove_file(legacy).unwrap();
        let key = recording.key.clone();
        let mic_path = recording.mic_path.clone();
        let archive_path = archive_dir.join(format!("{}.archive.wav", key.generation_id()));
        let archive_bytes = b"RIFF-canonical-archive-v1".to_vec();
        std::fs::write(&archive_path, &archive_bytes).unwrap();
        let archive_file = crate::audio::source::verify_existing_file(&archive_path).unwrap();
        let archive =
            crate::storage::recording_store::VerifiedArchiveArtifact::from_file(&key, &archive_file)
                .unwrap();
        state
            .db
            .archive_recording_generation(&key, &recording.lease, &archive)
            .unwrap();
        recording.release_for_recovery(&state.db).unwrap();
        state
            .db
            .finalize_meeting(
                meeting_id,
                "2026-07-22T12:01:00Z",
                60,
                &archive_path.to_string_lossy(),
            )
            .unwrap();
        ReleasedArchivedGenerationFixture {
            key,
            mic_path,
            archive_path,
            archive_bytes,
        }
    }

    fn corrupt_archived_generation(fixture: &ReleasedArchivedGenerationFixture) {
        std::fs::write(&fixture.archive_path, b"RIFF-corrupted-archive-v1").unwrap();
    }

    fn restore_archived_generation(fixture: &ReleasedArchivedGenerationFixture) {
        std::fs::write(&fixture.archive_path, &fixture.archive_bytes).unwrap();
    }

    #[test]
    fn retry_reclaims_released_cleanup_after_transient_failure_without_restart() {
        let app_dir = std::env::temp_dir().join(format!(
            "murmur-retry-reclaim-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        crate::pipeline::with_test_recording_app_dir(app_dir.clone(), || {
            let state = build_state("retry-reclaim");
            let meeting_id = uuid::Uuid::new_v4().hyphenated().to_string();
            let fixture = stage_released_archived_generation(&state, &meeting_id, None);
            state
                .db
                .update_meeting_status(&meeting_id, MeetingStatus::Error)
                .unwrap();

            corrupt_archived_generation(&fixture);
            assert!(retry_transcription_prep(&state, &meeting_id).is_err());
            assert_eq!(
                state.db.get_meeting(&meeting_id).unwrap().unwrap().status,
                MeetingStatus::Error,
                "failed cleanup must not claim the ordinary retry"
            );
            restore_archived_generation(&fixture);

            assert_eq!(
                retry_transcription_prep(&state, &meeting_id).unwrap(),
                fixture.archive_path
            );
            assert_eq!(
                state
                    .db
                    .get_recording_generation_snapshot(&fixture.key)
                    .unwrap()
                    .unwrap()
                    .state,
                crate::storage::models::RecordingGenerationState::Retired
            );
            assert!(!fixture.mic_path.exists());
            assert!(fixture.archive_path.exists());
        });
        std::fs::remove_dir_all(app_dir).unwrap();
    }

    #[test]
    fn delete_reclaims_released_cleanup_after_transient_failure_without_restart() {
        let app_dir = std::env::temp_dir().join(format!(
            "murmur-delete-reclaim-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        crate::pipeline::with_test_recording_app_dir(app_dir.clone(), || {
            let state = build_state("delete-reclaim");
            let meeting_id = uuid::Uuid::new_v4().hyphenated().to_string();
            let fixture = stage_released_archived_generation(&state, &meeting_id, None);

            corrupt_archived_generation(&fixture);
            assert!(block_on(delete_meeting_inner(&state, &meeting_id)).is_err());
            assert!(state.db.get_meeting(&meeting_id).unwrap().is_some());
            restore_archived_generation(&fixture);

            block_on(delete_meeting_inner(&state, &meeting_id)).unwrap();
            assert!(state.db.get_meeting(&meeting_id).unwrap().is_none());
            assert!(state
                .db
                .get_recording_generation_snapshot(&fixture.key)
                .unwrap()
                .is_none());
            assert!(!fixture.mic_path.exists());

            // TRASH (2026-08-31) — the contract CHANGED here, so the assertion moved rather than
            // being dropped. `stage_released_archived_generation` passes `archive_path` to
            // `finalize_meeting`, which records it as the meeting's `audio_path` — i.e. this file is
            // the recording's PLAYBACK AUDIO, not a spent generation artifact like `mic_path` above.
            // A delete now moves the recording to the Trash, and the snapshot references that file
            // BY PATH, so unlinking it here would make the entry unrestorable the instant it was
            // created: restore would hand back a silent meeting. The file is retained on purpose,
            // and PURGING the entry is what reclaims it — which is asserted below, so this test
            // still pins "the audio eventually goes away" instead of merely dropping the guarantee.
            assert!(
                fixture.archive_path.exists(),
                "a to-trash delete must keep the playback audio — it is the only copy"
            );
            let entry = state
                .db
                .list_trash_entries()
                .unwrap()
                .into_iter()
                .find(|e| e.source_id == meeting_id)
                .expect("the delete moved the recording into the trash");
            block_on(purge_one_for_test(&state, &entry.id)).unwrap();
            assert!(
                !fixture.archive_path.exists(),
                "purging the trash entry reclaims the audio the delete kept"
            );
        });
        std::fs::remove_dir_all(app_dir).unwrap();
    }

