    #[test]
    fn locked_move_retries_cleanup_and_never_assigns_persistent_plaintext_generation() {
        let app_dir = std::env::temp_dir().join(format!(
            "murmur-move-reclaim-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        crate::pipeline::with_test_recording_app_dir(app_dir.clone(), || {
            let state = build_state("move-reclaim");
            let folder_id = format!("f-{}", uuid::Uuid::new_v4());
            make_open_folder(&state.db, &folder_id, "MoveLocked");
            lock_folder_inner(&state, folder_id.clone()).unwrap();
            session_unlock(&state, &folder_id);

            // An expired ARCHIVED generation whose first cleanup attempt fails must stay at root.
            // Restoring the exact canonical archive lets the very next Move in this process claim,
            // clean, retire, and only then assign+seal it into the locked folder.
            let meeting_id = uuid::Uuid::new_v4().hyphenated().to_string();
            let fixture = stage_released_archived_generation(&state, &meeting_id, None);
            corrupt_archived_generation(&fixture);
            assert!(move_into_locked_folder(&state, &meeting_id, &folder_id).is_err());
            assert_eq!(state.db.folder_for_meeting(&meeting_id).unwrap(), None);
            restore_archived_generation(&fixture);
            move_into_locked_folder(&state, &meeting_id, &folder_id).unwrap();
            assert_eq!(
                state.db.folder_for_meeting(&meeting_id).unwrap().as_deref(),
                Some(folder_id.as_str())
            );
            assert_eq!(
                state
                    .db
                    .get_recording_generation_snapshot(&fixture.key)
                    .unwrap()
                    .unwrap()
                    .state,
                crate::storage::models::RecordingGenerationState::Retired
            );
            assert!(!fixture.mic_path.exists());

            // A genuinely live FINALIZED/raw generation is not cleanup-only recovery. It remains
            // nonterminal, Move refuses before association, and the exact raw file survives.
            let active_id = uuid::Uuid::new_v4().hyphenated().to_string();
            seed_meeting(&state.db, &active_id, "# still recovering", None);
            let inflight = crate::pipeline::recording_inflight_dir().unwrap();
            let legacy = app_dir.join(format!("legacy-{active_id}.f32"));
            std::fs::write(&legacy, 0.5f32.to_le_bytes()).unwrap();
            let active = crate::audio::source::adopt_legacy_raw_recording(
                &state.db, &active_id, &legacy, 48_000, None, &inflight,
            )
            .unwrap();
            std::fs::remove_file(legacy).unwrap();
            let raw_path = active.mic_path.clone();
            assert!(move_into_locked_folder(&state, &active_id, &folder_id).is_err());
            assert_eq!(state.db.folder_for_meeting(&active_id).unwrap(), None);
            assert!(
                raw_path.exists(),
                "refused Move preserves the exact raw source"
            );
            active.release_for_recovery(&state.db).unwrap();
        });
        std::fs::remove_dir_all(app_dir).unwrap();
    }

    /// Every fail-closed gate of `retry_transcription_prep`, in order: locked folder → `Locked`;
    /// non-Error status → refused; missing audio → refused; happy path claims `Error → Recording`
    /// exactly once (single-flight).
    #[test]
    fn retry_prep_refuses_while_recording_priority_is_starting_without_a_recorder_slot() {
        let _serial = crate::perf::model_lifecycle_test_guard();
        crate::perf::reset_model_lifecycle_for_test();
        let state = build_state("retry-prep-starting-priority");
        let owner = crate::perf::begin_recording_session().unwrap();

        // Starting deliberately precedes capture installation, so the recorder slot is empty.
        assert!(state.recorder.lock().unwrap().is_none());
        let result = retry_transcription_prep(&state, "not-reached");

        drop(owner);
        crate::perf::reset_model_lifecycle_for_test();
        assert!(matches!(result, Err(AppError::Audio(_))));
    }

    #[test]
    fn retry_prep_gates_fail_closed_then_claims_single_flight() {
        let state = build_state("retry-prep");

        // Unknown meeting.
        assert!(matches!(
            retry_transcription_prep(&state, "m-none"),
            Err(AppError::InvalidArg(_))
        ));

        // LOCKED folder → AppError::Locked (never re-pipeline sealed content).
        seed_meeting(&state.db, "m-locked", "# sealed", None);
        make_open_folder(&state.db, "f-retry-locked", "RetryLocked");
        state
            .db
            .set_meeting_folder("m-locked", Some("f-retry-locked"))
            .unwrap();
        lock_folder_inner(&state, "f-retry-locked".to_string()).unwrap();
        assert!(
            matches!(
                retry_transcription_prep(&state, "m-locked"),
                Err(AppError::Locked(_))
            ),
            "a sealed-and-not-session-unlocked meeting must refuse with Locked"
        );

        // Non-Error status refused (seed_meeting leaves the row Summarized).
        seed_meeting(&state.db, "m-summarized", "# fine", None);
        assert!(matches!(
            retry_transcription_prep(&state, "m-summarized"),
            Err(AppError::InvalidArg(_))
        ));

        // Error status but NO audio on disk → refused, row untouched.
        seed_meeting(&state.db, "m-no-audio", "# err", None);
        state
            .db
            .update_meeting_status("m-no-audio", MeetingStatus::Error)
            .unwrap();
        assert!(matches!(
            retry_transcription_prep(&state, "m-no-audio"),
            Err(AppError::Storage(_))
        ));
        assert_eq!(
            state.db.get_meeting("m-no-audio").unwrap().unwrap().status,
            MeetingStatus::Error,
            "a refused prep must not have claimed the row"
        );

        // A durable generation recovery owner wins over the ordinary archive Retry path. This
        // prevents a startup claim and a user click from transcribing/mutating the same meeting in
        // parallel.
        let owned_mid = uuid::Uuid::new_v4().to_string();
        seed_meeting(&state.db, &owned_mid, "# recovery-owned", None);
        state
            .db
            .update_meeting_status(&owned_mid, MeetingStatus::Error)
            .unwrap();
        let generation = crate::storage::models::RecordingGenerationKey::fresh(&owned_mid).unwrap();
        let mic =
            crate::storage::models::RecordingMicAssertion::for_generation(&generation, 48_000, 7, 11)
                .unwrap();
        let _owner = state
            .db
            .prepare_recording_generation(&generation, &mic, 120_000)
            .unwrap();
        assert!(matches!(
            retry_transcription_prep(&state, &owned_mid),
            Err(AppError::Storage(_))
        ));

        // Happy path: Error + a real on-disk WAV → claimed (Error → Recording), path resolved.
        let wav = std::env::temp_dir().join(format!("murmur-retry-prep-{}.wav", std::process::id()));
        std::fs::write(&wav, b"RIFF-fake").unwrap();
        seed_meeting(&state.db, "m-retry", "# err", None);
        state
            .db
            .finalize_meeting(
                "m-retry",
                "2026-07-16T10:00:00Z",
                60,
                &wav.to_string_lossy(),
            )
            .unwrap();
        state
            .db
            .update_meeting_status("m-retry", MeetingStatus::Error)
            .unwrap();
        let got = retry_transcription_prep(&state, "m-retry").unwrap();
        assert_eq!(got, wav);
        assert_eq!(
            state.db.get_meeting("m-retry").unwrap().unwrap().status,
            MeetingStatus::Recording,
            "the claim flips Error → Recording (crash-safe: next launch's disk salvage re-claims it)"
        );
        // Single-flight: the row is no longer Error, so a second prep refuses.
        assert!(retry_transcription_prep(&state, "m-retry").is_err());
        let _ = std::fs::remove_file(&wav);
    }

    /// RETRY FROM A DUAL-STREAM ARCHIVE — it is accepted, and it comes back MONO.
    ///
    /// A live recording keeps `Me` and `Others` apart by transcribing the microphone and the system
    /// capture separately and merging them on wall-clock. A retry has neither: the raw per-stream
    /// files are unlinked once the archive is proven durable (`cleanup_completed_archived_generation`
    /// runs on the failure path too), so all a retry ever gets is the single archived WAV — and
    /// `run_salvage_from_disk` opens it through `WavMonoSource`, which AVERAGES whatever channels it
    /// finds into one.
    ///
    /// So a recovered transcript legitimately loses its speaker split. This test pins that as the
    /// behaviour rather than leaving it to be discovered from a user's transcript: retry must keep
    /// WORKING for a two-channel archive (the row is claimed, the path resolves), and the audio it
    /// hands the pipeline is the channel mean, not a stream pair. If retry is ever taught to keep the
    /// separation, the second half of this test is the assertion that has to go red first.
    #[test]
    fn retry_prep_accepts_a_two_channel_archive_and_salvage_reads_it_as_the_channel_mean() {
        use crate::audio::source::MonoSource;

        let state = build_state("retry-dual-stream-archive");
        let wav = std::env::temp_dir().join(format!(
            "murmur-retry-dual-{}-{}.wav",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        // Interleaved L/R: the microphone hard left, the system capture hard right — the most
        // separable two-channel archive there could be.
        let interleaved: Vec<f32> = vec![1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 1.0, 0.0];
        crate::audio::write_wav_f32(&wav, &interleaved, 48_000, 2).unwrap();

        let mid = uuid::Uuid::new_v4().to_string();
        seed_meeting(&state.db, &mid, "# err", None);
        state
            .db
            .finalize_meeting(&mid, "2026-09-02T10:00:00Z", 60, &wav.to_string_lossy())
            .unwrap();
        state
            .db
            .update_meeting_status(&mid, MeetingStatus::Error)
            .unwrap();

        // A two-channel archive is still a retryable archive: nothing in the gate rejects it.
        let got = retry_transcription_prep(&state, &mid).unwrap();
        assert_eq!(got, wav);
        assert_eq!(
            state.db.get_meeting(&mid).unwrap().unwrap().status,
            MeetingStatus::Recording,
        );

        // And what salvage will actually feed Whisper is one mono track at the channel mean —
        // 0.5 everywhere, with neither the 1.0 microphone nor the 0.0 system side recoverable.
        let mut source = crate::audio::source::WavMonoSource::open(&wav).unwrap();
        assert_eq!(source.frames(), 4, "4 interleaved stereo frames");
        let frames = source.read_frames(0, 4).unwrap();
        assert_eq!(
            frames,
            vec![0.5, 0.5, 0.5, 0.5],
            "salvage averages the two streams together — the speaker split does not survive a retry"
        );

        let _ = std::fs::remove_file(&wav);
    }

    /// LOCK MODEL — a salvage/retry pins the folder CK at entry. If screen-share relock lands while
    /// Whisper is running, the finalizer seals and decrypt-verifies the exact new transcript/audio;
    /// it never deletes transcript rows merely because old audio exists. An open folder is a no-op.
    #[test]
    fn finalize_salvage_lock_state_seals_exact_output_after_a_relock() {
        let state = build_state("salvage-finalize");

        // No-op case first: an OPEN folder's meeting keeps its plaintext output.
        seed_meeting(&state.db, "m-open", "# open", None);
        finalize_salvage_lock_state(&state, "m-open", None);
        assert_eq!(
            state.db.get_segments("m-open").unwrap().len(),
            2,
            "an open/rootless meeting's fresh segments are untouched"
        );

        // Establish a real locked folder and verified encrypted audio, then session-unlock just
        // long enough to capture the one-shot salvage CK.
        let dir = std::env::temp_dir().join(format!("murmur-salvage-finalize-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let wav = dir.join("m-raced.wav");
        std::fs::write(&wav, b"RIFF-fresh-plaintext").unwrap();

        seed_meeting(&state.db, "m-raced", "# raced", None);
        state
            .db
            .finalize_meeting(
                "m-raced",
                "2026-07-16T10:00:00Z",
                60,
                &wav.to_string_lossy(),
            )
            .unwrap();
        state
            .db
            .insert_folder(&Folder {
                id: "f-raced".into(),
                name: "Raced".into(),
                path: "Raced".into(),
                parent_id: None,
                locked: false,
                created_at: "2026-07-16T00:00:00Z".into(),
            })
            .unwrap();
        state
            .db
            .set_meeting_folder("m-raced", Some("f-raced"))
            .unwrap();
        lock_folder_inner(&state, "f-raced".to_string()).unwrap();
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-raced".to_string());
        let seal_context = capture_salvage_seal_context(&state, "m-raced")
            .unwrap()
            .expect("locked session-unlocked salvage pins its CK");

        // Fresh pipeline output lands after the relock sweep. Remove the session markers to model
        // the screen-share race, while the finalizer retains only its scoped Zeroizing CK.
        state
            .db
            .replace_segments(
                "m-raced",
                &[Segment {
                    idx: 0,
                    start_s: 0.0,
                    end_s: 1.0,
                    text: "corrected exact transcript".into(),
                    speaker: Some("Me".into()),
                    confidence: Some(0.99),
                }],
            )
            .unwrap();
        std::fs::write(&wav, b"RIFF-fresh-after-relock").unwrap();
        state
            .db
            .set_meeting_audio_path("m-raced", Some(&wav.to_string_lossy()))
            .unwrap();
        state.unlocked_folders.lock().unwrap().clear();
        *state.master_kek.lock().unwrap() = None;

        finalize_salvage_lock_state(&state, "m-raced", Some(&seal_context));

        let sealed = state.db.raw_segments("m-raced").unwrap();
        assert_eq!(sealed.len(), 1, "the exact transcript row survives");
        assert!(
            sealed[0].text.is_empty() && sealed[0].text_blob.is_some(),
            "the exact transcript is authenticated and sealed, never re-derived or deleted"
        );
        assert!(
            !wav.exists(),
            "plaintext audio is removed only after a fresh authenticated seal"
        );
        assert!(
            dir.join("m-raced.wav.enc").exists(),
            "the finalizer publishes a verified encrypted audio artifact"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// LOCK MODEL — a salvage permit blocks only operations that could orphan its captured CK or
    /// discard/reassign the in-flight output. Session relock is deliberately still allowed so
    /// screen sharing can revoke every gated reader immediately.
    #[test]
    fn active_salvage_blocks_key_rotation_move_and_delete_but_allows_session_relock() {
        let state = build_state("salvage-permit");
        make_open_folder(&state.db, "f-permit", "Permit");
        seed_meeting(&state.db, "m-permit", "# exact", Some("f-permit"));

        let permit = begin_active_salvage(&state, "m-permit").unwrap();
        assert!(lock_folder_inner(&state, "f-permit".into()).is_err());
        assert!(move_note_inner_impl(&state, "m-permit".into(), None).is_err());
        assert!(block_on(delete_meeting_inner(&state, "m-permit")).is_err());
        assert!(delete_folder_inner(&state, "f-permit".into()).is_err());
        drop(permit);

        // Permit release makes a fresh seal possible. Once sealed, a second permit refuses the
        // permanent unlock (key destruction) while relock-all still revokes session visibility.
        lock_folder_inner(&state, "f-permit".into()).unwrap();
        let permit = begin_active_salvage(&state, "m-permit").unwrap();
        assert!(remove_lock_inner(&state, "f-permit".into()).is_err());
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-permit".into());
        relock_all_inner(&state).unwrap();
        assert!(state.unlocked_folders.lock().unwrap().is_empty());
        drop(permit);
    }

    /// LOCK MODEL — the finalizer's pinned CK is generation-bound. Even if storage is corrupted or
    /// bypasses the permit and swaps the folder's wrapped-key envelope, the stale context performs
    /// no seal/blank overwrite under an orphaned key.
    #[test]
    fn salvage_finalizer_refuses_a_changed_wrapped_key_generation_without_blanking() {
        let state = build_state("salvage-key-generation");
        make_open_folder(&state.db, "f-generation", "Generation");
        seed_meeting(
            &state.db,
            "m-generation",
            "# original note",
            Some("f-generation"),
        );
        lock_folder_inner(&state, "f-generation".into()).unwrap();
        let kek = secrets::get_or_create_master_kek().unwrap();
        *state.master_kek.lock().unwrap() = Some(Zeroizing::new(kek));
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-generation".into());
        let seal_context = capture_salvage_seal_context(&state, "m-generation")
            .unwrap()
            .expect("session-unlocked locked folder captures its key generation");
        let original_note_blob = state
            .db
            .sealable_notes_for_meeting("m-generation")
            .unwrap()
            .into_iter()
            .next()
            .unwrap()
            .content_blob;

        let replacement_ck = crate::crypto::random_key().unwrap();
        let replacement_wrapped =
            crate::crypto::encrypt(&kek, &replacement_ck, &aad_wrapped_ck("f-generation")).unwrap();
        state
            .db
            .set_folder_locked("f-generation", true, Some(&replacement_wrapped))
            .unwrap();
        state
            .db
            .replace_segments(
                "m-generation",
                &[Segment {
                    idx: 0,
                    start_s: 0.0,
                    end_s: 1.0,
                    text: "exact fresh transcript".into(),
                    speaker: Some("Me".into()),
                    confidence: Some(0.99),
                }],
            )
            .unwrap();
        state.unlocked_folders.lock().unwrap().clear();
        *state.master_kek.lock().unwrap() = None;

        finalize_salvage_lock_state(&state, "m-generation", Some(&seal_context));

        let segments = state.db.raw_segments("m-generation").unwrap();
        assert_eq!(segments[0].text, "exact fresh transcript");
        assert!(segments[0].text_blob.is_none());
        assert_eq!(
            state
                .db
                .sealable_notes_for_meeting("m-generation")
                .unwrap()
                .into_iter()
                .next()
                .unwrap()
                .content_blob,
            original_note_blob,
            "a stale salvage CK never overwrites the current generation's note blob"
        );
    }

    #[derive(Default)]
    struct FinalizedEventRecorder(std::cell::RefCell<Vec<String>>);

    impl crate::events::RecordingTerminalNotifier for FinalizedEventRecorder {
        fn recording_finalized(&self, meeting_id: &str) {
            self.0.borrow_mut().push(meeting_id.to_string());
        }

        fn recording_cleanup_failed(&self, _meeting_id: &str) {
            panic!("the post-await visibility seam never reports a recovery cleanup failure");
        }
    }

    /// The terminal command response is a navigation token, never a second content channel. The
    /// renderer hydrates the exact meeting through `get_meeting_detail`, where the lock gate masks
    /// note content and audio paths. Bind the producing Rust wire shape, not an E2E mock.
    #[test]
    fn stop_result_wire_is_content_free_meeting_id_only() {
        let json = serde_json::to_value(StopResult {
            meeting_id: "meeting-42".into(),
        })
        .unwrap();
        assert_eq!(json, serde_json::json!({ "meetingId": "meeting-42" }));
        let raw = json.to_string();
        assert!(!raw.contains("markdown"));
        assert!(!raw.contains("exportedPath"));
    }

    /// Model the detached Stop after its long pipeline/model-retirement tail: a relock that wins
    /// before the owner's final boundary advances the visibility epoch, so completion must return
    /// `Locked`, emit no `finalized`, and retain only the opaque id in the successful open case.
    #[test]
    fn stop_owner_completion_fails_closed_when_relock_wins_after_tail() {
        let state = build_state("stop-owner-finalized-gate");
        make_open_folder(&state.db, "f-stop-result", "Stop result");
        seed_meeting(
            &state.db,
            "m-stop-result",
            "# pipeline result",
            Some("f-stop-result"),
        );
        let epoch_before = state.seal_epoch.load(std::sync::atomic::Ordering::SeqCst);

        // This represents manual/screen-share relock winning during the owner's long tail.
        lock_folder_inner(&state, "f-stop-result".into()).unwrap();
        assert!(state.seal_epoch.load(std::sync::atomic::Ordering::SeqCst) > epoch_before);

        let recorder = FinalizedEventRecorder::default();
        let error = complete_stop_after_visibility(&state, &recorder, "m-stop-result").unwrap_err();
        assert!(matches!(error, AppError::Locked(_)));
        assert!(
            recorder.0.borrow().is_empty(),
            "a Stop owner must never publish finalized after relock"
        );

        let visible = build_state("stop-owner-finalized-open");
        seed_meeting(&visible.db, "m-stop-visible", "# visible", None);
        let result = complete_stop_after_visibility(&visible, &recorder, "m-stop-visible").unwrap();
        assert_eq!(result.meeting_id, "m-stop-visible");
        assert_eq!(recorder.0.borrow().as_slice(), ["m-stop-visible"]);
        assert_eq!(
            serde_json::to_value(result).unwrap(),
            serde_json::json!({ "meetingId": "m-stop-visible" })
        );
    }

    /// A cached pipeline markdown must not cross IPC after the folder is relocked during a long
    /// await. The shared re-summarize/retry terminal seam fails closed before emitting `finalized`,
    /// even though the caller still owns the String. An open result emits exactly once.
    #[test]
    fn resummarize_and_retry_finalized_gate_refuses_cached_plaintext_after_relock() {
        let state = build_state("post-await-result-gate");
        make_open_folder(&state.db, "f-result", "Result");
        seed_meeting(
            &state.db,
            "m-result",
            "# cached plaintext",
            Some("f-result"),
        );
        lock_folder_inner(&state, "f-result".into()).unwrap();

        let cached_markdown = "# cached plaintext".to_string();
        let recorder = FinalizedEventRecorder::default();
        let error =
            emit_recording_finalized_after_visibility(&state, &recorder, "m-result").unwrap_err();
        assert!(matches!(error, AppError::Locked(_)));
        assert_eq!(cached_markdown, "# cached plaintext");
        assert!(
            recorder.0.borrow().is_empty(),
            "a relocked result must never publish finalized"
        );

        let visible = build_state("post-await-visible-result");
        seed_meeting(&visible.db, "m-visible", "# visible", None);
        emit_recording_finalized_after_visibility(&visible, &recorder, "m-visible").unwrap();
        assert_eq!(recorder.0.borrow().as_slice(), ["m-visible"]);
    }

    /// A multi-source synthesis is invalidated by any lock-generation transition, even if the
    /// caller still owns the assembled corpus/result in RAM.
    #[test]
    fn content_visibility_snapshot_refuses_a_late_result_after_epoch_change() {
        let state = build_state("content-visibility-epoch");
        let snapshot = capture_content_visibility_snapshot(&state);

        bump_seal_epoch(&state);

        assert!(matches!(
            require_current_content_visibility_snapshot(&state, snapshot),
            Err(AppError::Locked(_))
        ));
    }

    /// Regression for a shipped deadlock: Living Answer preflight already owns the non-reentrant
    /// lifecycle mutex, so its visibility witness must use the under-lifecycle snapshot seam. This
    /// drives the exact headless preflight called by the Tauri command and fails deterministically
    /// if that path ever tries to acquire the same mutex twice.
    #[test]
    fn living_answer_refresh_preflight_does_not_relock_the_lifecycle_mutex() {
        let state = Arc::new(build_state("living-answer-preflight-no-relock"));
        state
            .db
            .insert_dashboard(
                "board-preflight",
                "Board",
                None,
                None,
                "2026-08-13T10:00:00Z",
            )
            .unwrap();
        state
            .db
            .insert_dashboard_living_answer_tile(
                "tile-preflight",
                "board-preflight",
                4,
                "What changed?",
                "[]",
                "2026-08-13T10:00:01Z",
            )
            .unwrap();

        let (tx, rx) = std::sync::mpsc::sync_channel(1);
        std::thread::spawn(move || {
            let result = crate::commands::dashboards::refresh_dashboard_answer_preflight(
                &state,
                "board-preflight",
                "tile-preflight",
                "What changed?",
            );
            tx.send(result.map(|(_, context, _, _, _)| context.packed_corpus))
                .unwrap();
        });

        let corpus = rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .expect("Living Answer preflight deadlocked on the lifecycle mutex")
            .unwrap();
        assert!(
            corpus.is_empty(),
            "the board contains only the excluded cache"
        );
    }

    #[test]
    fn save_config_waits_for_the_content_lifecycle_before_changing_ask_dispatch() {
        let state = Arc::new(build_state("save-config-lifecycle"));
        let mut dto = {
            let config = state.config.lock().unwrap();
            config_to_dto(&config)
        };
        dto.role_ask_connection = crate::summarize::roles::CONN_LOCAL.to_string();

        let lifecycle = lifecycle_guard(&state);
        let writer_state = state.clone();
        let (started_tx, started_rx) = std::sync::mpsc::sync_channel(1);
        let (tx, rx) = std::sync::mpsc::sync_channel(1);
        std::thread::spawn(move || {
            started_tx.send(()).unwrap();
            tx.send(save_config_inner(&writer_state, dto)).unwrap();
        });
        started_rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .expect("config writer did not reach save_config_inner");
        assert!(matches!(
            rx.recv_timeout(std::time::Duration::from_millis(100)),
            Err(std::sync::mpsc::RecvTimeoutError::Timeout)
        ));
        assert_ne!(
            state.config.lock().unwrap().role_ask_connection,
            crate::summarize::roles::CONN_LOCAL,
            "config must remain the old complete snapshot while lifecycle is held"
        );
        drop(lifecycle);
        rx.recv_timeout(std::time::Duration::from_secs(2))
            .expect("config writer stayed blocked after lifecycle release")
            .unwrap();
        assert_eq!(
            state.config.lock().unwrap().role_ask_connection,
            crate::summarize::roles::CONN_LOCAL
        );
    }

    #[test]
    fn ask_dispatch_generation_defeats_provider_aba_and_noop_saves() {
        let state = build_state("ask-dispatch-aba");
        let start = state.db.ask_dispatch_generation().unwrap();
        let original = {
            let config = state.config.lock().unwrap();
            config_to_dto(&config)
        };
        save_config_inner(&state, original.clone()).unwrap();
        assert_eq!(state.db.ask_dispatch_generation().unwrap(), start);

        let mut changed = original.clone();
        changed.role_ask_connection = crate::summarize::PROVIDER_GATEWAY.to_string();
        changed.role_ask_model = "same-budget-model".to_string();
        save_config_inner(&state, changed).unwrap();
        assert_eq!(state.db.ask_dispatch_generation().unwrap(), start + 1);

        save_config_inner(&state, original.clone()).unwrap();
        assert_eq!(
            state.db.ask_dispatch_generation().unwrap(),
            start + 2,
            "returning to byte-identical config must not revive generation N"
        );

        let mut memory_disabled = original;
        memory_disabled.user_memory_enabled = false;
        save_config_inner(&state, memory_disabled).unwrap();
        assert_eq!(
            state.db.ask_dispatch_generation().unwrap(),
            start + 3,
            "turning user memory off must revoke prompts captured while it was enabled"
        );
    }

    #[test]
    fn malformed_ask_dispatch_generation_fails_closed_and_cannot_be_coerced() {
        let state = build_state("ask-dispatch-malformed");
        {
            let conn = state.db.lock();
            conn.execute_batch(
                "PRAGMA ignore_check_constraints=ON;
                     UPDATE ask_dispatch_state SET generation='malformed' WHERE singleton=1;
                     PRAGMA ignore_check_constraints=OFF;",
            )
            .unwrap();
        }
        assert!(state.db.ask_dispatch_generation().is_err());
        assert!(state.db.advance_ask_dispatch_generation().is_err());
        let raw: (String, String) = state
            .db
            .lock()
            .query_row(
                "SELECT typeof(generation),CAST(generation AS TEXT)
                       FROM ask_dispatch_state WHERE singleton=1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(raw, ("text".into(), "malformed".into()));
    }

    #[test]
    fn history_commit_and_ipc_response_share_one_lifecycle_interval() {
        let state = Arc::new(build_state("ask-history-atomic-response"));
        let snapshot = DurableScopeSnapshot::Vault(capture_content_visibility_snapshot(&state));
        let ask_dispatch = {
            let _lifecycle = lifecycle_guard(&state);
            let config = state.config.lock().unwrap().clone();
            capture_ask_dispatch_snapshot_under_lifecycle(&state, &config).unwrap()
        };
        let (committed_tx, committed_rx) = std::sync::mpsc::sync_channel(1);
        let (release_tx, release_rx) = std::sync::mpsc::sync_channel(1);
        let worker_state = state.clone();
        let worker_snapshot = snapshot.clone();
        let worker_dispatch = ask_dispatch.clone();
        let (done_tx, done_rx) = std::sync::mpsc::sync_channel(1);
        std::thread::spawn(move || {
            let result = finish_persisted_ask_send_after_await_with_hook(
                &worker_state,
                &worker_snapshot,
                &worker_dispatch,
                &crate::storage::models::AskConversationScope::Vault,
                "question",
                "answer".into(),
                || {
                    committed_tx.send(()).unwrap();
                    release_rx.recv().unwrap();
                },
            );
            done_tx.send(result.map(|_| ())).unwrap();
        });
        committed_rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .expect("finalizer did not commit");

        let writer_state = state.clone();
        let (writer_started_tx, writer_started_rx) = std::sync::mpsc::sync_channel(1);
        let (writer_tx, writer_rx) = std::sync::mpsc::sync_channel(1);
        std::thread::spawn(move || {
            writer_started_tx.send(()).unwrap();
            let mut dto = {
                let config = writer_state.config.lock().unwrap();
                config_to_dto(&config)
            };
            dto.role_ask_connection = crate::summarize::roles::CONN_LOCAL.to_string();
            writer_tx
                .send(save_config_inner(&writer_state, dto))
                .unwrap();
        });
        writer_started_rx.recv().unwrap();
        assert!(matches!(
            writer_rx.recv_timeout(std::time::Duration::from_millis(100)),
            Err(std::sync::mpsc::RecvTimeoutError::Timeout)
        ));
        release_tx.send(()).unwrap();
        done_rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .unwrap()
            .unwrap();
        writer_rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .unwrap()
            .unwrap();
        assert_eq!(
            state
                .db
                .lock()
                .query_row(
                    "SELECT COUNT(*) FROM ask_conversation_messages",
                    [],
                    |row| { row.get::<_, i64>(0) }
                )
                .unwrap(),
            2
        );
    }

    /// A dashboard witness authorizes one exact provider/config projection. Changing the Ask role
    /// after preflight must stop every continuation before plaintext is hydrated/dispatched,
    /// persisted, cached, or serialized back across IPC.
    #[test]
    fn ask_dispatch_mutation_invalidates_history_dispatch_cache_and_response() {
        let state = Arc::new(build_state("ask-budget-mutation"));
        state
            .db
            .insert_dashboard("board-budget", "Budget", None, None, "2026-08-13T10:00:00Z")
            .unwrap();
        state
            .db
            .insert_dashboard_living_answer_tile(
                "tile-budget",
                "board-budget",
                4,
                "What changed?",
                "[]",
                "2026-08-13T10:00:01Z",
            )
            .unwrap();
        let old_budget = {
            let config = state.config.lock().unwrap();
            let connection =
                crate::summarize::roles::provider_target(crate::summarize::roles::Role::Ask, &config)
                    .connection;
            crate::summarize::vault_context::budget_for(&connection)
        };
        let context = crate::commands::dashboards::dashboard_composite_context(
            &state.db,
            "board-budget",
            &HashSet::new(),
            old_budget,
            &[],
            None,
        )
        .unwrap();
        let meeting_context = crate::commands::dashboards::dashboard_composite_context(
            &state.db,
            "board-budget",
            &HashSet::new(),
            old_budget.min(crate::summarize::chat::MAX_PINNED_SOURCE_CHARS),
            &[],
            Some("meeting-anchor"),
        )
        .unwrap();
        let living_context = crate::commands::dashboards::living_answer_composite_context(
            &state.db,
            "board-budget",
            &HashSet::new(),
            old_budget,
        )
        .unwrap();
        let snapshot = DurableScopeSnapshot::Vault(capture_content_visibility_snapshot(&state));
        let committed = persist_ask_exchange_after_await(
            &state,
            &snapshot,
            &crate::storage::models::AskConversationScope::Vault,
            None,
            None,
            "first question",
            "first answer",
            &[],
            &[],
            &[],
            &[],
            Some(&context.witness),
        )
        .unwrap();

        switch_ask_to_local_under_lifecycle(&state);
        let new_budget = {
            let config = state.config.lock().unwrap();
            let connection =
                crate::summarize::roles::provider_target(crate::summarize::roles::Role::Ask, &config)
                    .connection;
            crate::summarize::vault_context::budget_for(&connection)
        };
        assert_ne!(old_budget, new_budget, "the fixture must change Ask budget");

        let preflight = state
            .db
            .ask_conversation_preflight(
                &crate::storage::models::AskConversationScope::Vault,
                &committed.conversation_id,
                &HashSet::new(),
            )
            .unwrap();
        assert!(
            preflight.is_none(),
            "old dispatch generation must be rejected before history hydration"
        );
        state
            .db
            .lock()
            .execute_batch(&format!(
                "UPDATE ask_conversations SET title=x'80' WHERE id='{id}';
                     UPDATE ask_conversation_messages SET content=x'80' WHERE conversation_id='{id}';",
                id = committed.conversation_id
            ))
            .unwrap();
        list_ask_conversations_inner(&state, &crate::storage::models::AskConversationScope::Vault)
            .expect("stale-budget list must reject metadata before hydrating the poisoned title");
        assert!(matches!(
            load_ask_conversation_inner(
                &state,
                &crate::storage::models::AskConversationScope::Vault,
                &committed.conversation_id,
            ),
            Err(AppError::Locked(_))
        ));

        let provider = Arc::new(BudgetMutationProvider {
            calls: std::sync::atomic::AtomicUsize::new(0),
        });
        let gate_state = state.clone();
        let stale_witness = context.witness.clone();
        let admission =
            crate::state::ContentDispatchAdmission::for_test(Arc::new(Mutex::new(())), move || {
                let _lifecycle = lifecycle_guard(&gate_state);
                crate::commands::dashboards::require_current_dashboard_context_witness_under_lifecycle(
                    &gate_state,
                    &stale_witness,
                    &HashSet::new(),
                )
            });
        let dispatch_error = block_on(ask_vault_prepacked_dashboard_dispatch(
            &context,
            "second question",
            &[],
            admission,
            {
                let provider = provider.clone();
                move || Ok(provider as Arc<dyn crate::summarize::provider::SummarizerProvider>)
            },
        ))
        .unwrap_err();
        assert!(matches!(dispatch_error, AppError::Locked(_)));
        assert_eq!(provider.calls.load(Ordering::SeqCst), 0);

        assert!(matches!(
            persist_ask_exchange_after_await(
                &state,
                &snapshot,
                &crate::storage::models::AskConversationScope::Vault,
                Some(&committed.conversation_id),
                None,
                "second question",
                "stale answer",
                &[],
                &[],
                &[],
                &[],
                Some(&context.witness),
            ),
            Err(AppError::Locked(_))
        ));
        let message_count: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM ask_conversation_messages WHERE conversation_id=?1",
                [&committed.conversation_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(message_count, 2, "stale exchange must add no history turns");

        let payload = crate::storage::models::AskConversationSendResult {
            conversation_id: committed.conversation_id.clone(),
            user_message_id: committed.user_message_id.clone(),
            assistant_message_id: committed.assistant_message_id.clone(),
            answer: "stale answer".into(),
            sources: Vec::new(),
            citations: Vec::new(),
        };
        assert!(matches!(
            serialize_durable_send_response(&state, &snapshot, Some(&context.witness), &payload,),
            Err(AppError::Locked(_))
        ));
        {
            let _lifecycle = lifecycle_guard(&state);
            assert!(matches!(
                crate::commands::dashboards::require_current_dashboard_context_witness_under_lifecycle(
                    &state,
                    &meeting_context.witness,
                    &HashSet::new(),
                ),
                Err(AppError::Locked(_))
            ));
        }

        assert!(matches!(
            crate::commands::dashboards::persist_dashboard_living_answer_after_await(
                &state,
                &snapshot,
                &living_context.witness,
                &[],
                "board-budget",
                "tile-budget",
                "What changed?",
                "stale answer",
                "2026-08-13T10:01:00Z",
            ),
            Err(AppError::Locked(_))
        ));
        let answer_type: String = state
            .db
            .lock()
            .query_row(
                "SELECT typeof(living_answer) FROM dashboard_tiles WHERE id='tile-budget'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            answer_type, "null",
            "stale answer must add no cache content"
        );
    }

    #[test]
    fn ask_writer_withholds_old_living_answer_without_hydrating_or_clearing_it() {
        let state = build_state("ask-budget-existing-cache");
        state
            .db
            .insert_dashboard("board-cache", "Cache", None, None, "2026-08-13T10:00:00Z")
            .unwrap();
        state
            .db
            .insert_dashboard_living_answer_tile(
                "tile-cache",
                "board-cache",
                4,
                "What changed?",
                "[]",
                "2026-08-13T10:00:01Z",
            )
            .unwrap();
        let old_budget = {
            let config = state.config.lock().unwrap();
            resolved_ask_corpus_budget(&config)
        };
        let old_context = crate::commands::dashboards::living_answer_composite_context(
            &state.db,
            "board-cache",
            &HashSet::new(),
            old_budget,
        )
        .unwrap();
        assert!(state
            .db
            .store_dashboard_living_answer_cas(
                "tile-cache",
                "board-cache",
                "What changed?",
                "Old-budget answer",
                "2026-08-13T10:01:00Z",
                "[]",
                old_context.witness.generation,
                &old_context.witness.input_digest,
                old_budget,
            )
            .unwrap());
        let tile = state.db.get_dashboard_tile("tile-cache").unwrap().unwrap();
        assert!(matches!(
            crate::commands::dashboards::resolve_tile(&state.db, &tile, &HashSet::new()).unwrap(),
            crate::commands::dashboards::TileData::LivingAnswer {
                answer: Some(ref answer),
                withheld: false,
                ..
            } if answer == "Old-budget answer"
        ));
        let general_before = state.db.dashboard_context_state("board-cache").unwrap().0;
        let structural_before = state
            .db
            .dashboard_structural_context_state("board-cache")
            .unwrap()
            .0;

        switch_ask_to_local_under_lifecycle(&state);

        assert_eq!(
            state.db.dashboard_context_state("board-cache").unwrap().0,
            general_before
        );
        assert_eq!(
            state
                .db
                .dashboard_structural_context_state("board-cache")
                .unwrap()
                .0,
            structural_before,
            "a provider-budget change does not change board structure"
        );
        assert!(matches!(
            state
                .db
                .dashboard_living_answer_preflight("tile-cache")
                .unwrap()
                .unwrap()
                .answer,
            crate::storage::dashboards_store::LivingAnswerCacheState::Valid { .. }
        ));
        assert!(matches!(
            crate::commands::dashboards::resolve_tile(&state.db, &tile, &HashSet::new()).unwrap(),
            crate::commands::dashboards::TileData::LivingAnswer {
                ref question,
                answer: None,
                answered_at: None,
                withheld: false,
            } if question == "What changed?"
        ));

        let new_budget = {
            let config = state.config.lock().unwrap();
            resolved_ask_corpus_budget(&config)
        };
        let new_context = crate::commands::dashboards::living_answer_composite_context(
            &state.db,
            "board-cache",
            &HashSet::new(),
            new_budget,
        )
        .unwrap();
        assert!(state
            .db
            .store_dashboard_living_answer_cas(
                "tile-cache",
                "board-cache",
                "What changed?",
                "Fresh local answer",
                "2026-08-13T10:02:00Z",
                "[]",
                new_context.witness.generation,
                &new_context.witness.input_digest,
                new_budget,
            )
            .unwrap());
        let general_after_refresh = state.db.dashboard_context_state("board-cache").unwrap().0;
        let structural_after_refresh = state
            .db
            .dashboard_structural_context_state("board-cache")
            .unwrap()
            .0;
        let mut same_budget_dto = {
            let config = state.config.lock().unwrap();
            config_to_dto(&config)
        };
        same_budget_dto.note_language = "pl".to_string();
        save_config_inner(&state, same_budget_dto).unwrap();
        assert_eq!(
            state.db.dashboard_context_state("board-cache").unwrap().0,
            general_after_refresh,
            "an unrelated same-budget save must not invalidate the answer"
        );
        assert_eq!(
            state
                .db
                .dashboard_structural_context_state("board-cache")
                .unwrap()
                .0,
            structural_after_refresh
        );
        assert!(matches!(
            crate::commands::dashboards::resolve_tile(&state.db, &tile, &HashSet::new()).unwrap(),
            crate::commands::dashboards::TileData::LivingAnswer {
                answer: Some(ref answer),
                withheld: false,
                ..
            } if answer == "Fresh local answer"
        ));
    }

    /// RED-before-GREEN Ask-history oracle: a relock/delete generation change after inference must
    /// prevent BOTH the IPC result and the atomic user+assistant write. No orphan thread survives.
    #[test]
    fn ask_history_post_await_epoch_change_writes_zero_rows() {
        let state = build_state("ask-history-post-await");
        let snapshot = DurableScopeSnapshot::Vault(capture_content_visibility_snapshot(&state));
        bump_seal_epoch(&state);

        let error = persist_ask_exchange_after_await(
            &state,
            &snapshot,
            &crate::storage::models::AskConversationScope::Vault,
            None,
            None,
            "question",
            "stale answer",
            &[],
            &[],
            &[],
            &[],
            None,
        )
        .unwrap_err();
        assert!(matches!(error, AppError::Locked(_)));
        let count: i64 = state
            .db
            .lock()
            .query_row("SELECT COUNT(*) FROM ask_conversations", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(count, 0, "stale post-await result must persist no rows");
    }

