        let count: i64 = state
            .db
            .lock()
            .query_row("SELECT COUNT(*) FROM ask_conversations", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(count, 0, "a stale tail mutation must persist no history");
