    /// A visibility increase does not advance `seal_epoch`. If a folder becomes session-visible
    /// while the provider is running, the post-await persistence seam must include it in the
    /// durable dependency union; otherwise a later relock could leave the derived answer readable.
    #[test]
    fn ask_history_post_await_unions_newly_visible_folder_dependency() {
        let state = build_state("ask-history-post-await-widen");
        make_open_folder(&state.db, "f-visible", "Visible");
        make_open_folder(&state.db, "f-late", "Late");
        lock_folder_inner(&state, "f-late".into()).unwrap();

        let snapshot = DurableScopeSnapshot::Vault(capture_content_visibility_snapshot(&state));
        let initial_dependencies = state.db.visible_folder_ids(&HashSet::new()).unwrap();
        // Every database now carries a default project (the hierarchy migration), which is a real
        // always-open container and so is legitimately part of the visible set. Subtract exactly
        // THAT id rather than filtering by a name prefix, so both assertions stay CLOSED sets: any
        // other id leaking into the visible set — another generated container, an org- or
        // system-sourced one — must still fail here, at a gate assertion. Naming the id also avoids
        // depending on where a UUID happens to sort relative to "f-visible".
        let project_id: String = state
            .db
            .lock()
            .query_row(
                "SELECT id FROM folders WHERE COALESCE(level, 'folder') = 'project'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let seeded = |ids: &[String]| -> Vec<String> {
            let mut v: Vec<String> = ids
                .iter()
                .filter(|id| **id != project_id)
                .cloned()
                .collect();
            v.sort();
            v
        };
        assert_eq!(seeded(&initial_dependencies), vec!["f-visible".to_string()]);

        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-late".into());
        let committed = persist_ask_exchange_after_await(
            &state,
            &snapshot,
            &crate::storage::models::AskConversationScope::Vault,
            None,
            None,
            "question",
            "answer using the newly visible folder",
            &[],
            &[],
            &[],
            &initial_dependencies,
            None,
        )
        .unwrap();

        let dependencies = {
            let conn = state.db.lock();
            let mut stmt = conn
                .prepare(
                    "SELECT dependency_ref FROM ask_conversation_dependencies
                                      WHERE conversation_id = ?1 ORDER BY dependency_ref",
                )
                .unwrap();
            stmt.query_map([committed.conversation_id], |row| row.get::<_, String>(0))
                .unwrap()
                .collect::<std::result::Result<Vec<_>, _>>()
                .unwrap()
        };
        assert_eq!(
            seeded(&dependencies),
            vec!["f-late".to_string(), "f-visible".to_string()]
        );
    }

