    /// INLINE REPUBLISH: there is one atomic `/items` request and no anonymous `/blobs` staging
    /// request. Source moves are serialized by the public mutation command and covered by their
    /// barrier oracles; this test pins the single-request transport contract itself.
    #[test]
    fn republish_inline_publish_uses_one_atomic_request() {
        let server = tiny_http::Server::http("127.0.0.1:0").unwrap();
        let addr = server.server_addr().to_ip().unwrap();
        let state = build_state("org-republish-move-during-upload");
        seed_org(&state.db, STABLE_ORG_ID, "Acme", "member", 1);
        make_open_folder(&state.db, "f-before", "Before");
        make_open_folder(&state.db, "f-after", "After");
        state
            .db
            .insert_note("n-race", "f-before", "race", "Race", "# fresh body", 1)
            .unwrap();
        state
            .db
            .insert_org_share(
                "s-race",
                STABLE_ORG_ID,
                None,
                Some("n-race"),
                "note",
                Some("Race"),
                1,
                1,
                &[1u8; 32], // deliberately differs from the fresh envelope hash
                "2026-07-11T09:00:00Z",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("s-race", "item-old", "2026-07-11T09:00:00Z")
            .unwrap();
        state.config.lock().unwrap().org_egress_consented = true;
        state.config.lock().unwrap().share_base_url = format!("http://{addr}/");
        seed_live_session(&state);
        seed_ock(&state, STABLE_ORG_ID, 1);

        let mock = std::thread::spawn(move || {
            let req = server
                .recv_timeout(std::time::Duration::from_secs(2))
                .unwrap()
                .expect("republish must issue one inline publish");
            assert_eq!(req.method(), &tiny_http::Method::Post);
            assert_eq!(
                req.url().split('?').next(),
                Some(concat!(
                    "/v1/orgs/",
                    "11111111-1111-4111-8111-111111111111",
                    "/items"
                ))
            );

            let mut req = req;
            let mut body = String::new();
            req.as_reader().read_to_string(&mut body).unwrap();
            let json: serde_json::Value = serde_json::from_str(&body).unwrap();
            assert!(json.get("blobId").is_none());
            assert!(json.get("contentCell").and_then(|v| v.as_str()).is_some());
            let doc_id = json["docId"].as_str().unwrap();

            let response = tiny_http::Response::from_string(format!(
                    r#"{{"itemId":"item-new","seq":2,"docId":"{doc_id}","access":"view","documentOwnerUserId":"c534b6d2-02c1-4c2c-a256-3af8592b1567"}}"#
                ))
                .with_header(
                        "Content-Type: application/json"
                            .parse::<tiny_http::Header>()
                            .unwrap(),
                    );
            req.respond(response).unwrap();

            // A successful supersede has exactly one follow-up: tombstone the old item. There is no
            // staging request and no second publish.
            let tombstone = server
                .recv_timeout(std::time::Duration::from_millis(400))
                .unwrap()
                .expect("successful republish tombstones the old item");
            let tombstone_path = tombstone.url().to_string();
            assert_eq!(tombstone.method(), &tiny_http::Method::Delete);
            let _ = tombstone.respond(tiny_http::Response::empty(200));
            let extra = server
                .recv_timeout(std::time::Duration::from_millis(200))
                .unwrap()
                .map(|req| req.url().to_string());
            (tombstone_path, extra)
        });

        let republished = block_on(republish_org_shares_for_source(
            &state,
            None,
            Some("n-race"),
        ))
        .unwrap();
        assert_eq!(republished, 1, "one authorized snapshot was published");
        let (tombstone_path, extra) = mock.join().unwrap();
        assert_eq!(
            tombstone_path,
            format!("/v1/orgs/{STABLE_ORG_ID}/items/item-old")
        );
        assert_eq!(extra, None, "no staging or duplicate publish request");

        let row = state.db.get_org_share("s-race").unwrap().unwrap();
        assert_eq!(row.rev, 2, "the inline publish advanced one revision");
        assert_eq!(row.item_id.as_deref(), Some("item-new"));
        assert_eq!(row.state, "uploaded");
    }

    /// COLLAPSE — auto-clean of duplicates that already exist. `share_to_org_inner` on a source with
    /// MULTIPLE live copies in one org returns the EARLIEST (the keeper) and marks the extras for teardown
    /// (`revoke_pending`). The tombstone network call fails in a unit test (no session) but is
    /// best-effort: `revoke_org_share_inner` marks the row `revoke_pending` FIRST (the launch sweep
    /// finishes it), and the swallowed error never breaks the idempotent return.
    #[test]
    fn share_to_org_inner_collapses_existing_duplicates_keeping_the_earliest() {
        let state = build_state("org-share-collapse");
        seed_org(&state.db, STABLE_ORG_ID, "Acme", "member", 1);
        state.config.lock().unwrap().org_egress_consented = true;
        make_open_folder(&state.db, "f-collapse", "Team");
        state
            .db
            .insert_note("n1", "f-collapse", "note", "A Note", "# body", 1)
            .unwrap();
        // Two accidental duplicates of (org-1, n1): earliest = keeper, later = the extra to tombstone.
        state
            .db
            .insert_org_share(
                "keep",
                STABLE_ORG_ID,
                None,
                Some("n1"),
                "note",
                Some("A Note"),
                1,
                1,
                &[1u8; 32],
                "2026-07-11T09:00:00Z",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("keep", "item-keep", "2026-07-11T09:00:00Z")
            .unwrap();
        state
            .db
            .insert_org_share(
                "dup",
                STABLE_ORG_ID,
                None,
                Some("n1"),
                "note",
                Some("A Note"),
                1,
                1,
                &[2u8; 32],
                "2026-07-11T09:05:00Z",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("dup", "item-dup", "2026-07-11T09:05:00Z")
            .unwrap();
        // A NOT-yet-uploaded sibling (a stuck pending retry) for the same source — redundant, cancelled.
        state
            .db
            .insert_org_share(
                "pending",
                STABLE_ORG_ID,
                None,
                Some("n1"),
                "note",
                Some("A Note"),
                1,
                1,
                &[3u8; 32],
                "2026-07-11T09:06:00Z",
            )
            .unwrap();

        let entry = block_on(share_to_org_inner(
            &state,
            STABLE_ORG_ID,
            None,
            Some("n1".to_string()),
            false,
        ))
        .unwrap();
        assert_eq!(
            entry.item_id.as_deref(),
            Some("item-keep"),
            "the EARLIEST live copy is the keeper"
        );
        // Keeper stays uploaded; the duplicate is queued for tombstone. No new row was minted.
        assert_eq!(
            state.db.get_org_share("keep").unwrap().unwrap().state,
            "uploaded",
            "keeper untouched"
        );
        assert_eq!(
            state.db.get_org_share("dup").unwrap().unwrap().state,
            "revoke_pending",
            "the duplicate is marked for tombstone (launch sweep finishes it)"
        );
        assert_eq!(
            state.db.get_org_share("pending").unwrap().unwrap().state,
            "queued",
            "a queued NULL-item sibling is not proof of remote absence and stays fail-closed"
        );
    }

    /// MULTI-ORG STATUS (RED→GREEN for the single-org `.next()` bug): `org_list_statuses` must return
    /// an `OrgStatus` for EVERY locally-joined org — the one I created AND the one I was invited to —
    /// not just the first. With no server configured (empty base URL) it stays offline: each status
    /// falls back to the cached row. This FAILS on any `.next()`/first-only status path (it would
    /// return 1). `org_status` (legacy) still returns exactly the FIRST for old callers.
    #[test]
    fn org_list_statuses_returns_all_local_orgs() {
        let state = build_state("org-list-statuses");
        // Two orgs: one owned (created), one member (invited). No server → offline per-org fallback.
        seed_org(&state.db, "org-own", "Acme", "owner", 1);
        seed_org(&state.db, "org-inv", "Partner Co", "member", 2);

        let statuses = block_on(org_list_statuses_inner(&state)).unwrap();
        assert_eq!(
            statuses.len(),
            2,
            "every locally-joined org yields a status (RED on a single-org .next())"
        );
        let ids: std::collections::HashSet<&str> = statuses.iter().map(|s| s.org_id.as_str()).collect();
        assert!(ids.contains("org-own"), "the owned org appears");
        assert!(ids.contains("org-inv"), "the invited org appears");

        // Legacy single-org `org_status` still returns the FIRST (ordered by joined_at) — unchanged
        // for pre-multi-org FE callers.
        let first = block_on(org_status_inner(&state)).unwrap();
        assert!(first.is_some(), "legacy org_status still returns the first");
    }

    #[test]
    fn org_list_statuses_keeps_other_rows_when_one_refresh_is_unavailable() {
        use std::io::{Read, Write};

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut socket, _) = listener.accept().unwrap();
            let mut request = [0u8; 4096];
            let _ = socket.read(&mut request).unwrap();
            // An authenticated but mismatched per-org response is unavailable/fail-closed for the
            // refresh. The aggregate must still return the cached content-free status.
            let body = r#"{"orgId":"wrong-org","name":"Wrong","role":"member","createdAt":"2026-08-13T00:00:00Z","currentGeneration":1}"#;
            write!(
                    socket,
                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                    body.len(),
                    body
                )
                .unwrap();
        });

        let state = build_state("org-list-statuses-partial-unavailable");
        seed_org(&state.db, "org-live", "Cached", "member", 1);
        seed_live_session(&state);
        state.config.lock().unwrap().share_base_url = format!("http://{addr}/");

        let statuses = block_on(org_list_statuses_inner(&state)).unwrap();
        server.join().unwrap();
        assert_eq!(statuses.len(), 1);
        assert_eq!(statuses[0].org_id, "org-live");
        assert_eq!(statuses[0].name, "Cached");
    }

