    /// MEMBERSHIP RECONCILE (DB core, network-free): `reconcile_org_state_into_db` must ADD an org the
    /// server now lists (an invite I didn't have locally) and REMOVE an org the server no longer lists
    /// (I left / was removed). Preserves an existing org's local cursor/consent across the refresh.
    #[test]
    fn reconcile_adds_invited_org_and_removes_departed() {
        let state = build_state("org-reconcile");
        // Local pre-state: I'm in "org-keep" (with a cursor + consent) and "org-gone" (departed).
        seed_org(&state.db, "org-keep", "Keep", "member", 1);
        seed_org(&state.db, "org-gone", "Gone", "member", 1);
        state.db.set_org_consented("org-keep", true).unwrap();
        state.db.set_org_last_seq("org-keep", 55).unwrap();

        // Server says: I'm in "org-keep" (name refreshed) + a NEW "org-new" (an invite). "org-gone" is
        // absent (I left / was removed).
        let server = vec![
            crate::share::org_dto::OrgSummary {
                org_id: "org-keep".into(),
                name: "Keep Renamed".into(),
                role: "member".into(),
                created_at: "2026-07-01T00:00:00Z".into(),
                current_generation: 3,
            },
            crate::share::org_dto::OrgSummary {
                org_id: "org-new".into(),
                name: "Newly Invited".into(),
                role: "member".into(),
                created_at: "2026-07-11T09:00:00Z".into(),
                current_generation: 1,
            },
        ];

        let outcome = reconcile_org_state_into_db(&state, &server).unwrap();
        // "org-new" is the only NEW org (needs an OCK fetch); "org-gone" is the only removal.
        assert_eq!(outcome.new_orgs, vec![("org-new".to_string(), 1u32)]);
        assert_eq!(outcome.removed, 1);

        let after: std::collections::HashSet<String> = state
            .db
            .list_org_states()
            .unwrap()
            .into_iter()
            .map(|o| o.org_id)
            .collect();
        assert!(after.contains("org-keep"), "kept org stays");
        assert!(after.contains("org-new"), "invited org added");
        assert!(!after.contains("org-gone"), "departed org removed");

        // The kept org's LOCAL cursor + consent survive the reconcile (upsert only refreshed
        // name/role/generation); its generation was refreshed to the server value.
        let keep = state.db.get_org_state("org-keep").unwrap().unwrap();
        assert_eq!(keep.name, "Keep Renamed", "name refreshed from server");
        assert_eq!(keep.generation, 3, "generation refreshed from server");
        assert_eq!(keep.last_seq, 55, "local cursor NOT rewound");
        assert!(keep.consented, "local consent NOT cleared");
        // The new org lands with the defaults.
        let new = state.db.get_org_state("org-new").unwrap().unwrap();
        assert_eq!(new.joined_at, "2026-07-11T09:00:00Z");
        assert!(!new.consented);
        assert_eq!(new.last_seq, 0);
    }

    #[test]
    fn single_authenticated_empty_org_list_cannot_purge_live_membership_or_private_links() {
        use std::io::{Read, Write};

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut socket, _) = listener.accept().unwrap();
            let mut request = [0u8; 4096];
            let _ = socket.read(&mut request).unwrap();
            let body = r#"{"orgs":[]}"#;
            write!(
                    socket,
                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                    body.len(),
                    body
                )
                .unwrap();
            listener.set_nonblocking(true).unwrap();
            let deadline = std::time::Instant::now() + std::time::Duration::from_millis(500);
            loop {
                match listener.accept() {
                    Ok((mut unexpected, _)) => {
                        let _ = unexpected.read(&mut request).unwrap();
                        return 2usize;
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        if std::time::Instant::now() >= deadline {
                            return 1usize;
                        }
                        std::thread::sleep(std::time::Duration::from_millis(10));
                    }
                    Err(error) => panic!("empty-membership mock accept failed: {error}"),
                }
            }
        });

        let state = build_state("org-empty-list-corroboration");
        let org_id = "11111111-1111-4111-8111-111111111111";
        let link_id = format!("{org_id}:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa");
        seed_org(&state.db, org_id, "Acme", "member", 1);
        make_open_folder(&state.db, "f-empty", "Empty reconcile");
        seed_meeting(
            &state.db,
            "private-local-anchor",
            "# local",
            Some("f-empty"),
        );
        seed_live_session(&state);
        state.config.lock().unwrap().share_base_url = format!("http://{addr}/");
        state.db.lock().execute(
                "INSERT INTO links (src_kind, src_id, dst_kind, dst_id, edge_type, score, created_by, status, created_at)
                 VALUES ('org',?1,'meeting','private-local-anchor','manual',1.0,'user','active',1)",
                [link_id.as_str()],
            ).unwrap();

        block_on(org_reconcile_memberships_notifying(&state, None)).unwrap();
        assert_eq!(
            server.join().unwrap(),
            1,
            "without org-egress consent there is no per-org status request"
        );
        assert!(state.db.get_org_state(org_id).unwrap().is_some());
        let private_links: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM links WHERE src_kind='org' AND src_id=?1",
                [link_id.as_str()],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(private_links, 1);
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_membership_corroborate")
                .unwrap(),
            0
        );
    }

    #[test]
    fn consented_membership_corroboration_ledgers_success_and_preserves_on_error() {
        use std::io::{Read, Write};

        fn run(tag: &str, exact_status: &str) -> AppState {
            let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
            let addr = listener.local_addr().unwrap();
            let exact_status = exact_status.to_string();
            let server = std::thread::spawn(move || {
                for response in [
                        "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: 11\r\nconnection: close\r\n\r\n{\"orgs\":[]}".to_string(),
                        format!(
                            "HTTP/1.1 {exact_status}\r\ncontent-length: 0\r\nconnection: close\r\n\r\n"
                        ),
                    ] {
                        let (mut socket, _) = listener.accept().unwrap();
                        let mut request = [0u8; 4096];
                        let _ = socket.read(&mut request).unwrap();
                        socket.write_all(response.as_bytes()).unwrap();
                    }
            });
            let state = build_state(tag);
            seed_org(
                &state.db,
                "11111111-1111-4111-8111-111111111111",
                "Acme",
                "member",
                1,
            );
            state
                    .db
                    .lock()
                    .execute(
                        "INSERT INTO links (src_kind, src_id, dst_kind, dst_id, edge_type, score, created_by, status, created_at)
                         VALUES ('org','11111111-1111-4111-8111-111111111111:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','note','local-note','manual',1.0,'user','active',1)",
                        [],
                    )
                    .unwrap();
            seed_live_session(&state);
            state.config.lock().unwrap().share_base_url = format!("http://{addr}/");
            state.config.lock().unwrap().org_egress_consented = true;
            block_on(org_reconcile_memberships_notifying(&state, None)).unwrap();
            server.join().unwrap();
            state
        }

        let absent = run("org-corroborate-404", "404 Not Found");
        assert!(absent
            .db
            .get_org_state("11111111-1111-4111-8111-111111111111")
            .unwrap()
            .is_none());
        assert_eq!(
            absent
                .db
                .count_share_egress_by_kind("org_membership_corroborate")
                .unwrap(),
            1,
            "an exact successful absence check is recorded content-free"
        );

        let failed = run("org-corroborate-error", "500 Internal Server Error");
        assert!(
            failed
                .db
                .get_org_state("11111111-1111-4111-8111-111111111111")
                .unwrap()
                .is_some(),
            "a failed corroboration preserves cached membership"
        );
        let private_links: i64 = failed
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM links WHERE src_kind='org' AND edge_type='manual'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            private_links, 1,
            "a failed corroboration preserves private links"
        );
        assert_eq!(
            failed
                .db
                .count_share_egress_by_kind("org_membership_corroborate")
                .unwrap(),
            1,
            "the exact pre-dispatch attempt is ledgered even when the server returns an error"
        );
    }

    #[test]
    fn uncorroborated_empty_reconcile_core_is_non_destructive() {
        let state = build_state("org-empty-core-fail-safe");
        seed_org(&state.db, "org-1", "Acme", "member", 1);
        make_open_folder(&state.db, "f-empty-core", "Empty core");
        seed_meeting(
            &state.db,
            "private-local-anchor",
            "# local",
            Some("f-empty-core"),
        );
        state.db.lock().execute(
                "INSERT INTO links (src_kind, src_id, dst_kind, dst_id, edge_type, score, created_by, status, created_at)
                 VALUES ('org','org-1:doc-1','meeting','private-local-anchor','manual',1.0,'user','active',1)",
                [],
            ).unwrap();

        let outcome = reconcile_org_state_into_db(&state, &[]).unwrap();
        assert_eq!(outcome.removed, 0);
        assert!(state.db.get_org_state("org-1").unwrap().is_some());
        let count: i64 = state
            .db
            .lock()
            .query_row("SELECT COUNT(*) FROM links", [], |row| row.get(0))
            .unwrap();
        assert_eq!(count, 1);
    }

    /// MULTI-ORG SYNC services ALL orgs across bounded round-robin turns. Each invocation owns one
    /// global feed-page budget, so with TWO orgs two consecutive calls must attempt one org each.
    /// Point the client at an UNREACHABLE loopback URL (connection refused, no real egress): each
    /// turn records one error and neither durable cursor is rewound.
    #[test]
    fn org_sync_now_over_two_orgs_iterates_both() {
        let state = build_state("org-sync-multi");
        seed_org(&state.db, "org-a", "A", "member", 1);
        seed_org(&state.db, "org-b", "B", "member", 1);
        state.db.set_org_last_seq("org-a", 10).unwrap();
        state.db.set_org_last_seq("org-b", 20).unwrap();

        // A loopback URL with a closed port → connection refused (validate_gateway_url allows http on
        // loopback). NO real network egress; both org feeds fail the same way.
        state.config.lock().unwrap().share_base_url = "http://127.0.0.1:9/".to_string();
        // A live (non-expired) session so `valid_access_token` yields a bearer and the loop runs.
        *state.account_session.lock().unwrap() = Some(crate::share::AccountSession {
            account_id: "user@example.com".into(),
            email: "user@example.com".into(),
            server_user_id: Some("c534b6d2-02c1-4c2c-a256-3af8592b1567".into()),
            device_id: "dev-1".into(),
            mk: Zeroizing::new([7u8; 32]),
            generation: 1,
            access_token: "a".into(),
            access_expires_at: Some("2099-01-01T00:00:00Z".into()),
            refresh_token: "r".into(),
        });

        let first = block_on(org_sync_now_inner(&state)).unwrap();
        let second = block_on(org_sync_now_inner(&state)).unwrap();
        // One global page budget per call; consecutive round-robin turns cover both orgs regardless
        // of the process-global cursor's starting parity.
        assert_eq!(
            first.errors.len() + second.errors.len(),
            2,
            "two bounded turns must attempt both joined orgs"
        );
        assert_eq!(first.errors.len(), 1);
        assert_eq!(second.errors.len(), 1);
        assert_eq!(first.ingested + second.ingested, 0);
        assert_eq!(first.tombstoned + second.tombstoned, 0);
        // Neither cursor is rewound by a failed sync (monotonic).
        assert_eq!(
            state.db.get_org_state("org-a").unwrap().unwrap().last_seq,
            10
        );
        assert_eq!(
            state.db.get_org_state("org-b").unwrap().unwrap().last_seq,
            20
        );
    }

    /// The authenticated feed/import path is membership-gated before its first socket, then commits
    /// an opened envelope only while that same local org membership still exists. This is the
    /// command-level companion to the storage race oracle: a guessed org id gets zero network and
    /// zero plaintext; a joined org traverses the real feed + blob + open + storage chain.
    #[test]
    fn org_sync_import_requires_membership_before_feed_and_plaintext_commit() {
        use crate::share::org_envelope::{seal_org_envelope, OrgEnvelope, OrgItemKind, OrgSourceKind};
        use std::io::{Read, Write};

        let ock = [9_u8; 32];
        let env = OrgEnvelope::new(
            OrgItemKind::Note,
            "Member plan",
            "authenticated member-only body",
            "anna",
            "2026-07-11T09:00:00Z",
            1,
            OrgSourceKind::Document,
        );
        let sha = env.content_sha256();
        let nonce = org_item_nonce(&sha);
        let (ciphertext, _) = seal_org_envelope(&ock, &env, "org-member", &nonce).unwrap();

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let addr = listener.local_addr().unwrap();
        let requests = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let requests_for_server = std::sync::Arc::clone(&requests);
        let server = std::thread::spawn(move || {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            let mut served = 0usize;
            while served < 2 && std::time::Instant::now() < deadline {
                let (mut socket, _) = match listener.accept() {
                    Ok(pair) => pair,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(10));
                        continue;
                    }
                    Err(error) => panic!("member import mock accept failed: {error}"),
                };
                socket.set_nonblocking(false).unwrap();
                socket
                    .set_read_timeout(Some(std::time::Duration::from_secs(1)))
                    .unwrap();
                let mut request = [0_u8; 8192];
                let read = socket.read(&mut request).unwrap();
                let request = String::from_utf8_lossy(&request[..read]).into_owned();
                let first_line = request.lines().next().unwrap_or_default().to_string();
                requests_for_server.lock().unwrap().push(first_line.clone());
                assert!(
                    request
                        .to_ascii_lowercase()
                        .contains("authorization: bearer a"),
                    "both feed and blob reads must use the authenticated session"
                );

                if first_line.contains("/v1/orgs/org-member/items?") {
                    let body = format!(
                            "{{\"items\":[{{\"itemId\":\"member-item\",\"seq\":1,\"authorUserId\":\"author-1\",\"rev\":1,\"generation\":1,\"createdAt\":\"2026-07-11T09:00:00Z\",\"tombstoned\":false,\"blobId\":\"member-blob\",\"contentSha256\":\"{}\"}}],\"nextSeq\":1}}",
                            murmur_protocol::b64::encode(&sha)
                        );
                    write!(
                            socket,
                            "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                            body.len(),
                            body
                        )
                        .unwrap();
                } else if first_line.contains("/v1/blobs/member-blob") {
                    write!(
                            socket,
                            "HTTP/1.1 200 OK\r\ncontent-type: application/octet-stream\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                            ciphertext.len()
                        )
                        .unwrap();
                    socket.write_all(&ciphertext).unwrap();
                } else {
                    panic!("unexpected member import request: {first_line}");
                }
                socket.flush().unwrap();
                served += 1;
            }
            served
        });

        let state = build_state("org-sync-member-admission");
        state.config.lock().unwrap().share_base_url = format!("http://{addr}");
        seed_live_session(&state);

        assert!(matches!(
            block_on(org_sync_one_now_inner(&state, "org-outsider")),
            Err(AppError::InvalidArg(_))
        ));
        assert!(
            requests.lock().unwrap().is_empty(),
            "a non-member org id must be rejected before the first socket"
        );
        assert!(state.db.list_org_items("org-outsider").unwrap().is_empty());

        seed_org(&state.db, "org-member", "Member org", "member", 1);
        state
            .org_ock_cache
            .lock()
            .unwrap()
            .insert(("org-member".to_string(), 1), Zeroizing::new(ock));
        let report = block_on(org_sync_one_now_inner(&state, "org-member")).unwrap();
        assert_eq!(server.join().unwrap(), 2, "one feed plus one blob read");
        assert_eq!(report.pulled, 1);
        assert_eq!(report.ingested, 1);
        let stored = state
            .db
            .get_org_item("member-item")
            .unwrap()
            .expect("the authenticated member envelope must commit");
        assert_eq!(stored.markdown, "authenticated member-only body");
        assert_eq!(
            state
                .db
                .lock()
                .query_row(
                    "SELECT org_id FROM org_items WHERE item_id='member-item'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
            "org-member"
        );
        assert_eq!(state.db.org_last_seq_for("org-member").unwrap(), 1);
    }

    /// FIX D (per-item sync robustness, RED→GREEN): a TERMINAL-bad item at seq N must NOT stall the
    /// feed forever — the GOOD item at N+1 still ingests on the SAME sync. Pre-fix EVERY per-item
    /// failure did `break 'pages`, so one poison cell blocked all newer items indefinitely. We serve a
    /// synthetic one-page feed: item at seq 5 is a LIVE entry with NO blob (structurally terminal — it
    /// can never open, detected before any key/network), and item at seq 6 is a TOMBSTONE (a "good"
    /// action that applies with no key/blob). After the fix: seq 5 is skipped (error recorded, cursor
    /// advanced), seq 6's tombstone APPLIES (`tombstoned == 1`) and the cursor advances to 6. RED on the
    /// old break-all code: seq 5 breaks the loop → seq 6 never processed → `tombstoned == 0`, cursor
    /// unchanged.
    #[test]
    fn org_sync_skips_a_terminal_item_and_ingests_the_next() {
        use std::io::{Read, Write};
        // One-shot local server answering exactly one `GET /v1/orgs/{id}/items` feed page.
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut sock, _) = listener.accept().unwrap();
            let mut buf = [0u8; 8192];
            let _ = sock.read(&mut buf).unwrap();
            // seq 5: LIVE (tombstoned:false) but blobId:null → TERMINAL missing-blob.
            // seq 6: TOMBSTONE → applies without a key/blob (the "good" item behind the poison one).
            let body = r#"{"items":[{"itemId":"poison","seq":5,"authorUserId":"u","rev":1,"generation":1,"createdAt":"2026-07-11T09:00:00Z","tombstoned":false,"blobId":null,"contentSha256":null},{"itemId":"good-tomb","seq":6,"authorUserId":"u","rev":1,"generation":1,"createdAt":"2026-07-11T09:01:00Z","tombstoned":true,"blobId":null,"contentSha256":null}],"nextSeq":6}"#;
            let resp = format!(
                                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{body}",
                                    body.len()
                                );
            let _ = sock.write_all(resp.as_bytes());
        });

        let state = build_state("org-sync-terminal-skip");
        seed_org(&state.db, "org-x", "X", "member", 1);
        state.db.set_org_last_seq("org-x", 4).unwrap(); // cursor starts at 4 (items 5,6 are new)
        state.config.lock().unwrap().share_base_url = format!("http://{addr}");
        *state.account_session.lock().unwrap() = Some(crate::share::AccountSession {
            account_id: "user@example.com".into(),
            email: "user@example.com".into(),
            server_user_id: Some("c534b6d2-02c1-4c2c-a256-3af8592b1567".into()),
            device_id: "dev-1".into(),
            mk: Zeroizing::new([7u8; 32]),
            generation: 1,
            access_token: "a".into(),
            access_expires_at: Some("2099-01-01T00:00:00Z".into()),
            refresh_token: "r".into(),
        });

        let report = block_on(org_sync_one_now_inner(&state, "org-x")).unwrap();
        server.join().unwrap();

        // Both items were pulled; the terminal one was recorded as an error, the good one APPLIED.
        assert_eq!(report.pulled, 2, "both feed items were pulled");
        assert_eq!(
            report.tombstoned, 1,
            "the GOOD item behind the poison one ingested (RED on break-all: this was 0)"
        );
        assert!(
            report
                .errors
                .iter()
                .any(|e| e.contains("poison") && e.contains("missing blob")),
            "the terminal item is recorded as an error, not silently dropped: {:?}",
            report.errors
        );
        // The cursor advanced PAST both the skipped terminal item and the applied tombstone.
        assert_eq!(
            state.db.get_org_state("org-x").unwrap().unwrap().last_seq,
            6,
            "cursor advanced past the terminal item AND the good one (RED on break-all: stayed at 4)"
        );
    }

    /// READER-FIRST TASK COMPATIBILITY. This runs the real encrypted feed/blob/open/apply loop with
    /// the exact kind discriminator frozen from the pre-Task client revision. A Task cell at seq 2
    /// must fail that old reader closed, claim only seq 2 through the production terminal-skip path,
    /// and still ingest the following Note at seq 3 in the same page. The pinned release receipt,
    /// hashed source excerpts and canonical content hashes keep this executable in shallow CI
    /// checkouts rather than depending on historical Git objects being locally available.
    #[test]
    fn pre_task_reader_terminal_skips_encrypted_task_and_ingests_later_note() {
        use crate::share::org_envelope::{seal_org_envelope, OrgEnvelope, OrgItemKind, OrgSourceKind};
        use crate::share::task_envelope::{TaskEnvelope, TaskStatus, TASK_ENVELOPE_VERSION};
        use sha2::{Digest, Sha256};
        use std::io::{Read, Write};

        const FROZEN_PRE_TASK_KIND_DISCRIMINATOR: &str = concat!(
            "    fn from_tag(t: u8) -> Result<Self> {\n",
            "        match t {\n",
            "            1 => Ok(OrgItemKind::Note),\n",
            "            2 => Ok(OrgItemKind::Summary),\n",
            "            _ => Err(AppError::InvalidArg(\"unknown org item kind tag\".into())),\n",
            "        }\n",
            "    }\n",
        );
        const FROZEN_PRE_TASK_TERMINAL_SKIP: &str = concat!(
            "                        FeedAction::SkipTerminal { seq } => {\n",
            "                            let Some(_applied) =\n",
            "                                policy.commit(|| db.commit_org_feed_terminal_skip(&org_id, seq))?\n",
            "                            else {\n",
            "                                break;\n",
            "                            };\n",
        );

        assert_eq!(
            PRE_TASK_READER_REVISION,
            "abb6971607d221bfe728d4ff5202ccde7872fcf8"
        );
        assert_eq!(PRE_TASK_READER_RELEASE_TAG, "v1.1.0");
        assert_eq!(
            PRE_TASK_READER_RELEASE_SUBJECT,
            "Merge pull request #533 from murmur-io/chore/release-1.1.0"
        );
        assert_eq!(
            PRE_TASK_READER_COMPAT_REVISION,
            "2e6ff1eaa35273347a19e7284837f86432f80195"
        );
        println!(
            "MURMUR_TASK_READER_FIRST_RELEASE tag={} release_sha={} compat_sha={}",
            PRE_TASK_READER_RELEASE_TAG, PRE_TASK_READER_REVISION, PRE_TASK_READER_COMPAT_REVISION
        );
        assert_eq!(
            PRE_TASK_ORG_ENVELOPE_BLOB_SHA1,
            "7a49b5b7b70ab3ea0cd66e77280866b61c6780ee"
        );
        assert_eq!(
            PRE_TASK_ORG_ENVELOPE_SOURCE_SHA256,
            "18e76f37177cee674bec35df3849fcbbbe50d504603f6e40fb36d7660a41070f"
        );
        assert_eq!(
            PRE_TASK_RELEASE_ORG_COMMANDS_BLOB_SHA1,
            "141290c2e518dfab109df9ff93be09b50d586a65"
        );
        assert_eq!(
            PRE_TASK_RELEASE_ORG_COMMANDS_SOURCE_SHA256,
            "a88eacd9920b9a47221804910e467f52f7eb546ba9dec676cab7a250a6029392"
        );
        assert_eq!(
            PRE_TASK_KIND_DISCRIMINATOR_SHA256,
            "6fe0b52de9d7165a21e04dc6b11f92252ca796d2308a02c8427671f233426210"
        );
        assert_eq!(
            PRE_TASK_TERMINAL_SKIP_SHA256,
            "ee38b7539c693e708a0c9df61fa5404224eb27f82e52fa61c1fe265fd1e5254a"
        );

        assert_eq!(
            PRE_TASK_ORG_ENVELOPE_BLOB_SHA1,
            "7a49b5b7b70ab3ea0cd66e77280866b61c6780ee"
        );
        assert_eq!(
            PRE_TASK_ORG_ENVELOPE_SOURCE_SHA256,
            "18e76f37177cee674bec35df3849fcbbbe50d504603f6e40fb36d7660a41070f"
        );
        assert_eq!(
            org_item_nonce(&Sha256::digest(
                FROZEN_PRE_TASK_KIND_DISCRIMINATOR.as_bytes()
            )),
            PRE_TASK_KIND_DISCRIMINATOR_SHA256,
            "the immediate pre-Task reader must retain the exact v1.1.0 kind discriminator"
        );
        assert!(FROZEN_PRE_TASK_KIND_DISCRIMINATOR.contains("1 => Ok(OrgItemKind::Note)"));
        assert!(FROZEN_PRE_TASK_KIND_DISCRIMINATOR.contains("2 => Ok(OrgItemKind::Summary)"));
        assert!(FROZEN_PRE_TASK_KIND_DISCRIMINATOR
            .contains("_ => Err(AppError::InvalidArg(\"unknown org item kind tag\".into()))"));
        assert!(
            !FROZEN_PRE_TASK_KIND_DISCRIMINATOR.contains("3 => Ok(OrgItemKind::Task)"),
            "the pinned reader source itself must prove Task tag 3 was unknown"
        );
        assert_eq!(
            PRE_TASK_RELEASE_ORG_COMMANDS_BLOB_SHA1,
            "141290c2e518dfab109df9ff93be09b50d586a65"
        );
        assert_eq!(
            PRE_TASK_RELEASE_ORG_COMMANDS_SOURCE_SHA256,
            "a88eacd9920b9a47221804910e467f52f7eb546ba9dec676cab7a250a6029392"
        );
        assert_eq!(
            PRE_TASK_COMPAT_ORG_COMMANDS_BLOB_SHA1,
            "59538a6b230459f96bd4349e85fb4eb9b570951c"
        );
        assert_eq!(
            PRE_TASK_COMPAT_ORG_COMMANDS_SOURCE_SHA256,
            "3b2cb4688e360e2e16b57136401df938b5a1c33b2c876b64c6346bcec2d1b49d"
        );
        assert_eq!(
            org_item_nonce(&Sha256::digest(FROZEN_PRE_TASK_TERMINAL_SKIP.as_bytes())),
            PRE_TASK_TERMINAL_SKIP_SHA256,
            "the immediate pre-Task reader must retain the exact v1.1.0 terminal-skip arm"
        );
        assert!(FROZEN_PRE_TASK_TERMINAL_SKIP
            .contains("policy.commit(|| db.commit_org_feed_terminal_skip(&org_id, seq))?"));
        // Rollout receipt: the verified reader+feed implementation shipped in v1.1.0, the generic
        // stable-document relay already accepted opaque ciphertext, and only the descendant
        // immutable Harness writer candidate adds Task writers. Old readers therefore skip tag 3
        // before any Task writer can publish it.

        let ock = [13_u8; 32];
        let task_payload = TaskEnvelope {
            version: TASK_ENVELOPE_VERSION,
            org_id: STABLE_ORG_ID.into(),
            title: "Legacy task".into(),
            description: "must remain opaque to the old reader".into(),
            status: TaskStatus::Todo,
            due_at: None,
            assignee_user_id: None,
            created_at: "2026-08-22T09:00:01Z".into(),
            subtasks: Vec::new(),
            org_refs: Vec::new(),
            images: Vec::new(),
        };
        let task_json = task_payload.to_canonical_json(STABLE_ORG_ID).unwrap();
        let task = OrgEnvelope::new(
            OrgItemKind::Task,
            "Legacy task",
            task_json,
            "author",
            "2026-08-22T09:00:01Z",
            1,
            OrgSourceKind::Task,
        );
        let later_note = OrgEnvelope::new(
            OrgItemKind::Note,
            "Later note",
            "the old reader must still ingest this plaintext",
            "author",
            "2026-08-22T09:00:02Z",
            1,
            OrgSourceKind::Document,
        );
        let task_sha = task.content_sha256();
        let note_sha = later_note.content_sha256();
        assert_eq!(
            org_item_nonce(&task_sha),
            "a88cb0d3e7e6666c7fe99a896a0b93d6af359e19c034111f5dc6e91dc60032f3"
        );
        assert_eq!(
            org_item_nonce(&note_sha),
            "e1016d285098bd1157747918cce8d33ffeb85ad7f27140964e70bd0cf4134916"
        );
        let (task_ciphertext, _) =
            seal_org_envelope(&ock, &task, STABLE_ORG_ID, &org_item_nonce(&task_sha)).unwrap();
        let (note_ciphertext, _) =
            seal_org_envelope(&ock, &later_note, STABLE_ORG_ID, &org_item_nonce(&note_sha)).unwrap();

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            for _ in 0..3 {
                let (mut socket, _) = accept_with_timeout(&listener);
                socket.set_nonblocking(false).unwrap();
                let mut request = [0_u8; 8192];
                let read = socket.read(&mut request).unwrap();
                let first_line = String::from_utf8_lossy(&request[..read])
                    .lines()
                    .next()
                    .unwrap_or_default()
                    .to_string();
                if first_line.contains("/v1/orgs/") {
                    let body = format!(
                        "{{\"items\":[{{\"itemId\":\"legacy-task-item\",\"seq\":2,\"authorUserId\":\"author-1\",\"rev\":1,\"generation\":1,\"createdAt\":\"2026-08-22T09:00:01Z\",\"tombstoned\":false,\"blobId\":\"legacy-task-blob\",\"contentSha256\":\"{}\"}},{{\"itemId\":\"later-note-item\",\"seq\":3,\"authorUserId\":\"author-1\",\"rev\":1,\"generation\":1,\"createdAt\":\"2026-08-22T09:00:02Z\",\"tombstoned\":false,\"blobId\":\"later-note-blob\",\"contentSha256\":\"{}\"}}],\"nextSeq\":3}}",
                        murmur_protocol::b64::encode(&task_sha),
                        murmur_protocol::b64::encode(&note_sha),
                    );
                    write!(
                        socket,
                        "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{body}",
                        body.len(),
                    )
                    .unwrap();
                } else {
                    let ciphertext = if first_line.contains("/v1/blobs/legacy-task-blob") {
                        &task_ciphertext
                    } else if first_line.contains("/v1/blobs/later-note-blob") {
                        &note_ciphertext
                    } else {
                        panic!("unexpected legacy reader request: {first_line}");
                    };
                    write!(
                        socket,
                        "HTTP/1.1 200 OK\r\ncontent-type: application/octet-stream\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                        ciphertext.len(),
                    )
                    .unwrap();
                    socket.write_all(ciphertext).unwrap();
                }
                socket.flush().unwrap();
            }
        });

        let state = build_state("pre-task-reader-feed");
        seed_org(&state.db, STABLE_ORG_ID, "Reader-first org", "member", 1);
        let before = Db::prepare_org_item_index("Earlier note", "t", "earlier body", None).unwrap();
        assert!(state
            .db
            .commit_org_feed_item(
                "earlier-note-item",
                STABLE_ORG_ID,
                1,
                "author",
                "Earlier note",
                "earlier body",
                "2026-08-22T09:00:00Z",
                1,
                1,
                &[1_u8; 32],
                Some("document"),
                Some("author-1"),
                &before,
            )
            .unwrap());
        state.config.lock().unwrap().share_base_url = format!("http://{addr}");
        seed_live_session(&state);
        state
            .org_ock_cache
            .lock()
            .unwrap()
            .insert((STABLE_ORG_ID.to_string(), 1), Zeroizing::new(ock));

        let report = block_on(org_sync_one_now_with_pre_task_reader(&state, STABLE_ORG_ID)).unwrap();
        server.join().unwrap();

        assert_eq!(report.pulled, 2);
        assert_eq!(
            report.ingested, 1,
            "only the later Note may project plaintext"
        );
        assert_eq!(state.db.org_last_seq_for(STABLE_ORG_ID).unwrap(), 3);
        assert!(state.db.get_org_item("legacy-task-item").unwrap().is_none());
        assert!(state
            .db
            .list_org_tasks(Some(STABLE_ORG_ID))
            .unwrap()
            .is_empty());
        assert_eq!(
            state
                .db
                .get_org_item("later-note-item")
                .unwrap()
                .unwrap()
                .markdown,
            "the old reader must still ingest this plaintext"
        );
        assert!(report.errors.iter().any(|error| {
            error.contains("legacy-task-item") && error.contains("envelope open failed")
        }));
    }

    /// Cross-repository stable-wire receipt. The client-owned JSON vectors are deserialized by the
    /// exact `murmur_protocol::dto` crate from the sibling server revision pinned by
    /// `.murmur-server-revision`; this is stronger than checking only a client mock or only the
    /// server's independent suite.
    #[test]
    fn task_stable_post_and_put_vectors_match_pinned_server_protocol() {
        use crate::share::org_dto::{
            OrgItemAccess, PublishItemRequest as ClientPublish, UpdateOrgItemRequest as ClientUpdate,
        };
        use std::process::Command;

        let repo = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .unwrap();
        let pinned = std::fs::read_to_string(repo.join(".murmur-server-revision"))
            .expect("server revision pin")
            .trim()
            .to_string();
        let server_repo = repo.parent().unwrap().join("murmur-server");
        let server_head = Command::new("git")
            .args(["-C"])
            .arg(&server_repo)
            .args(["rev-parse", "HEAD"])
            .output()
            .expect("pinned sibling server checkout must be readable");
        assert!(server_head.status.success());
        assert_eq!(
            String::from_utf8(server_head.stdout).unwrap().trim(),
            pinned,
            "the protocol DTO parser must come from the exact pinned server checkout"
        );

        let doc_id = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
        let cell = vec![0, 255, 1, 254, 2, 253];
        let semantic_sha = vec![7; 32];
        let post = ClientPublish {
            mutation_id: None,
            doc_id: Some(doc_id.into()),
            access: Some(OrgItemAccess::Edit),
            blob_id: None,
            content_cell: Some(cell.clone()),
            content_sha256: semantic_sha.clone(),
            rev: 1,
            generation: 3,
        };
        let post_json = serde_json::to_vec(&post).unwrap();
        let server_post: murmur_protocol::dto::PublishItemRequest =
            serde_json::from_slice(&post_json).expect("pinned server must accept Task POST vector");
        assert_eq!(server_post.doc_id.as_deref(), Some(doc_id));
        assert_eq!(server_post.rev, 1);
        assert_eq!(server_post.generation, 3);
        assert_eq!(server_post.content_cell.as_deref(), Some(cell.as_slice()));
        assert_eq!(server_post.content_sha256, semantic_sha);
        assert!(matches!(
            server_post.access,
            Some(murmur_protocol::dto::OrgItemAccess::Edit)
        ));

        let update = ClientUpdate {
            mutation_id: None,
            expected_rev: 1,
            content_cell: cell.clone(),
            content_sha256: vec![8; 32],
            generation: 3,
        };
        let update_json = serde_json::to_vec(&update).unwrap();
        let server_update: murmur_protocol::dto::UpdateOrgItemRequest =
            serde_json::from_slice(&update_json).expect("pinned server must accept Task PUT vector");
        assert_eq!(server_update.expected_rev, 1);
        assert_eq!(server_update.generation, 3);
        assert_eq!(server_update.content_cell, cell);
        assert_eq!(server_update.content_sha256, vec![8; 32]);
        assert!(server_update.mutation_id.is_none());
        println!(
            "MURMUR_TASK_PINNED_PROTOCOL server_sha={} post_rev=1 put_expected_rev=1 stable_doc_id={}",
            pinned, doc_id
        );
    }

    /// STALE-INGEST AUTHOR BACKFILL (root-cause fix, RED→GREEN): an `org_items` row ingested before
    /// `author_user_id` existed (or one whose seq is already behind the sync cursor) has NULL
    /// `author_user_id` forever under the OLD cursor-only pull, because the feed is only ever asked for
    /// `seq > cursor` — the author's own second machine can never recognise the item as its own, so
    /// `org_get_item`'s `editable` stays false no matter how many times sync runs. Seed a LIVE local
    /// `org_items` row with `author_user_id = NULL` at seq 3, and advance the cursor to 5 (simulating an
    /// already-caught-up device — a plain cursor pull would fetch NOTHING new). The bounded scheduler
    /// alternates a normal `sinceSeq=5` turn with a bounded backfill turn starting immediately before
    /// the stale row (`seq=3` ⇒ `sinceSeq=2`), so drive TWO ticks; the mock returns the SAME item with
    /// its authorUserId on the backfill turn. The server loop is bounded so a regression fails instead
    /// of hanging the entire suite on a second blocking `accept()`.
    #[test]
    fn org_sync_backfills_null_author_for_an_already_ingested_item() {
        use std::io::{Read, Write};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let addr = listener.local_addr().unwrap();
        let me_uuid = "c534b6d2-02c1-4c2c-a256-3af8592b1567";
        let server = std::thread::spawn(move || {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            let mut served = 0usize;
            while served < 2 && std::time::Instant::now() < deadline {
                let (mut sock, _) = match listener.accept() {
                    Ok(v) => v,
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(10));
                        continue;
                    }
                    Err(e) => panic!("author-backfill mock accept failed: {e}"),
                };
                sock.set_nonblocking(false).unwrap();
                sock.set_read_timeout(Some(std::time::Duration::from_secs(1)))
                    .unwrap();
                served += 1;
                let mut buf = [0u8; 8192];
                let n = sock.read(&mut buf).unwrap();
                let req = String::from_utf8_lossy(&buf[..n]);
                let body = if req.contains("sinceSeq=2") {
                    // The backfill's full re-pull: the SAME item, now WITH its real author id.
                    // `contentSha256` is base64URL-NO-PAD (`murmur_protocol::b64`) — 32 zero bytes.
                    format!(
                        r#"{{"items":[{{"itemId":"item-stale","seq":3,"authorUserId":"{me_uuid}","rev":1,"generation":1,"createdAt":"2026-07-11T09:00:00Z","tombstoned":false,"blobId":"b1","contentSha256":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"}}],"nextSeq":3}}"#
                    )
                } else {
                    // The normal cursor pull from seq 5: nothing new (device already caught up).
                    r#"{"items":[],"nextSeq":5}"#.to_string()
                };
                let resp = format!(
                                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{body}",
                                    body.len()
                                );
                let _ = sock.write_all(resp.as_bytes());
                let _ = sock.flush();
                let _ = sock.shutdown(std::net::Shutdown::Write);
                // Let the client fully drain the response before this socket is dropped (dropping
                // immediately can race a `connection: close` RST ahead of the client's read).
                let mut drain = [0u8; 64];
                loop {
                    match sock.read(&mut drain) {
                        Ok(0) | Err(_) => break,
                        Ok(_) => continue,
                    }
                }
            }
            served
        });

        let state = build_state("org-sync-author-backfill");
        seed_org(&state.db, "org-y", "Y", "member", 1);
        // A LIVE local replica row ingested BEFORE author stamping existed: author_user_id NULL.
        state
            .db
            .upsert_org_item(
                "item-stale",
                "org-y",
                3,
                "anna",
                "Old note",
                "# body",
                "2026-07-11T09:00:00Z",
                1,
                1,
                &[9u8; 32],
                Some("document"),
                None, // author_user_id: unknown at ingest — this row IS the stale-ingest gap under test.
                None,
            )
            .unwrap();
        assert_eq!(
            state
                .db
                .org_item_edit_ctx("item-stale")
                .unwrap()
                .unwrap()
                .author_user_id,
            None,
            "precondition: the stale row starts with no stamped author"
        );
        // Cursor already PAST the item's seq — a plain cursor pull will never re-see it.
        state.db.set_org_last_seq("org-y", 5).unwrap();
        state.config.lock().unwrap().share_base_url = format!("http://{addr}");
        *state.account_session.lock().unwrap() = Some(crate::share::AccountSession {
            account_id: "user@example.com".into(),
            email: "user@example.com".into(),
            server_user_id: Some(me_uuid.into()),
            device_id: "dev-2".into(),
            mk: Zeroizing::new([7u8; 32]),
            generation: 1,
            access_token: "a".into(),
            access_expires_at: Some("2099-01-01T00:00:00Z".into()),
            refresh_token: "r".into(),
        });

        let first = block_on(org_sync_one_now_inner(&state, "org-y")).unwrap();
        let second = block_on(org_sync_one_now_inner(&state, "org-y")).unwrap();
        let served = server.join().unwrap();
        assert_eq!(
            served, 2,
            "sync must issue cursor + author-backfill requests"
        );

        assert_eq!(
            first.authors_backfilled + second.authors_backfilled,
            1,
            "the two bounded sync turns backfilled exactly one stale-NULL row: first={:?}, second={:?}",
            first.errors,
            second.errors,
        );
        // The local row now carries the real author id (GREEN — RED on the pre-fix code: this stayed
        // None forever, since the cursor pull alone never re-visits an already-ingested seq).
        let ctx = state.db.org_item_edit_ctx("item-stale").unwrap().unwrap();
        assert_eq!(ctx.author_user_id.as_deref(), Some(me_uuid));
        // The cursor itself is UNCHANGED by the backfill (it's a read-only side query, not a re-ingest).
        assert_eq!(
            state.db.get_org_state("org-y").unwrap().unwrap().last_seq,
            5
        );

        // End-to-end: replays `org_get_item`'s own editable-resolution logic (it takes a Tauri `State`
        // wrapper the test suite has no constructor for elsewhere, so we drive the same two calls the
        // command body makes) — the actual user-facing bug was "can't edit my own note from a second
        // device", so the test must prove `editable` flips true, not just that storage round-trips.
        let mut detail = state
            .db
            .get_org_item("item-stale")
            .unwrap()
            .expect("item still resolves");
        if let Some(edit_ctx) = state.db.org_item_edit_ctx("item-stale").unwrap() {
            if let (Some(author), Ok(me)) = (
                edit_ctx.author_user_id.as_deref(),
                session_server_user_id(&state),
            ) {
                detail.editable = author == me;
            }
        }
        assert!(
            detail.editable,
            "editable must flip true once author_user_id is backfilled to match the caller's session"
        );
    }

    /// F1 (MULTI-ORG TARGETING, RED→GREEN for the `.next()` misroute): with TWO local orgs, the org
    /// commands must resolve the SPECIFIC org the FE passed, never the FIRST. `resolve_org` — the
    /// shared resolution seam every per-org command now uses — must return the SECOND org's row when
    /// asked for it (RED on any `.next()`/first-only resolution: it would return org #1's row), refuse
    /// a blank id, and refuse an org the caller isn't a local member of.
    #[test]
    fn resolve_org_targets_the_specified_org_not_the_first() {
        let state = build_state("org-resolve-target");
        // `org-first` joined EARLIER → it is the deterministic `.next()` (ORDER BY joined_at ASC) org,
        // so a pre-fix first-only resolve would return it — making the RED direction unambiguous.
        seed_org_at(
            &state.db,
            "org-first",
            "First",
            "owner",
            "2026-07-01T00:00:00Z",
        );
        seed_org_at(
            &state.db,
            "org-second",
            "Second",
            "member",
            "2026-07-11T00:00:00Z",
        );

        // Ask for the SECOND org explicitly → get the SECOND (not the first-by-.next()).
        let got = resolve_org(&state, "org-second").unwrap();
        assert_eq!(
            got.org_id, "org-second",
            "resolve targets the specified org, not the first (RED on a .next() resolve)"
        );
        assert_eq!(got.role, "member");
        // And the first, explicitly, still resolves to the first.
        assert_eq!(
            resolve_org(&state, "org-first").unwrap().org_id,
            "org-first"
        );

        // A blank id is an InvalidArg refusal (never a silent first-org pick).
        assert!(matches!(
            resolve_org(&state, "  "),
            Err(AppError::InvalidArg(_))
        ));
        // An org we're not a local member of is refused — we never operate on an org the caller isn't in.
        assert!(matches!(
            resolve_org(&state, "org-not-mine"),
            Err(AppError::InvalidArg(_))
        ));
    }

    /// FIX C (org SHARE targets the SPECIFIED org, RED→GREEN for the `.next()` MISROUTE): with TWO
    /// local orgs, `share_to_org_inner` must queue the outbound share under the org the FE PICKED, never
    /// the FIRST (`.next()`). Seed a session + consent + an open (unlocked) meeting with a note, point
    /// the client at a CLOSED loopback port (no real egress — the seal/upload fails), and share TARGETING
    /// the SECOND org. Regardless of the network failure, the QUEUED row is persisted BEFORE any egress —
    /// under `org-second`. RED on the pre-fix code (it `.next()`-picked `org-first` → the row landed under
    /// org #1); GREEN after routing through `resolve_org`.
    #[test]
    fn share_to_org_queues_under_the_specified_org_not_the_first() {
        let state = build_state("org-share-target");
        // `org-first` joined EARLIER → the deterministic `.next()` (ORDER BY joined_at ASC) org a pre-fix
        // share would have wrongly used. The FE picks `org-second`.
        seed_org_at(
            &state.db,
            "org-first",
            "First",
            "owner",
            "2026-07-01T00:00:00Z",
        );
        seed_org_at(
            &state.db,
            "org-second",
            "Second",
            "member",
            "2026-07-11T00:00:00Z",
        );

        // An OPEN folder + a note so the read-gate + clean/scrub pass (no lock).
        state
            .db
            .insert_folder(&Folder {
                id: "f-share".to_string(),
                name: "Team".to_string(),
                path: "Team".to_string(),
                parent_id: None,
                locked: false,
                created_at: "2026-07-11T00:00:00Z".to_string(),
            })
            .unwrap();
        state
            .db
            .insert_note(
                "n-share",
                "f-share",
                "plan",
                "Q3 Plan",
                "# the Q3 roadmap",
                1,
            )
            .unwrap();

        // Consent granted + a closed loopback port (connection refused; NO real egress).
        state.config.lock().unwrap().org_egress_consented = true;
        state.config.lock().unwrap().share_base_url = "http://127.0.0.1:9/".to_string();
        // A live (non-expired) session so `require_session_mk` yields a bearer and the queue insert runs.
        *state.account_session.lock().unwrap() = Some(crate::share::AccountSession {
            account_id: "user@example.com".into(),
            email: "user@example.com".into(),
            server_user_id: Some("c534b6d2-02c1-4c2c-a256-3af8592b1567".into()),
            device_id: "dev-1".into(),
            mk: Zeroizing::new([7u8; 32]),
            generation: 1,
            access_token: "a".into(),
            access_expires_at: Some("2099-01-01T00:00:00Z".into()),
            refresh_token: "r".into(),
        });

        // Share TARGETING the SECOND org. The network egress fails (closed port), but the QUEUED row is
        // written first — under the resolved target org.
        let _ = block_on(share_to_org_inner(
            &state,
            "org-second",
            None,
            Some("n-share".to_string()),
            true,
        ));

        // The row MUST be under org-second (the picked org), NOT org-first (the `.next()` org).
        let second = state.db.list_org_shares_for_org("org-second").unwrap();
        assert_eq!(
            second.len(),
            1,
            "the outbound share was queued under the PICKED org (org-second)"
        );
        assert_eq!(second[0].document_id.as_deref(), Some("n-share"));
        let first = state.db.list_org_shares_for_org("org-first").unwrap();
        assert!(
                                first.is_empty(),
                                "no share landed under the FIRST org (RED on a .next() misroute — the row was under org-first)"
                            );
    }

    // ── RE-PUBLISH-ON-EDIT (the stale-org-copy fix) — end-to-end against a MOCK org server ─────────

    /// What a `MockOrgServer` recorded across a test: the sequence of published item ids (one per
    /// `POST …/items`) and the set of tombstoned item ids (one per `DELETE …/items/{id}`). Lets a
    /// republish test assert BOTH the new-item-published AND the old-item-tombstoned sides.
    #[derive(Default)]
    struct MockOrgLog {
        requests: Vec<String>,
        published: Vec<String>,
        tombstoned: Vec<String>,
        published_content_sha256: Vec<String>,
        published_content_cells: Vec<String>,
        published_expected_revs: Vec<Option<u64>>,
        /// The feed the mock serves from `GET /v1/orgs/{id}/items?sinceSeq=&limit=`, ascending by
        /// `seq`. Seeded by a test (see `MockOrgServer::seed_feed`) so the anti-entropy reconcile
        /// sweep can be driven headless. METADATA ONLY — a record that is tombstoned, or whose
        /// `content_sha256` already matches the local replica, is decided without any blob, which is
        /// exactly the sweep's cheap path.
        feed: Vec<MockFeedEntry>,
        /// Every `sinceSeq` the client asked the feed for, in order — lets a test prove the SLOW
        /// reconcile cursor really restarts at 0 while the LIVE cursor stays where it was.
        feed_since: Vec<u64>,
    }

    /// One row of `MockOrgLog::feed` — the fields `share::org_dto::OrgItemEntry` deserializes.
    #[derive(Clone)]
    struct MockFeedEntry {
        item_id: String,
        seq: u64,
        tombstoned: bool,
        content_sha256: Option<Vec<u8>>,
    }

    impl MockFeedEntry {
        /// A withdrawn record. The real server writes `tombstoned_at` WITHOUT minting a fresh `seq`,
        /// so the seq stays the item's ORIGINAL one — which is the entire reason a member already
        /// past it never learns the item is gone.
        fn tombstoned(item_id: &str, seq: u64) -> Self {
            Self {
                item_id: item_id.into(),
                seq,
                tombstoned: true,
                content_sha256: None,
            }
        }

        /// A live record carrying its plaintext hash (no blob id ⇒ the sweep must decide it from the
        /// hash alone, never by fetching).
        fn live(item_id: &str, seq: u64, content_sha256: &[u8]) -> Self {
            Self {
                item_id: item_id.into(),
                seq,
                tombstoned: false,
                content_sha256: Some(content_sha256.to_vec()),
            }
        }

        /// Serialize exactly like the server's `OrgItemEntry` — camelCase, `murmur_protocol::b64`
        /// (base64url-unpadded) bytes, and the SAME optionality the real server emits: a tombstone
        /// OMITS `blobId`/`contentSha256` entirely rather than sending nulls (mirrors the fixture in
        /// `share::org_dto`'s own wire test).
        fn to_json(&self) -> String {
            let sha = match &self.content_sha256 {
                Some(bytes) => {
                    format!(
                        ",\"contentSha256\":\"{}\"",
                        murmur_protocol::b64::encode(bytes)
                    )
                }
                None => String::new(),
            };
            format!(
                            "{{\"itemId\":\"{}\",\"seq\":{},\"authorUserId\":\"author-1\",\"rev\":1,\
                                  \"generation\":1,\"createdAt\":\"2026-07-01T00:00:00Z\",\"tombstoned\":{}{}}}",
                            self.item_id, self.seq, self.tombstoned, sha
                        )
        }
    }

    /// A minimal in-process org server (tiny_http) that answers the TWO routes the atomic-inline org
    /// publish/republish flow hits — `POST /v1/orgs/{id}/items` and
    /// `DELETE /v1/orgs/{id}/items/{id}` — so seal→publish→tombstone runs headless without a backend.
    /// The OCK is pre-seeded into `org_ock_cache` so
    /// `acquire_org_ock` never needs the (unmocked) key-grants endpoint. Shuts down on drop.
    struct MockOrgServer {
        base: String,
        log: Arc<Mutex<MockOrgLog>>,
        shutdown: Arc<AtomicBool>,
        handle: Option<std::thread::JoinHandle<()>>,
    }

    impl MockOrgServer {
        fn start() -> Self {
            let server = tiny_http::Server::http("127.0.0.1:0").unwrap();
            let addr = server.server_addr();
            let base = format!("http://{}/", addr.to_ip().unwrap());
            let log = Arc::new(Mutex::new(MockOrgLog::default()));
            let shutdown = Arc::new(AtomicBool::new(false));
            let log_t = Arc::clone(&log);
            let shutdown_t = Arc::clone(&shutdown);
            let handle = std::thread::spawn(move || {
                let mut seq: u64 = 0;
                loop {
                    if shutdown_t.load(Ordering::SeqCst) {
                        break;
                    }
                    match server.recv_timeout(std::time::Duration::from_millis(50)) {
                        Ok(Some(mut req)) => {
                            let method = req.method().clone();
                            let url = req.url().to_string();
                            let path = url.split('?').next().unwrap_or("").to_string();
                            log_t
                                .lock()
                                .unwrap()
                                .requests
                                .push(format!("{method} {url}"));
                            if method == tiny_http::Method::Delete {
                                assert_eq!(url, path, "DELETE identifiers belong only in the path");
                                assert!(
                                    req.headers().iter().any(|header| {
                                        header.field.equiv("Authorization")
                                            && header.value.as_str().starts_with("Bearer ")
                                    }),
                                    "the access token must be carried only by Authorization"
                                );
                                let mut body = String::new();
                                std::io::Read::read_to_string(req.as_reader(), &mut body).unwrap();
                                assert!(body.is_empty(), "DELETE must carry no request body");
                            }
                            // POST creates a stable document; PUT CAS-replaces its head. Both return
                            // the same publish response shape and mint a fresh revision item id.
                            let is_post = method == tiny_http::Method::Post
                                && path.starts_with("/v1/orgs/")
                                && path.ends_with("/items");
                            let is_put = method == tiny_http::Method::Put
                                && path.starts_with("/v1/orgs/")
                                && path.contains("/documents/");
                            if is_post || is_put {
                                let mut request_body = String::new();
                                let _ =
                                    std::io::Read::read_to_string(req.as_reader(), &mut request_body);
                                let parsed = serde_json::from_str::<serde_json::Value>(&request_body)
                                    .unwrap_or(serde_json::Value::Null);
                                {
                                    let body = &parsed;
                                    log_t.lock().unwrap().published_expected_revs.push(
                                        body.get("expectedRev").and_then(serde_json::Value::as_u64),
                                    );
                                    if let Some(sha) = body
                                        .get("contentSha256")
                                        .and_then(serde_json::Value::as_str)
                                    {
                                        log_t
                                            .lock()
                                            .unwrap()
                                            .published_content_sha256
                                            .push(sha.to_string());
                                    }
                                    if let Some(cell) =
                                        body.get("contentCell").and_then(serde_json::Value::as_str)
                                    {
                                        log_t
                                            .lock()
                                            .unwrap()
                                            .published_content_cells
                                            .push(cell.to_string());
                                    }
                                }
                                seq += 1;
                                let item_id = format!("item-{seq}");
                                log_t.lock().unwrap().published.push(item_id.clone());
                                let doc_id = if is_put {
                                    path.rsplit('/').next().unwrap_or("doc-1")
                                } else {
                                    parsed
                                        .get("docId")
                                        .and_then(serde_json::Value::as_str)
                                        .unwrap_or("doc-1")
                                };
                                let access = parsed
                                    .get("access")
                                    .and_then(serde_json::Value::as_str)
                                    .unwrap_or("view");
                                let body = format!(
                                                    "{{\"itemId\":\"{item_id}\",\"seq\":{seq},\"docId\":\"{doc_id}\",\"access\":\"{access}\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\"}}"
                                                );
                                let resp = tiny_http::Response::from_string(body).with_header(
                                    "Content-Type: application/json"
                                        .parse::<tiny_http::Header>()
                                        .unwrap(),
                                );
                                let _ = req.respond(resp);
                                continue;
                            }
                            // GET /v1/orgs/{id}/items?sinceSeq=&limit= → the bounded append-only feed.
                            // Mirrors the real server EXACTLY on the property this whole fix is about:
                            // the window is `seq > sinceSeq`, and a tombstoned record keeps its
                            // ORIGINAL seq — so a caller whose cursor is already past it never sees it.
                            if method == tiny_http::Method::Get
                                && path.starts_with("/v1/orgs/")
                                && path.ends_with("/items")
                            {
                                let query = url.split_once('?').map(|(_, q)| q).unwrap_or("");
                                let param = |key: &str| -> Option<u64> {
                                    query.split('&').find_map(|kv| {
                                        kv.split_once('=').and_then(|(k, v)| {
                                            (k == key).then(|| v.parse::<u64>().ok()).flatten()
                                        })
                                    })
                                };
                                let since = param("sinceSeq").unwrap_or(0);
                                let limit = param("limit").unwrap_or(50) as usize;
                                let mut guard = log_t.lock().unwrap();
                                guard.feed_since.push(since);
                                let page: Vec<MockFeedEntry> = guard
                                    .feed
                                    .iter()
                                    .filter(|e| e.seq > since)
                                    .take(limit)
                                    .cloned()
                                    .collect();
                                drop(guard);
                                let next_seq = page.last().map(|e| e.seq).unwrap_or(since);
                                let items = page
                                    .iter()
                                    .map(MockFeedEntry::to_json)
                                    .collect::<Vec<_>>()
                                    .join(",");
                                let body = format!("{{\"items\":[{items}],\"nextSeq\":{next_seq}}}");
                                let resp = tiny_http::Response::from_string(body).with_header(
                                    "Content-Type: application/json"
                                        .parse::<tiny_http::Header>()
                                        .unwrap(),
                                );
                                let _ = req.respond(resp);
                                continue;
                            }
                            // DELETE /v1/orgs/{id}/items/{itemId} → 200 (tombstone)
                            if method == tiny_http::Method::Delete
                                && path.contains("/items/")
                                && !path.ends_with("/items")
                            {
                                if let Some(item) = path.rsplit('/').next() {
                                    log_t.lock().unwrap().tombstoned.push(item.to_string());
                                }
                                let _ = req.respond(tiny_http::Response::empty(200));
                                continue;
                            }
                            let _ = req.respond(tiny_http::Response::empty(404));
                        }
                        Ok(None) => continue,
                        Err(_) => break,
                    }
                }
            });
            Self {
                base,
                log,
                shutdown,
                handle: Some(handle),
            }
        }

        /// Install the records `GET …/items` will serve (ascending `seq`).
        fn seed_feed(&self, entries: Vec<MockFeedEntry>) {
            self.log.lock().unwrap().feed = entries;
        }

        /// Every `sinceSeq` the client has asked for so far, in order.
        fn feed_since(&self) -> Vec<u64> {
            self.log.lock().unwrap().feed_since.clone()
        }
    }

    impl Drop for MockOrgServer {
        fn drop(&mut self) {
            self.shutdown.store(true, Ordering::SeqCst);
            if let Some(h) = self.handle.take() {
                let _ = h.join();
            }
        }
    }

    /// Seed a live (non-expiring) session so `require_session_mk` / `valid_access_token` yield a bearer
    /// with NO network refresh — the mock server never sees an auth call.
    fn seed_live_session(state: &AppState) {
        *state.account_session.lock().unwrap() = Some(crate::share::AccountSession {
            account_id: "user@example.com".into(),
            email: "user@example.com".into(),
            server_user_id: Some("c534b6d2-02c1-4c2c-a256-3af8592b1567".into()),
            device_id: "dev-1".into(),
            mk: Zeroizing::new([7u8; 32]),
            generation: 1,
            access_token: "a".into(),
            access_expires_at: Some("2099-01-01T00:00:00Z".into()),
            refresh_token: "r".into(),
        });
    }

    /// Pre-seed the session OCK cache for `(org_id, generation)` so `acquire_org_ock` hits the cache
    /// and never touches the (unmocked) key-grants endpoint.
    fn seed_ock(state: &AppState, org_id: &str, generation: u32) {
        state
            .org_ock_cache
            .lock()
            .unwrap()
            .insert((org_id.to_string(), generation), Zeroizing::new([9u8; 32]));
    }

    fn seed_editable_stable_org_item(state: &AppState, item_id: &str, access: &str) {
        seed_org(&state.db, STABLE_ORG_ID, "Acme", "member", 1);
        state
            .db
            .upsert_org_item(
                item_id,
                STABLE_ORG_ID,
                1,
                "user",
                "Draft",
                "old body",
                "2026-08-13T00:00:00Z",
                1,
                1,
                &[1u8; 32],
                Some("document"),
                Some("c534b6d2-02c1-4c2c-a256-3af8592b1567"),
                None,
            )
            .unwrap();
        state
            .db
            .set_org_item_document_metadata(
                item_id,
                Some(STABLE_DOC_ID),
                access,
                Some("c534b6d2-02c1-4c2c-a256-3af8592b1567"),
            )
            .unwrap();
        state
            .db
            .repair_org_reconcile_metadata(
                item_id,
                STABLE_ORG_ID,
                1,
                Some(STABLE_DOC_ID),
                access,
                Some("c534b6d2-02c1-4c2c-a256-3af8592b1567"),
                true,
            )
            .unwrap();
        seed_live_session(state);
        seed_ock(state, STABLE_ORG_ID, 1);
        state.config.lock().unwrap().org_egress_consented = true;
    }

    fn direct_put_lost_response_server(
        authoritative_access: &'static str,
    ) -> (String, std::thread::JoinHandle<()>) {
        use std::io::Write;

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut put, _) = accept_with_timeout(&listener);
            let request = read_http_request(&mut put);
            let request_line = String::from_utf8_lossy(&request);
            assert!(request_line.starts_with(&format!(
                "PUT /v1/orgs/{STABLE_ORG_ID}/documents/{STABLE_DOC_ID}"
            )));
            let body_at = request.windows(4).position(|w| w == b"\r\n\r\n").unwrap() + 4;
            let json: serde_json::Value = serde_json::from_slice(&request[body_at..]).unwrap();
            assert!(
                json.get("mutationId").is_none(),
                "old strict relay rejects even a null mutationId"
            );
            assert_eq!(json["expectedRev"], 1);
            assert_eq!(json["generation"], 1);
            let sha = json["contentSha256"].as_str().unwrap().to_string();
            drop(put); // the relay committed, but the success response was lost

            let (mut get, _) = accept_with_timeout(&listener);
            let request = read_http_request(&mut get);
            assert!(String::from_utf8_lossy(&request)
                .starts_with(&format!("GET /v1/orgs/{STABLE_ORG_ID}/items?")));
            let body = format!(
                    "{{\"items\":[{{\"itemId\":\"item-old\",\"seq\":1,\"authorUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"rev\":1,\"generation\":1,\"createdAt\":\"2026-08-13T00:00:00Z\",\"tombstoned\":true,\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"edit\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"isCurrent\":false}},{{\"itemId\":\"item-new\",\"seq\":2,\"authorUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"rev\":2,\"generation\":1,\"createdAt\":\"2026-08-13T00:00:00Z\",\"tombstoned\":false,\"contentSha256\":\"{sha}\",\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"{authoritative_access}\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"isCurrent\":true}}],\"nextSeq\":2}}"
                );
            write!(
                    get,
                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                    body.len(),
                    body
                )
                .unwrap();
        });
        (format!("http://{addr}/"), server)
    }

    #[test]
    fn direct_put_response_lost_accepts_only_the_exact_authoritative_head() {
        let state = build_state("org-direct-put-lost-exact");
        seed_editable_stable_org_item(&state, "item-old", "edit");
        let (base, server) = direct_put_lost_response_server("edit");
        state.config.lock().unwrap().share_base_url = base;

        let updated = block_on(org_update_own_item_inner(
            &state, "item-old", "Updated", "new body",
        ));
        server.join().unwrap();
        assert_eq!(updated.unwrap(), "item-new");
        assert!(state.db.get_org_item("item-old").unwrap().is_none());
        let current = state.db.get_org_item("item-new").unwrap().unwrap();
        assert_eq!(current.title, "Updated");
        assert_eq!(current.access, "edit");
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_share_publish")
                .unwrap(),
            1,
            "dispatch and exact recovery share one idempotent ledger row"
        );
        assert_eq!(block_on(org_sweep_pending_inner(&state)).unwrap(), 0);
    }

    #[test]
    fn direct_put_head_mismatch_is_terminal_and_never_retried() {
        let state = build_state("org-direct-put-lost-mismatch");
        seed_editable_stable_org_item(&state, "item-old", "edit");
        let (base, server) = direct_put_lost_response_server("view");
        state.config.lock().unwrap().share_base_url = base;

        let error = block_on(org_update_own_item_inner(
            &state, "item-old", "Updated", "new body",
        ));
        server.join().unwrap();
        assert!(matches!(
            error,
            Err(AppError::InvalidArg(message)) if message.starts_with("[org-edit-conflict] ")
        ));
        let attempt = state
            .db
            .list_org_shares_for_org(STABLE_ORG_ID)
            .unwrap()
            .into_iter()
            .find(|row| row.last_error.as_deref() == Some(ORG_SHARE_ERR_EDIT_CONFLICT))
            .expect("the exact draft commitment remains durably terminal");
        assert_eq!(attempt.item_id.as_deref(), Some("item-old"));
        assert_eq!(attempt.doc_id.as_deref(), Some(STABLE_DOC_ID));
        assert_eq!(attempt.rev, 2);
        assert_eq!(attempt.generation, 1);
        assert_eq!(attempt.access, "edit");
        assert!(attempt.content_sha256.is_some());
        assert_eq!(block_on(org_sweep_pending_inner(&state)).unwrap(), 0);
        assert!(state.db.get_org_item("item-old").unwrap().is_some());
        assert!(state.db.get_org_item("item-new").unwrap().is_none());
    }

    #[test]
    fn direct_put_demoted_exact_target_behind_newer_head_remains_inconclusive() {
        use std::io::Write;
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut put, _) = accept_with_timeout(&listener);
            let request = read_http_request(&mut put);
            let body_at = request.windows(4).position(|w| w == b"\r\n\r\n").unwrap() + 4;
            let json: serde_json::Value = serde_json::from_slice(&request[body_at..]).unwrap();
            let sha = json["contentSha256"].as_str().unwrap();
            drop(put);
            let (mut get, _) = accept_with_timeout(&listener);
            let _ = read_http_request(&mut get);
            let body = format!(
                    "{{\"items\":[{{\"itemId\":\"item-old\",\"seq\":1,\"authorUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"rev\":1,\"generation\":1,\"createdAt\":\"t\",\"tombstoned\":true,\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"edit\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"isCurrent\":false}},{{\"itemId\":\"attempt-a\",\"seq\":2,\"authorUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"rev\":2,\"generation\":1,\"createdAt\":\"t\",\"tombstoned\":false,\"contentSha256\":\"{sha}\",\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"edit\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"isCurrent\":false}},{{\"itemId\":\"newer-b\",\"seq\":3,\"authorUserId\":\"other\",\"rev\":3,\"generation\":1,\"createdAt\":\"t\",\"tombstoned\":false,\"contentSha256\":\"{}\",\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"edit\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"isCurrent\":true}}],\"nextSeq\":3}}",
                    murmur_protocol::b64::encode(&[9u8;32]),
                );
            write!(get,"HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",body.len(),body).unwrap();
        });
        let state = build_state("org-direct-demoted-inconclusive");
        seed_editable_stable_org_item(&state, "item-old", "edit");
        state.config.lock().unwrap().share_base_url = format!("http://{addr}/");
        assert!(matches!(
            block_on(org_update_own_item_inner(
                &state, "item-old", "Updated", "body"
            )),
            Err(AppError::Unavailable(_))
        ));
        server.join().unwrap();
        let pending = state.db.list_org_shares_in_state("failed").unwrap();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].last_error.as_deref(), Some("direct_put_pending"));
        assert!(state.db.get_org_item("attempt-a").unwrap().is_none());
    }

    #[test]
    fn direct_put_wrong_doc_id_with_only_old_head_stays_pending_in_command_and_sweep() {
        use std::io::Write;

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut put, _) = accept_with_timeout(&listener);
            let request = read_http_request(&mut put);
            assert!(String::from_utf8_lossy(&request).starts_with(&format!(
                "PUT /v1/orgs/{STABLE_ORG_ID}/documents/{STABLE_DOC_ID}"
            )));
            let wrong_doc = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
            let wrong = format!(
                    "{{\"itemId\":\"wrong-doc-head\",\"seq\":2,\"docId\":\"{wrong_doc}\",\"access\":\"edit\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\"}}"
                );
            write!(
                    put,
                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                    wrong.len(),
                    wrong
                )
                .unwrap();

            let old_hash = murmur_protocol::b64::encode(&[1u8; 32]);
            let old = format!(
                    "{{\"items\":[{{\"itemId\":\"item-old\",\"seq\":1,\"authorUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"rev\":1,\"generation\":1,\"createdAt\":\"2026-08-13T00:00:00Z\",\"tombstoned\":false,\"contentSha256\":\"{old_hash}\",\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"edit\",\"documentOwnerUserId\":\"c534b6d2-02c1-4c2c-a256-3af8592b1567\",\"isCurrent\":true}}],\"nextSeq\":1}}"
                );
            for _ in 0..2 {
                let (mut get, _) = accept_with_timeout(&listener);
                let request = read_http_request(&mut get);
                assert!(String::from_utf8_lossy(&request)
                    .starts_with(&format!("GET /v1/orgs/{STABLE_ORG_ID}/items?")));
                write!(
                        get,
                        "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                        old.len(), old
                    )
                    .unwrap();
            }
        });

        let state = build_state("org-direct-put-wrong-doc-2xx");
        seed_editable_stable_org_item(&state, "item-old", "edit");
        state.config.lock().unwrap().share_base_url = format!("http://{addr}/");
        let result = block_on(org_update_own_item_inner(
            &state, "item-old", "Updated", "new body",
        ));
        assert!(matches!(result, Err(AppError::Unavailable(_))));
        let attempt = state
            .db
            .list_org_shares_for_org(STABLE_ORG_ID)
            .unwrap()
            .remove(0);
        assert_eq!(attempt.doc_id.as_deref(), Some(STABLE_DOC_ID));
        assert_eq!(attempt.access, "edit");
        assert_eq!(attempt.last_error.as_deref(), Some("direct_put_pending"));
        assert!(state.db.get_org_item("wrong-doc-head").unwrap().is_none());
        assert_eq!(block_on(org_sweep_pending_inner(&state)).unwrap(), 0);
        server.join().unwrap();
        let still_pending = state.db.get_org_share(&attempt.id).unwrap().unwrap();
        assert_eq!(
            still_pending.last_error.as_deref(),
            Some("direct_put_pending")
        );
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_share_publish")
                .unwrap(),
            1,
            "query-only recovery must not duplicate the dispatch ledger"
        );
    }

