    /// Install a raw SQLite guard/fault trigger on the test DB (dropped again by `drop_test_trigger`).
    /// This is the only seam that can interrupt a revoke BETWEEN its two local commits without adding
    /// a production-code test hook: SQLite enforces it inside the very transaction being committed.
    fn install_test_trigger(state: &AppState, sql: &str) {
        state.db.lock().execute_batch(sql).unwrap();
    }

    fn drop_test_trigger(state: &AppState, name: &str) {
        state
            .db
            .lock()
            .execute_batch(&format!("DROP TRIGGER {name};"))
            .unwrap();
    }

    /// THE REVOKE CRASH WINDOW, part 1 — the ORDERING itself.
    ///
    /// A revoke makes two SEPARATE local commits after the server DELETE lands: the `org_shares` state
    /// flip and the local replica eviction. Whichever runs second defines what a crash / quit /
    /// background-epoch flip between them leaves behind. Pre-fix the order was state-THEN-eviction, so
    /// the interrupted state was a row marked `revoked` whose decrypted replica — markdown, chunks,
    /// int8 vectors, FTS tokens, image BLOBs — was still live and searchable through org search / Ask /
    /// MCP `org_search`, and `org_sweep_pending` (which only re-drives `revoke_pending`) could never
    /// reach it again.
    ///
    /// The invariant is asserted where it actually lives — in the DB, not in the call sequence: a
    /// BEFORE-UPDATE trigger ABORTS any transition of a share row to `revoked` while that item's
    /// replica row is still live. On the pre-fix order that abort fires and the revoke returns `Err`
    /// (RED); on the fixed order the eviction has already happened, the guard is satisfied, and the
    /// revoke completes.
    #[test]
    fn revoke_evicts_the_local_replica_before_it_flips_the_share_to_revoked() {
        let mock = MockOrgServer::start();
        let state = build_state("org-revoke-order");
        seed_published_share_with_replica(&state, &mock.base);

        install_test_trigger(
                    &state,
                    "CREATE TRIGGER guard_revoke_order BEFORE UPDATE ON org_shares
                               WHEN NEW.state = 'revoked'
                                AND EXISTS (SELECT 1 FROM org_items
                                             WHERE item_id = NEW.item_id AND tombstoned = 0)
                             BEGIN
                               SELECT RAISE(ABORT, 'share flipped to revoked while its replica was still live');
                             END;",
                );

        block_on(revoke_org_share_inner(&state, "it-rv".to_string()))
            .expect("the eviction must be committed BEFORE the revoked state flip");

        assert_eq!(
            mock.log.lock().unwrap().tombstoned,
            vec!["it-rv".to_string()],
            "the server is still told FIRST — an eviction before a failed tombstone would blind us"
        );
        assert!(state.db.get_org_item("it-rv").unwrap().is_none());
        assert_eq!(replica_counts(&state, "it-rv"), (0, 0, 0, 0));
        assert_eq!(
            state.db.get_org_share("os-rv").unwrap().unwrap().state,
            "revoked"
        );
    }

    /// THE REVOKE CRASH WINDOW, part 2 — what an INTERRUPTION in the window actually leaves, and that
    /// the launch sweep still repairs it.
    ///
    /// The interruption is injected as a fault trigger that ABORTS the eviction's `org_items` write —
    /// the observable equivalent of the process dying at that instant: the server tombstone has landed,
    /// the eviction has not. What matters is the state the share row is left in.
    ///   - Pre-fix (state THEN eviction) it is `revoked`: `org_sweep_pending` only re-drives
    ///     `revoke_pending`, so the still-live replica is unreachable by the crash-safe recovery path.
    ///   - Post-fix (eviction THEN state) it is `revoke_pending`: both the server tombstone and the
    ///     eviction are idempotent, so the very next sweep re-drives the row and converges it.
    #[test]
    fn an_interrupted_revoke_leaves_a_re_drivable_row_not_a_live_orphaned_replica() {
        let mock = MockOrgServer::start();
        let state = build_state("org-revoke-interrupted");
        seed_published_share_with_replica(&state, &mock.base);

        // Fault injection: the eviction's tombstone write fails (≙ the process stopping right there).
        install_test_trigger(
                        &state,
                        "CREATE TRIGGER fault_on_evict BEFORE UPDATE ON org_items
                               WHEN NEW.tombstoned = 1
                             BEGIN SELECT RAISE(ABORT, 'simulated interruption during the local eviction'); END;",
                    );

        block_on(revoke_org_share_inner(&state, "it-rv".to_string()))
            .expect_err("the interrupted eviction must surface, not be silently swallowed");

        assert_eq!(
            mock.log.lock().unwrap().tombstoned,
            vec!["it-rv".to_string()],
            "the server withdrawal already happened — this is exactly the dangerous window"
        );
        assert!(
            state.db.get_org_item("it-rv").unwrap().is_some(),
            "the eviction really did not happen (its transaction rolled back)"
        );
        assert_eq!(
            state.db.get_org_share("os-rv").unwrap().unwrap().state,
            "revoke_pending",
            "an interruption must NEVER leave a `revoked` row whose replica is still live — that row \
                             re-enters no queue"
        );

        // The interruption is over (the app relaunches): the sweep re-drives the `revoke_pending` row.
        drop_test_trigger(&state, "fault_on_evict");
        assert!(block_on(org_sweep_pending_inner(&state)).unwrap() >= 1);

        assert!(
            state.db.get_org_item("it-rv").unwrap().is_none(),
            "the launch sweep converged the replica the interrupted revoke left behind"
        );
        assert_eq!(replica_counts(&state, "it-rv"), (0, 0, 0, 0));
        assert_eq!(
            state.db.get_org_share("os-rv").unwrap().unwrap().state,
            "revoked"
        );
    }

    /// DEFENCE IN DEPTH behind the ordering fix: `org_sweep_pending` now also converges a `revoked`
    /// row that still has a LIVE local replica — the shape a device interrupted under the OLD order is
    /// stuck in, and the one shape no queue used to re-drive. Local-only: no server, no session, no
    /// network call (the server tombstone already landed for a `revoked` row, so re-issuing it every
    /// launch would be pure waste).
    #[test]
    fn the_launch_sweep_evicts_an_orphaned_replica_of_an_already_revoked_share() {
        let state = build_state("org-revoked-orphan-repair");
        // No `share_base_url`, no session — deliberately: the repair must not depend on either (and
        // this test must never reach out to the default production host).
        state.config.lock().unwrap().share_base_url = String::new();
        seed_org(&state.db, "org-1", "Acme", "member", 1);
        state
            .db
            .insert_org_share(
                "os-orphan",
                "org-1",
                None,
                Some("n-orphan"),
                "note",
                Some("Quarterly acquisition plan"),
                1,
                1,
                &[7u8; 32],
                "2026-07-11T00:00:00Z",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("os-orphan", "it-orphan", "2026-07-11T00:00:00Z")
            .unwrap();
        state
            .db
            .set_org_share_state("os-orphan", "revoked", "2026-07-11T00:05:00Z")
            .unwrap();
        seed_replica_item(&state, "it-orphan", "org-1", 5);

        assert_eq!(block_on(org_sweep_pending_inner(&state)).unwrap(), 1);
        assert!(state.db.get_org_item("it-orphan").unwrap().is_none());
        assert_eq!(replica_counts(&state, "it-orphan"), (0, 0, 0, 0));

        // Converged ⇒ the next pass is a pure no-op (it must not keep counting the same row forever).
        assert_eq!(block_on(org_sweep_pending_inner(&state)).unwrap(), 0);
    }

    /// Records every [`crate::events::EVENT_ORG_FEED_UPDATED`] notice a command fires, so the "does the
    /// FE actually get told to re-fetch?" half of an org mutation is assertable without a Tauri runtime.
    #[derive(Default)]
    struct RecordingOrgFeedNotifier {
        calls: Mutex<Vec<u32>>,
    }

    impl crate::events::OrgFeedNotifier for RecordingOrgFeedNotifier {
        fn org_feed_updated(&self, orgs_changed: u32) {
            self.calls.lock().unwrap().push(orgs_changed);
        }
    }

    #[test]
    fn org_view_notification_emits_once_only_when_state_changed() {
        let notifier = RecordingOrgFeedNotifier::default();

        notify_org_views_if_changed(Some(&notifier), false);
        assert!(notifier.calls.lock().unwrap().is_empty());

        notify_org_views_if_changed(Some(&notifier), true);
        assert_eq!(
            *notifier.calls.lock().unwrap(),
            vec![0],
            "one changed local visibility state emits one content-free refetch notice"
        );
    }

    /// `revoke_org_share` was the ONLY org-item-mutating command that never emitted `org-feed-updated`
    /// — every sibling (`delete_org_item_as_author`, the share/publish paths) does. Now that a revoke
    /// mutates the LOCAL replica too, the omission left `OrgBrainService.loadOrgs()`, the Settings
    /// organization section and an open org-item viewer showing the withdrawn row until some unrelated
    /// productive sync tick (up to `ORG_SYNC_TICK_SECS` later, or never on a quiet feed) — and the
    /// reconcile sweep cannot cover the gap, since it emits only when it changed something and the item
    /// is already locally tombstoned by then.
    #[test]
    fn a_successful_revoke_tells_the_frontend_to_refresh() {
        let mock = MockOrgServer::start();
        let state = build_state("org-revoke-emits");
        seed_published_share_with_replica(&state, &mock.base);

        let notifier = RecordingOrgFeedNotifier::default();
        block_on(revoke_org_share_notifying(
            &state,
            "it-rv".to_string(),
            &notifier,
        ))
        .unwrap();

        assert_eq!(
            *notifier.calls.lock().unwrap(),
            vec![1],
            "a successful revoke must fire exactly one org-feed-updated notice"
        );
    }

    /// The flip side: a revoke that FAILED changed nothing the FE needs to re-fetch, so it must stay
    /// silent (a notice there would make every open view re-fetch identical state on every error).
    #[test]
    fn a_failed_revoke_does_not_tell_the_frontend_to_refresh() {
        let state = build_state("org-revoke-no-emit-on-failure");
        let notifier = RecordingOrgFeedNotifier::default();

        block_on(revoke_org_share_notifying(
            &state,
            "it-does-not-exist".to_string(),
            &notifier,
        ))
        .expect_err("no local org share for that item");

        assert!(notifier.calls.lock().unwrap().is_empty());
    }

    #[test]
    fn unrouted_document_delete_404_keeps_replica_and_revoke_pending() {
        let mock = MockOrgServer::start();
        let state = build_state("org-stable-delete-unrouted-404");
        seed_published_share_with_replica(&state, &mock.base);
        state
            .db
            .set_org_share_document_metadata("os-rv", STABLE_DOC_ID, "view")
            .unwrap();
        state
            .db
            .set_org_item_document_metadata(
                "it-rv",
                Some(STABLE_DOC_ID),
                "view",
                Some("c534b6d2-02c1-4c2c-a256-3af8592b1567"),
            )
            .unwrap();
        let replica_before = replica_counts(&state, "it-rv");
        assert!(replica_before.0 > 0 && replica_before.1 > 0 && replica_before.2 > 0);

        let error = block_on(revoke_org_share_inner(&state, "it-rv".into()))
            .expect_err("generic route 404 is not proof of stable withdrawal");
        assert!(matches!(
            error,
            AppError::InvalidArg(_) | AppError::Unavailable(_)
        ));
        assert_eq!(
            replica_counts(&state, "it-rv"),
            replica_before,
            "an unrouted 404 must not evict any decrypted replica material"
        );
        assert_eq!(
            state.db.get_org_share("os-rv").unwrap().unwrap().state,
            "revoke_pending"
        );
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_share_revoke")
                .unwrap(),
            1,
            "the destructive request attempt is ledgered before its unrouted 404 response"
        );
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_document_delete_404_read")
                .unwrap(),
            1,
            "the failed 404 corroboration GET has one durable pre-send receipt"
        );
    }

    fn seed_legacy_revoke_share(state: &AppState, base: &str) {
        seed_org(&state.db, STABLE_ORG_ID, "Acme", "member", 1);
        seed_live_session(state);
        state.config.lock().unwrap().org_egress_consented = true;
        state.config.lock().unwrap().share_base_url = base.to_string();
        state
            .db
            .insert_org_share(
                "legacy-row",
                STABLE_ORG_ID,
                None,
                Some("legacy-source"),
                "note",
                Some("Legacy"),
                1,
                1,
                &[3u8; 32],
                "t",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("legacy-row", "legacy-item", "t")
            .unwrap();
        state
            .db
            .upsert_org_item(
                "legacy-item",
                STABLE_ORG_ID,
                1,
                "owner",
                "Legacy",
                "secret",
                "t",
                1,
                1,
                &[3u8; 32],
                Some("document"),
                Some("owner"),
                None,
            )
            .unwrap();
    }

    #[test]
    fn legacy_tombstone_unrouted_404_fails_closed() {
        use std::io::Write;
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            for expected in ["DELETE", "GET"] {
                let (mut socket, _) = accept_with_timeout(&listener);
                let request = String::from_utf8_lossy(&read_http_request(&mut socket)).to_string();
                assert!(request.starts_with(expected));
                write!(
                    socket,
                    "HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\nconnection: close\r\n\r\n"
                )
                .unwrap();
            }
        });
        let state = build_state("legacy-tombstone-unrouted");
        seed_legacy_revoke_share(&state, &format!("http://{addr}/"));
        assert!(block_on(revoke_org_share_inner(&state, "legacy-item".into())).is_err());
        server.join().unwrap();
        assert_eq!(
            state.db.get_org_share("legacy-row").unwrap().unwrap().state,
            "revoke_pending"
        );
        assert!(state.db.get_org_item("legacy-item").unwrap().is_some());
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_item_tombstone_404_read")
                .unwrap(),
            1
        );
    }

    #[test]
    fn legacy_tombstone_404_with_authenticated_tombstone_completes() {
        use std::io::Write;
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut delete, _) = accept_with_timeout(&listener);
            let _ = read_http_request(&mut delete);
            write!(
                delete,
                "HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\nconnection: close\r\n\r\n"
            )
            .unwrap();
            let (mut get, _) = accept_with_timeout(&listener);
            let _ = read_http_request(&mut get);
            let body = "{\"items\":[{\"itemId\":\"legacy-item\",\"seq\":1,\"authorUserId\":\"owner\",\"rev\":1,\"generation\":1,\"createdAt\":\"t\",\"tombstoned\":true,\"isCurrent\":false}],\"nextSeq\":1}";
            write!(get,"HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",body.len(),body).unwrap();
        });
        let state = build_state("legacy-tombstone-corroborated");
        seed_legacy_revoke_share(&state, &format!("http://{addr}/"));
        block_on(revoke_org_share_inner(&state, "legacy-item".into())).unwrap();
        server.join().unwrap();
        assert_eq!(
            state.db.get_org_share("legacy-row").unwrap().unwrap().state,
            "revoked"
        );
        assert!(state.db.get_org_item("legacy-item").unwrap().is_none());
    }

    /// ITEM 4 — `list_org_shares` takes the caller's chosen org. Pre-fix it ignored the caller and
    /// returned `list_org_states().next()` — the FIRST local org — so in a shipped MULTI-org app a
    /// member of two orgs saw the wrong org's share list. An unknown org id returns EMPTY rather than
    /// silently falling back.
    #[test]
    fn list_org_shares_is_scoped_to_the_requested_org() {
        let state = build_state("org-shares-scoped");
        seed_org_at(
            &state.db,
            "org-a",
            "Alpha",
            "member",
            "2026-07-01T00:00:00Z",
        );
        seed_org_at(&state.db, "org-b", "Beta", "member", "2026-07-02T00:00:00Z");
        make_open_folder(&state.db, "f-shares", "Shares");
        state
            .db
            .insert_note("n-a", "f-shares", "n-a", "Alpha note", "body", 1)
            .unwrap();
        state
            .db
            .insert_note("n-b", "f-shares", "n-b", "Beta note", "body", 2)
            .unwrap();
        state
            .db
            .insert_org_share(
                "os-a",
                "org-a",
                None,
                Some("n-a"),
                "note",
                Some("Alpha note"),
                1,
                1,
                &[1u8; 32],
                "2026-07-11T00:00:00Z",
            )
            .unwrap();
        state
            .db
            .insert_org_share(
                "os-b",
                "org-b",
                None,
                Some("n-b"),
                "note",
                Some("Beta note"),
                1,
                1,
                &[2u8; 32],
                "2026-07-11T00:00:00Z",
            )
            .unwrap();

        let alpha = list_org_shares_inner(&state, "org-a").unwrap();
        assert_eq!(alpha.len(), 1);
        assert_eq!(alpha[0].title.as_deref(), Some("Alpha note"));

        // The SECOND org — the one the pre-fix `.next()` could never reach.
        let beta = list_org_shares_inner(&state, "org-b").unwrap();
        assert_eq!(beta.len(), 1);
        assert_eq!(beta[0].title.as_deref(), Some("Beta note"));

        assert!(
            list_org_shares_inner(&state, "org-unknown")
                .unwrap()
                .is_empty(),
            "an unjoined org id returns EMPTY, never another org's shares"
        );
    }

    /// Direct IPC helpers must not reveal outbound org-share titles/status for a sealed source.
    /// Session unlock restores both views without mutating the durable share row.
    #[test]
    fn org_share_reads_hide_sealed_source_and_restore_on_session_unlock() {
        let state = build_state("org-share-read-gate");
        seed_org(&state.db, "org-1", "Acme", "member", 1);
        make_open_folder(&state.db, "f-secret", "Secret");
        state
            .db
            .insert_note(
                "secret-note",
                "f-secret",
                "secret-note",
                "Classified roadmap",
                "body",
                1,
            )
            .unwrap();
        state
            .db
            .insert_org_share(
                "share-secret",
                "org-1",
                None,
                Some("secret-note"),
                "note",
                Some("Classified roadmap"),
                1,
                1,
                &[1u8; 32],
                "2026-08-12T00:00:00Z",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("share-secret", "item-secret", "2026-08-12T00:00:01Z")
            .unwrap();
        state.db.set_folder_locked("f-secret", true, None).unwrap();

        assert!(list_org_shares_inner(&state, "org-1").unwrap().is_empty());
        assert!(
            org_live_shares_for_source_inner(&state, None, Some("secret-note"))
                .unwrap()
                .is_empty()
        );

        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert("f-secret".into());
        let listed = list_org_shares_inner(&state, "org-1").unwrap();
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].title.as_deref(), Some("Classified roadmap"));
        let status = org_live_shares_for_source_inner(&state, None, Some("secret-note")).unwrap();
        assert_eq!(status.len(), 1);
        assert_eq!(status[0].item_id.as_deref(), Some("item-secret"));
    }

    /// Permission management may be launched from the origin share card after a collaborator has
    /// superseded its `item_id`. Resolve the current stable document and refresh every live local
    /// revision without rewriting the origin row's rev/item/hash CAS witness.
    #[test]
    fn org_set_item_access_from_stale_origin_updates_all_live_document_revisions() {
        use std::io::Write;

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut socket, _) = accept_with_timeout(&listener);
            let request_bytes = read_http_request(&mut socket);
            let request = String::from_utf8_lossy(&request_bytes);
            assert!(
                request.starts_with(&format!(
                    "PATCH /v1/orgs/{STABLE_ORG_ID}/documents/{STABLE_DOC_ID}"
                )),
                "permission update targeted the wrong resource: {}",
                request.lines().next().unwrap_or("")
            );
            let body = format!(
                r#"{{"docId":"{STABLE_DOC_ID}","access":"view","documentOwnerUserId":"c534b6d2-02c1-4c2c-a256-3af8592b1567"}}"#
            );
            let response = format!(
                                "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                                body.len(),
                                body
                            );
            socket.write_all(response.as_bytes()).unwrap();
        });

        let state = build_state("org-access-stale-origin");
        seed_org(&state.db, STABLE_ORG_ID, "Acme", "owner", 1);
        seed_live_session(&state);
        state.config.lock().unwrap().share_base_url = format!("http://{addr}");
        state
            .db
            .insert_org_share(
                "share-1",
                STABLE_ORG_ID,
                None,
                Some("local-note"),
                "note",
                Some("Local"),
                1,
                1,
                &[1u8; 32],
                "2026-08-12T00:00:00Z",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("share-1", "origin-old", "2026-08-12T00:00:01Z")
            .unwrap();
        state
            .db
            .set_org_share_document_metadata("share-1", STABLE_DOC_ID, "edit")
            .unwrap();

        for (item_id, seq, rev) in [
            ("origin-old", 1, 1),
            ("remote-current", 2, 2),
            ("remote-duplicate", 3, 3),
        ] {
            state
                .db
                .upsert_org_item(
                    item_id,
                    STABLE_ORG_ID,
                    seq,
                    "owner",
                    item_id,
                    "body",
                    "2026-08-12T00:00:00Z",
                    rev,
                    1,
                    &[rev as u8; 32],
                    None,
                    Some("editor"),
                    None,
                )
                .unwrap();
            state
                .db
                .set_org_item_document_metadata(
                    item_id,
                    Some(STABLE_DOC_ID),
                    "edit",
                    Some("c534b6d2-02c1-4c2c-a256-3af8592b1567"),
                )
                .unwrap();
        }
        state
            .db
            .repair_org_reconcile_metadata(
                "remote-current",
                STABLE_ORG_ID,
                1,
                Some(STABLE_DOC_ID),
                "edit",
                Some("c534b6d2-02c1-4c2c-a256-3af8592b1567"),
                true,
            )
            .unwrap();
        state.db.evict_org_item("origin-old").unwrap();

        let refused = block_on(org_set_item_access_inner(
            &state,
            "origin-old",
            crate::share::org_dto::OrgItemAccess::View,
        ));
        assert!(
            matches!(refused, Err(AppError::Unavailable(message)) if message.starts_with("[org-consent] "))
        );
        state.config.lock().unwrap().org_egress_consented = true;

        block_on(org_set_item_access_inner(
            &state,
            "origin-old",
            crate::share::org_dto::OrgItemAccess::View,
        ))
        .unwrap();
        server.join().unwrap();

        let live: Vec<(String, String, Option<String>)> = {
            let conn = state.db.lock();
            let mut stmt = conn
                .prepare(
                    "SELECT item_id, access, document_owner_user_id FROM org_items
                                      WHERE org_id = ?1 AND doc_id = ?2 AND tombstoned = 0
                                      ORDER BY item_id",
                )
                .unwrap();
            stmt.query_map(rusqlite::params![STABLE_ORG_ID, STABLE_DOC_ID], |row| {
                Ok((row.get(0)?, row.get(1)?, row.get(2)?))
            })
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap()
        };
        assert_eq!(live.len(), 2);
        assert!(live.iter().all(|(_, access, owner)| {
            access == "view" && owner.as_deref() == Some("c534b6d2-02c1-4c2c-a256-3af8592b1567")
        }));
        let share = state.db.get_org_share("share-1").unwrap().unwrap();
        assert_eq!(share.access, "view");
        assert_eq!(share.item_id.as_deref(), Some("origin-old"));
        assert_eq!(
            share.rev, 1,
            "permission PATCH must not advance the CAS witness"
        );
        assert_eq!(share.content_sha256, Some(vec![1u8; 32]));
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_share_access")
                .unwrap(),
            1
        );
    }

    #[test]
    fn org_set_item_access_rejects_wrong_access_or_owner_without_success_mutation() {
        use std::io::Write;

        for (case, response_access, response_owner) in [
            (
                "wrong-access",
                "edit",
                "c534b6d2-02c1-4c2c-a256-3af8592b1567",
            ),
            (
                "wrong-owner",
                "view",
                "11111111-1111-4111-8111-111111111111",
            ),
        ] {
            let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
            let addr = listener.local_addr().unwrap();
            let server = std::thread::spawn(move || {
                let (mut socket, _) = accept_with_timeout(&listener);
                let request = read_http_request(&mut socket);
                assert!(String::from_utf8_lossy(&request).starts_with(&format!(
                    "PATCH /v1/orgs/{STABLE_ORG_ID}/documents/{STABLE_DOC_ID}"
                )));
                let body = format!(
                        "{{\"docId\":\"{STABLE_DOC_ID}\",\"access\":\"{response_access}\",\"documentOwnerUserId\":\"{response_owner}\"}}"
                    );
                write!(
                        socket,
                        "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                        body.len(), body
                    )
                    .unwrap();
            });
            let state = build_state(&format!("org-access-{case}"));
            seed_editable_stable_org_item(&state, "item-old", "edit");
            state.config.lock().unwrap().share_base_url = format!("http://{addr}/");
            let result = block_on(org_set_item_access_inner(
                &state,
                "item-old",
                crate::share::org_dto::OrgItemAccess::View,
            ));
            server.join().unwrap();
            assert!(matches!(result, Err(AppError::Unavailable(_))));
            assert_eq!(
                state.db.get_org_item("item-old").unwrap().unwrap().access,
                "edit"
            );
            assert_eq!(
                state
                    .db
                    .count_share_egress_by_kind("org_share_access")
                    .unwrap(),
                1
            );
        }
    }

    #[test]
    fn org_access_is_single_flight_and_restart_reconciles_authoritative_access() {
        let state = build_state("org-access-response-reorder");
        seed_editable_stable_org_item(&state, "item-old", "edit");
        state
            .db
            .insert_org_share(
                "share-access",
                STABLE_ORG_ID,
                None,
                Some("source"),
                "note",
                Some("Draft"),
                1,
                1,
                &[1u8; 32],
                "t",
            )
            .unwrap();
        state
            .db
            .set_org_share_uploaded("share-access", "item-old", "t")
            .unwrap();
        state
            .db
            .set_org_share_document_metadata("share-access", STABLE_DOC_ID, "edit")
            .unwrap();
        let actor = "c534b6d2-02c1-4c2c-a256-3af8592b1567";
        state.config.lock().unwrap().org_egress_consented = true;
        let (_permit, dispatch_id) = permit_org_access(
            &state,
            "relay.example",
            STABLE_ORG_ID,
            STABLE_DOC_ID,
            crate::share::org_dto::OrgItemAccess::View,
            crate::share::org_dto::OrgItemAccess::Edit,
            actor,
            actor,
        )
        .unwrap();
        assert!(matches!(
            permit_org_access(
                &state,
                "relay.example",
                STABLE_ORG_ID,
                STABLE_DOC_ID,
                crate::share::org_dto::OrgItemAccess::View,
                crate::share::org_dto::OrgItemAccess::Edit,
                actor,
                actor,
            ),
            Err(AppError::Unavailable(_))
        ));
        assert_eq!(
            state
                .db
                .count_share_egress_by_kind("org_share_access")
                .unwrap(),
            1
        );
        assert_eq!(
            state.db.get_org_item("item-old").unwrap().unwrap().access,
            "edit"
        );
        let attempt = pending_org_access_attempts(&state).unwrap().remove(0);
        assert_eq!(attempt.dispatch_id, dispatch_id);
        let head: crate::share::org_dto::OrgItemEntry = serde_json::from_value(serde_json::json!({
            "itemId":"item-old","seq":1,"authorUserId":actor,"rev":1,"generation":1,
            "createdAt":"t","tombstoned":false,"docId":STABLE_DOC_ID,"access":"view",
            "documentOwnerUserId":actor,"isCurrent":true
        }))
        .unwrap();
        state
            .db
            .lock()
            .execute(
                "UPDATE org_shares SET state='failed',last_error='direct_put_pending'
                  WHERE org_id=?1 AND doc_id=?2",
                rusqlite::params![STABLE_ORG_ID, STABLE_DOC_ID],
            )
            .unwrap();
        assert!(!apply_authoritative_org_access(&state, &attempt, &head).unwrap());
        assert_eq!(
            state.db.get_org_item("item-old").unwrap().unwrap().access,
            "edit"
        );
        assert_eq!(pending_org_access_attempts(&state).unwrap().len(), 1);
        state
            .db
            .lock()
            .execute(
                "UPDATE org_shares SET state='uploaded',last_error=NULL
                  WHERE org_id=?1 AND doc_id=?2",
                rusqlite::params![STABLE_ORG_ID, STABLE_DOC_ID],
            )
            .unwrap();
        assert!(apply_authoritative_org_access(&state, &attempt, &head).unwrap());
        assert_eq!(
            state.db.get_org_item("item-old").unwrap().unwrap().access,
            "view"
        );
        assert!(pending_org_access_attempts(&state).unwrap().is_empty());
    }

