    #[test]
    fn org_dispatch_permits_reject_same_length_ciphertext_substitution() {
        let host = "relay.example";
        let org_id = STABLE_ORG_ID;
        let doc_id = STABLE_DOC_ID;
        let original_cell = vec![1u8, 2, 3, 4];
        let substituted_cell = vec![4u8, 3, 2, 1];
        let semantic_sha = vec![9u8; 32];
        let publish_request = crate::share::org_dto::PublishItemRequest {
            mutation_id: None,
            doc_id: Some(doc_id.to_string()),
            access: Some(crate::share::org_dto::OrgItemAccess::View),
            blob_id: None,
            content_cell: Some(original_cell.clone()),
            content_sha256: semantic_sha.clone(),
            rev: 1,
            generation: 1,
        };
        let publish_permit =
            test_org_publish_dispatch_permit(host, org_id, &publish_request, Some("owner"));
        let mut substituted_publish = publish_request;
        substituted_publish.content_cell = Some(substituted_cell.clone());
        assert!(matches!(
            publish_permit.authorize_publish(host, org_id, &substituted_publish),
            Err(AppError::Storage(message)) if message == "org publish dispatch permit mismatch"
        ));

        let original_update = crate::share::org_dto::UpdateOrgItemRequest {
            mutation_id: None,
            expected_rev: 1,
            content_cell: original_cell,
            content_sha256: semantic_sha.clone(),
            generation: 1,
        };
        let update_permit = test_org_update_dispatch_permit(
            host,
            org_id,
            doc_id,
            crate::share::org_dto::OrgItemAccess::Edit,
            "owner",
            &original_update,
        );
        let substituted_update = crate::share::org_dto::UpdateOrgItemRequest {
            mutation_id: None,
            expected_rev: 1,
            content_cell: substituted_cell,
            content_sha256: semantic_sha,
            generation: 1,
        };
        assert!(matches!(
            update_permit.authorize_update(host, org_id, doc_id, &substituted_update),
            Err(AppError::Storage(message)) if message == "org update dispatch permit mismatch"
        ));
    }

    /// Adoption does not change how a note container RENAMES — proven through the real rename entry
    /// point, on the vault, rather than asserted from the composition rule.
    ///
    /// This is the hazard the whole migration design exists to avoid, so it is not enough to reason
    /// that `rename_folder_inner` treats an empty parent path like no parent at all. A note container
    /// whose stored path cannot be composed from any note root is adopted by the project, whose path
    /// is the vault root; if that changed what a later rename does, the real directory would move
    /// while `notes.exported_path` / `documents.exported_path` stayed behind — and a later seal would
    /// then delete an `.md` at a path that no longer exists, leaving the plaintext inside a folder the
    /// app reports as sealed. Both databases are renamed identically and compared.
    #[test]
    fn adoption_does_not_change_how_a_note_container_renames() {
        fn rename_uncomposable(tag: &str, adopt: bool) -> (String, std::path::PathBuf) {
            let vault = tmp_vault(tag);
            let state = build_state_with_vault(tag, &vault);
            // Model a pre-hierarchy database: opening one adopts it, so undo that first.
            state
                .db
                .lock()
                .execute(
                    "DELETE FROM folders WHERE COALESCE(level, 'folder') = 'project'",
                    rusqlite::params![],
                )
                .unwrap();
            // A note container stamped two levels under a root while its parent link stays NULL —
            // the shape `create_note_folder_inner` produces and no root can compose.
            state
                .db
                .insert_folder(&Folder {
                    id: "c-deep".into(),
                    name: "Deep".into(),
                    path: "Notes/Mid/Deep".into(),
                    parent_id: None,
                    locked: false,
                    created_at: "2026-08-22T09:00:00Z".into(),
                })
                .unwrap();
            state
                .db
                .lock()
                .execute(
                    "UPDATE folders SET kind = 'note' WHERE id = 'c-deep'",
                    rusqlite::params![],
                )
                .unwrap();
            std::fs::create_dir_all(vault.join("Notes/Mid/Deep")).unwrap();

            if adopt {
                Db::migrate_hierarchy_v1(&state.db.lock()).unwrap();
            }
            rename_folder_inner(&state, "c-deep".into(), "Renamed".into()).unwrap();
            let path: String = state
                .db
                .lock()
                .query_row("SELECT path FROM folders WHERE id = 'c-deep'", [], |r| {
                    r.get(0)
                })
                .unwrap();
            (path, vault)
        }

        let (before, vault_before) = rename_uncomposable("rename-unadopted", false);
        let (after, vault_after) = rename_uncomposable("rename-adopted", true);
        assert_eq!(
            before, after,
            "adoption changed where a rename puts a note container's directory"
        );
        // And the directory really landed there in BOTH vaults — comparing two `exists()` calls would
        // also pass if neither directory existed at all.
        assert!(
            vault_before.join(&before).is_dir(),
            "the un-adopted rename did not create {before}"
        );
        assert!(
            vault_after.join(&after).is_dir(),
            "the adopted rename did not create {after}"
        );
        assert!(
            !vault_before.join("Notes/Mid/Deep").exists(),
            "the un-adopted rename left the old directory behind"
        );
        assert!(
            !vault_after.join("Notes/Mid/Deep").exists(),
            "the adopted rename left the old directory behind"
        );
    }

    /// Sealing a project reaches its own items only, never the containers beneath it.
    ///
    /// The hierarchy gives containers parents for the first time, so this pins that a lock is still
    /// exactly as wide as it was: per container, never recursive. (Making a project lock cascade to
    /// its children is a later, deliberate step — this proves it does not happen by accident here.)
    #[test]
    fn sealing_a_project_reaches_its_own_items_only() {
        let state = build_state("project-seal-scope");
        // The database adopts on open, so the project already exists; give it a child and one item
        // each, then seal the project.
        let project: String = state
            .db
            .lock()
            .query_row(
                "SELECT id FROM folders WHERE COALESCE(level, 'folder') = 'project' AND path = ''",
                [],
                |r| r.get(0),
            )
            .unwrap();
        make_child_folder(&state.db, "f-work", "Work", "Work", &project);
        seed_meeting(&state.db, "m-project", "# project note", Some(&project));
        seed_meeting(&state.db, "m-work", "# work note", Some("f-work"));

        lock_folder_inner(&state, project.clone()).unwrap();

        assert!(
            !meeting_is_unlocked(&state, "m-project").unwrap(),
            "the project's own item is sealed"
        );
        assert!(
            meeting_is_unlocked(&state, "m-work").unwrap(),
            "a container beneath it is untouched — a lock is per container, never recursive"
        );
    }

    /// Renaming or deleting the workspace root is refused.
    ///
    /// The hierarchy gives the default project `path = ''`, and every folder command composes its
    /// filesystem work from `folders.path`. `assert_in_vault` resolves an empty relative path to the
    /// vault root — the property that lets the migration adopt every container without moving a file
    /// — so without this refusal a rename would compose `fs::rename(<vault>, <vault>/<new name>)` and
    /// move the user's ENTIRE vault. No shipped row had an empty path before, so the refusal ships
    /// with the row that makes it reachable.
    #[test]
    fn the_workspace_root_cannot_be_renamed_or_deleted() {
        let vault = tmp_vault("workspace-root-guard");
        let state = build_state_with_vault("workspace-root-guard", &vault);
        make_open_folder(&state.db, "f-work", "Work");
        std::fs::create_dir_all(vault.join("Work")).unwrap();
        Db::migrate_hierarchy_v1(&state.db.lock()).unwrap();

        let project: String = state
            .db
            .lock()
            .query_row(
                "SELECT id FROM folders WHERE COALESCE(level, 'folder') = 'project'",
                [],
                |r| r.get(0),
            )
            .unwrap();

        let err = rename_folder_inner(&state, project.clone(), "Renamed".into())
            .expect_err("renaming the workspace root must be refused");
        assert!(matches!(err, AppError::InvalidArg(_)), "got {err:?}");
        let err = delete_folder_inner(&state, project.clone())
            .expect_err("deleting the workspace root must be refused");
        assert!(matches!(err, AppError::InvalidArg(_)), "got {err:?}");

        // The vault is intact and the project row is unchanged.
        assert!(vault.join("Work").is_dir(), "the vault was disturbed");
        assert!(!vault.join("Renamed").exists());
        let path: String = state
            .db
            .lock()
            .query_row(
                "SELECT path FROM folders WHERE id = ?1",
                rusqlite::params![project],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(path, "");

        // An ordinary container still renames exactly as before.
        rename_folder_inner(&state, "f-work".into(), "Ops".into()).unwrap();
        assert!(vault.join("Ops").is_dir());
    }

    /// On an ADOPTED database the reserved note root still resolves and still cannot be sealed.
    ///
    /// Adoption gives that root a non-NULL parent for the first time. The invariant it exists to
    /// protect — that creating a note always has a writable, never-sealed home — is checked here
    /// through the real resolver and the real seal refusal, not through its flag.
    #[test]
    fn the_note_root_still_resolves_and_still_refuses_to_seal_after_adoption() {
        let state = build_state("adopted-note-root");
        // The real upgrade path: an existing user already HAS a note root, and adoption then gives it
        // a parent. (A root created AFTER adoption keeps a NULL parent, because the completion guard
        // short-circuits — containers created post-adoption get their parent from the creation call
        // instead. Defaulting that parent to the workspace project belongs to the creation-guards
        // step, which is where the tree first has a consumer.)
        state
            .db
            .lock()
            .execute(
                "DELETE FROM folders WHERE COALESCE(level, 'folder') = 'project'",
                rusqlite::params![],
            )
            .unwrap();
        let root_before = state.db.ensure_notes_root().unwrap();
        Db::migrate_hierarchy_v1(&state.db.lock()).unwrap();

        let parent: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT parent_id FROM folders WHERE id = ?1",
                rusqlite::params![root_before],
                |r| r.get(0),
            )
            .unwrap();
        assert!(
            parent.is_some(),
            "adoption gives the note root a parent — that is the new condition under test"
        );

        // The resolver still finds the SAME root rather than minting a second one.
        let root_after = state.db.ensure_notes_root().unwrap();
        assert_eq!(root_after, root_before, "a second note root was created");

        // And sealing it is still refused, so note creation never dead-ends.
        let err = lock_folder_inner(&state, root_after.clone())
            .expect_err("the note root must still refuse to seal");
        assert!(matches!(err, AppError::InvalidArg(_)), "got {err:?}");
    }

    /// No shipped creation path can produce a container whose path is the vault root.
    ///
    /// The migration declines to adopt when the vault root is occupied, and the legacy-tree shim
    /// hides project rows — so if a user COULD create a container there, they could put their own
    /// database into the declined state. This drives BOTH shipped creation entry points rather than
    /// their shared name sanitiser: a path that stopped calling the sanitiser, or gained its own
    /// composition, would leave a sanitiser-only assertion green.
    #[test]
    fn no_creation_path_can_produce_a_vault_root_container() {
        let vault = tmp_vault("no-empty-path");
        let state = build_state_with_vault("no-empty-path", &vault);

        for name in ["", "   ", "...", "/", "///", "\u{0}", ".", " . "] {
            assert!(
                create_folder_inner(&state, name.to_string(), None).is_err(),
                "the meeting-side create accepted {name:?}"
            );
            assert!(
                create_note_folder_inner(&state, name, None).is_err(),
                "the note-side create accepted {name:?}"
            );
        }

        // Controls: an ordinary name succeeds on both paths, and neither lands at the vault root.
        let meeting_side = create_folder_inner(&state, "Work".into(), None).unwrap();
        assert!(!meeting_side.path.is_empty());
        let note_side = create_note_folder_inner(&state, "Research", None).unwrap();
        assert!(!note_side.path.is_empty());

        // And nothing in the database occupies the vault root except the project the migration made.
        let at_root: Vec<String> = {
            let conn = state.db.lock();
            let mut stmt = conn
                .prepare("SELECT COALESCE(level, 'folder') FROM folders WHERE path = ''")
                .unwrap();
            let rows = stmt.query_map([], |r| r.get::<_, String>(0)).unwrap();
            rows.map(|r| r.unwrap()).collect()
        };
        assert_eq!(at_root, vec!["project".to_string()]);
    }

    /// Resolving the vault root BY PATH after adoption returns the project — stated, because it
    /// returned nothing on every database before this change.
    ///
    /// It matters for the by-path resolvers: the auto-file classifier maps a model-chosen subfolder
    /// name to a container this way. The name it can produce is sanitised, and the sanitiser refuses
    /// anything empty, so the classifier cannot address the project — but that is now a property
    /// worth asserting rather than assuming.
    #[test]
    fn the_vault_root_resolves_by_path_only_to_the_project() {
        let state = build_state("vault-root-by-path");
        let project: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT id FROM folders WHERE COALESCE(level, 'folder') = 'project' AND path = ''",
                [],
                |r| r.get(0),
            )
            .ok();
        assert!(project.is_some(), "the database is adopted");

        let by_path = state.db.folder_by_path("").unwrap();
        assert_eq!(
            by_path.map(|f| f.id),
            project,
            "the empty path resolves to the workspace project and nothing else"
        );
        // The classifier's own vocabulary cannot name it.
        assert!(crate::summarize::organize::sanitize_folder("").is_none());
    }

    /// A genuinely sealed container survives adoption gated, unlockable, and byte-identical.
    ///
    /// Comparing the `locked` and `wrapped_key` columns before and after only shows the migration did
    /// not overwrite them. It cannot show that a REAL seal still opens afterwards, which is the
    /// property that matters: the content is only recoverable through the key those columns describe.
    /// So this seals through the ordinary lock path with real key material, migrates, checks the gate,
    /// then permanently unseals and compares the markdown byte for byte.
    #[test]
    fn a_real_seal_survives_adoption_and_still_unseals_byte_identical() {
        let state = build_state("sealed-through-adoption");
        // Model a pre-hierarchy database, seal a container with content in it, THEN adopt.
        state
            .db
            .lock()
            .execute(
                "DELETE FROM folders WHERE COALESCE(level, 'folder') = 'project'",
                rusqlite::params![],
            )
            .unwrap();
        make_open_folder(&state.db, "f-legal", "Legal");
        let markdown = "# Merger terms\n\nAcquire at 3.2x revenue.\n";
        seed_meeting(&state.db, "m1", markdown, Some("f-legal"));

        lock_folder_inner(&state, "f-legal".into()).unwrap();
        assert!(
            !meeting_is_unlocked(&state, "m1").unwrap(),
            "sealed before adoption"
        );

        Db::migrate_hierarchy_v1(&state.db.lock()).unwrap();

        // Adopted, and still sealed — the gate reads the per-row flag, which adoption never writes.
        let parent: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT parent_id FROM folders WHERE id = 'f-legal'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(parent.is_some(), "it was adopted");
        assert!(
            !meeting_is_unlocked(&state, "m1").unwrap(),
            "still sealed after adoption"
        );

        // And the real key still opens it, returning exactly what went in.
        remove_lock_inner(&state, "f-legal".to_string()).unwrap();
        assert!(meeting_is_unlocked(&state, "m1").unwrap());
        let restored = state
            .db
            .get_latest_note_for_meeting("m1")
            .unwrap()
            .expect("the note is back");
        assert_eq!(
            restored.markdown, markdown,
            "content did not survive seal -> adopt -> unseal byte-identical"
        );
    }

    /// The vault-root refusal covers a DECLINED-ADOPTION occupant too, not only the created project.
    ///
    /// The hazard is the path, not the row: every folder command composes its filesystem work from
    /// `folders.path`, and an empty one resolves to the vault root — so renaming it means "move the
    /// vault into a subdirectory of itself" and deleting it targets the vault directory, whichever row
    /// happens to sit there. Narrowing the refusal to the migration's own project would leave both
    /// operations reachable on exactly the database where the migration declined to adopt BECAUSE
    /// such a container was present.
    #[test]
    fn the_vault_root_refusal_covers_a_declined_adoption_occupant() {
        let vault = tmp_vault("declined-occupant");
        let state = build_state_with_vault("declined-occupant", &vault);
        state
            .db
            .lock()
            .execute(
                "DELETE FROM folders WHERE COALESCE(level, 'folder') = 'project'",
                rusqlite::params![],
            )
            .unwrap();
        // A container occupying the vault root, the shape only an import or a manual edit produces.
        make_open_folder(&state.db, "f-root", "");
        make_open_folder(&state.db, "f-work", "Work");
        std::fs::create_dir_all(vault.join("Work")).unwrap();

        Db::migrate_hierarchy_v1(&state.db.lock()).unwrap();
        assert!(
            state
                .db
                .lock()
                .query_row(
                    "SELECT EXISTS(SELECT 1 FROM folders WHERE COALESCE(level,'folder') = 'project')",
                    [],
                    |r| r.get::<_, i64>(0)
                )
                .unwrap()
                == 0,
            "adoption declined, which is the state under test"
        );

        // The occupant is NOT the project, and is still refused.
        let err = rename_folder_inner(&state, "f-root".into(), "Renamed".into())
            .expect_err("renaming a vault-root container must be refused");
        assert!(matches!(err, AppError::InvalidArg(_)), "got {err:?}");
        let err = delete_folder_inner(&state, "f-root".into())
            .expect_err("deleting a vault-root container must be refused");
        assert!(matches!(err, AppError::InvalidArg(_)), "got {err:?}");

        // The vault is intact: nothing moved, nothing removed.
        assert!(vault.join("Work").is_dir());
        assert!(!vault.join("Renamed").exists());
        assert!(vault.is_dir());

        // And an ordinary container on the same database still renames.
        rename_folder_inner(&state, "f-work".into(), "Ops".into()).unwrap();
        assert!(vault.join("Ops").is_dir());
    }

    // ── container-creation guards ───────────────────────────────────────────────────────────────
    //
    // Before the hierarchy, the shipped UI only ever created containers at the root, so none of the
    // three writers asked what a parent's seal meant for its child — and a child created under a
    // sealed parent was itself OPEN while its vault directory sat inside the sealed parent's. Under
    // Projects › Folders that is the ordinary way a folder is made.

    #[test]
    fn authored_notes_and_note_folders_can_live_under_a_mixed_space() {
        let state = build_state("mixed-space-note-content");
        make_open_folder(&state.db, "space", "Product");

        let note_id = create_note_inner(&state, Some("space"), "Brief").unwrap();
        assert_eq!(
            state.db.get_note_row(&note_id).unwrap().unwrap().folder_id,
            "space"
        );

        let child = create_note_folder_inner(&state, "Research", Some("space")).unwrap();
        assert_eq!(child.parent_id.as_deref(), Some("space"));
        assert_eq!(child.path, "Product/Research");
    }

    /// Session-unlock a sealed container, the way a successful Touch ID unlock leaves it.
    /// Put a folder in the state a real session-unlock leaves it in.
    ///
    /// Membership of the unlocked set is only half of it: `unlock_folder` also CACHES the
    /// master KEK it released, and that cache is what lets later work in the same session
    /// proceed without another Touch ID. A fixture that set only the membership described a
    /// state the app never produces — session-unlocked with no key — and any code that
    /// depends on the key being there would look broken against it.
    fn mark_session_unlocked(state: &AppState, folder_id: &str) {
        state
            .unlocked_folders
            .lock()
            .unwrap()
            .insert(folder_id.to_string());
        let mut kek = state.master_kek.lock().unwrap();
        if kek.is_none() {
            *kek = Some(zeroize::Zeroizing::new(
                crate::secrets::master_kek_with_policy("test", true).unwrap(),
            ));
        }
    }

    /// Creating inside a sealed, NOT session-unlocked container is refused — and nothing is created,
    /// on disk or in the database.
    ///
    /// There is no key to seal the child with, so the alternatives would be to leave plaintext inside
    /// a sealed tree or to prompt for authorisation from a path the user did not initiate.
    #[test]
    fn creating_inside_a_sealed_container_is_refused() {
        let vault = tmp_vault("create-in-sealed");
        let state = build_state_with_vault("create-in-sealed", &vault);
        make_open_folder(&state.db, "f-legal", "Legal");
        std::fs::create_dir_all(vault.join("Legal")).unwrap();
        lock_folder_inner(&state, "f-legal".into()).unwrap();

        let err = create_folder_inner(&state, "Q3".into(), Some("f-legal".into()))
            .expect_err("the meeting-side create must refuse a sealed parent");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        // The note side resolves its parent through the note-folder namespace, so give it one.
        make_open_folder(&state.db, "f-notes-parent", "Notes/Team");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-notes-parent'",
                rusqlite::params![],
            )
            .unwrap();
        lock_folder_inner(&state, "f-notes-parent".into()).unwrap();
        let err = create_note_folder_inner(&state, "Drafts", Some("f-notes-parent"))
            .expect_err("the note-side create must refuse a sealed parent");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        // Nothing landed: no row, and no directory inside the sealed parents.
        let children: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM folders WHERE parent_id IN ('f-legal', 'f-notes-parent')",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(children, 0, "a container was created inside a sealed one");
        assert!(
            !vault.join("Legal/Q3").exists(),
            "a directory was created inside a sealed tree"
        );
        assert!(
            !vault.join("Notes/Team/Drafts").exists(),
            "a note-side directory was created inside a sealed tree"
        );
    }

    /// Creating inside a sealed but SESSION-UNLOCKED container succeeds, and the child is already
    /// sealed when the call returns.
    ///
    /// The key is available for this session, which is the only reason the caller may proceed at all,
    /// so no extra authorisation is required and none is asked for.
    #[test]
    fn a_container_created_inside_an_unlocked_sealed_parent_is_born_sealed() {
        let vault = tmp_vault("create-in-unlocked");
        let state = build_state_with_vault("create-in-unlocked", &vault);
        make_open_folder(&state.db, "f-legal", "Legal");
        std::fs::create_dir_all(vault.join("Legal")).unwrap();
        lock_folder_inner(&state, "f-legal".into()).unwrap();
        mark_session_unlocked(&state, "f-legal");

        let child = create_folder_inner(&state, "Q3".into(), Some("f-legal".into())).unwrap();
        let locked: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT locked FROM folders WHERE id = ?1",
                rusqlite::params![child.id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            locked, 1,
            "the child must be sealed by the time creation returns"
        );
        // Sealed through the ordinary path means it has a real wrapped key, not just a flag.
        let wrapped: Option<Vec<u8>> = state
            .db
            .lock()
            .query_row(
                "SELECT wrapped_key FROM folders WHERE id = ?1",
                rusqlite::params![child.id],
                |r| r.get(0),
            )
            .unwrap();
        assert!(wrapped.is_some(), "no content key was minted for the child");
    }

    /// Re-parenting a note container into a sealed, not-unlocked container is refused.
    #[test]
    fn moving_a_container_into_a_sealed_container_is_refused() {
        let vault = tmp_vault("move-into-sealed");
        let state = build_state_with_vault("move-into-sealed", &vault);
        let movable = create_note_folder_inner(&state, "Drafts", None).unwrap();
        make_open_folder(&state.db, "f-target", "Notes/Sealed");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-target'",
                rusqlite::params![],
            )
            .unwrap();
        lock_folder_inner(&state, "f-target".into()).unwrap();

        let err = move_note_folder_inner(&state, &movable.id, Some("f-target"))
            .expect_err("moving into a sealed container must be refused");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        // The exemption's SECOND case, which the creates treat differently: a sealed
        // destination that IS session-unlocked is still refused here. The two creates seal
        // an empty new container; a move relocates an existing subtree whose content is
        // cached by renderers and visible over MCP, and sealing that needs the revocation
        // machinery the project-lock cascade builds. Without this the refusal would read as
        // "not implemented yet" rather than a decision.
        mark_session_unlocked(&state, "f-target");
        let err = move_note_folder_inner(&state, &movable.id, Some("f-target"))
            .expect_err("a session-unlocked sealed destination is refused too");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        // And the mover itself is untouched.
        let parent: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT parent_id FROM folders WHERE id = ?1",
                rusqlite::params![movable.id],
                |r| r.get(0),
            )
            .unwrap();
        assert_ne!(parent.as_deref(), Some("f-target"));
    }

    /// A creation with no explicit parent lands in the workspace project, and its path is exactly
    /// what a root container receives today.
    ///
    /// The tree renders from the projects down, so a container left parentless would exist and be
    /// unreachable — taking every note inside it with it.
    #[test]
    fn a_parentless_creation_lands_in_the_workspace_project() {
        let vault = tmp_vault("parentless-creation");
        let state = build_state_with_vault("parentless-creation", &vault);
        let project = state.db.workspace_project_id().unwrap().expect("adopted");

        let meeting_side = create_folder_inner(&state, "Work".into(), None).unwrap();
        assert_eq!(meeting_side.parent_id.as_deref(), Some(project.as_str()));
        assert_eq!(
            meeting_side.path, "Work",
            "the workspace project is the vault root, so the path is unchanged"
        );

        let note_side = create_note_folder_inner(&state, "Research", None).unwrap();
        assert!(
            note_side.parent_id.is_some(),
            "a note container is never parentless either"
        );
        assert_eq!(
            note_side.path, "Notes/Research",
            "its path is unchanged too"
        );

        // Both are reachable from the project in the workspace tree.
        let unlocked = std::collections::HashSet::new();
        let forest = workspace_tree_inner(&state.db, &unlocked).unwrap();
        let ids: Vec<&str> = forest[0].folders.iter().map(|f| f.id.as_str()).collect();
        assert!(
            ids.contains(&meeting_side.id.as_str()),
            "meeting-side container unreachable: {ids:?}"
        );
    }

    /// A container that cannot be given a key is not created at all.
    ///
    /// No injection: this is the real condition. The born-sealed path uses the KEK cached by
    /// the parent's own unlock and never prompts — "Lock all" zeroizes that cache, and a
    /// creation is not an operation the user authorised a Touch ID for. So the honest answer
    /// is to refuse, and the oracle is that refusing leaves NOTHING behind.
    ///
    /// There is no partially-created state to hunt any more. The row is written already
    /// sealed, in one statement, and the vault directory is made after it — so a failure
    /// before that insert has nothing to undo, which is why this test can assert absence
    /// rather than cleanup.
    #[test]
    fn a_container_that_cannot_be_sealed_is_not_created() {
        let vault = tmp_vault("no-key-no-container");
        let state = build_state_with_vault("no-key-no-container", &vault);
        make_open_folder(&state.db, "f-legal", "Legal");
        std::fs::create_dir_all(vault.join("Legal")).unwrap();
        lock_folder_inner(&state, "f-legal".into()).unwrap();
        mark_session_unlocked(&state, "f-legal");

        // The parent stays session-unlocked while the KEK cache is gone — exactly what a
        // "Lock all" leaves behind for a folder the session set still names.
        *state.master_kek.lock().unwrap() = None;

        let err = create_folder_inner(&state, "Q3".into(), Some("f-legal".into()))
            .expect_err("a container with no key must not be created");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        make_open_folder(&state.db, "f-notes-parent", "Notes/Team");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-notes-parent'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join("Notes/Team")).unwrap();
        lock_folder_inner(&state, "f-notes-parent".into()).unwrap();
        mark_session_unlocked(&state, "f-notes-parent");
        *state.master_kek.lock().unwrap() = None;

        let err = create_note_folder_inner(&state, "Drafts", Some("f-notes-parent"))
            .expect_err("the note-side create must refuse too");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        let children: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM folders WHERE parent_id IN ('f-legal', 'f-notes-parent')",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(children, 0, "a container survived inside a sealed one");
        assert!(
            !vault.join("Legal/Q3").exists(),
            "a directory survived inside a sealed tree"
        );
        assert!(
            !vault.join("Notes/Team/Drafts").exists(),
            "a note-side directory survived inside a sealed tree"
        );
    }

    /// Both writers report the state the database actually holds, not the one built before sealing.
    ///
    /// The value returned is what the frontend renders and what a caller chains onto. Reporting a
    /// freshly born-sealed container as open is how a caller comes to export plaintext into it.
    #[test]
    fn a_born_sealed_container_reports_itself_locked_on_both_writers() {
        let vault = tmp_vault("born-sealed-dto");
        let state = build_state_with_vault("born-sealed-dto", &vault);
        make_open_folder(&state.db, "f-legal", "Legal");
        std::fs::create_dir_all(vault.join("Legal")).unwrap();
        lock_folder_inner(&state, "f-legal".into()).unwrap();
        mark_session_unlocked(&state, "f-legal");

        let child = create_folder_inner(&state, "Q3".into(), Some("f-legal".into())).unwrap();
        assert!(
            child.locked,
            "the meeting-side create reported an open container"
        );

        make_open_folder(&state.db, "f-notes-parent", "Notes/Team");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-notes-parent'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join("Notes/Team")).unwrap();
        lock_folder_inner(&state, "f-notes-parent".into()).unwrap();
        mark_session_unlocked(&state, "f-notes-parent");

        let note_child = create_note_folder_inner(&state, "Drafts", Some("f-notes-parent")).unwrap();
        assert!(
            note_child.locked,
            "the note-side create reported an open container"
        );
    }

    /// When "Notes" is occupied by a LOCKED container, a defaulted creation goes to the reserved
    /// root instead — and its path, its parent link and its directory all name that same container.
    ///
    /// This is the case the three separate decisions used to disagree on. The path came from the
    /// literal "Notes" and the parent from `ensure_default_note_folder`, which returns whatever row
    /// holds that path EVEN WHEN IT IS SEALED — so the child was created open, inside a sealed tree,
    /// with no gate having looked at it.
    #[test]
    fn a_defaulted_creation_never_lands_in_a_locked_notes_container() {
        let vault = tmp_vault("notes-occupied");
        let state = build_state_with_vault("notes-occupied", &vault);
        make_open_folder(&state.db, "f-notes-taken", "Notes");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-notes-taken'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join("Notes")).unwrap();
        lock_folder_inner(&state, "f-notes-taken".into()).unwrap();

        let child = create_note_folder_inner(&state, "Drafts", None).unwrap();

        assert!(
            !child.path.starts_with("Notes/"),
            "the child was placed inside the locked container: {}",
            child.path
        );
        assert!(
            !child.locked,
            "the reserved root is always open, so its children are too"
        );

        // The parent link names the reserved root, and the root's own path is the one the child was
        // composed from — the three agree.
        let root_id = child
            .parent_id
            .clone()
            .expect("a defaulted creation is never parentless");
        let (root_path, is_root, root_locked): (String, i64, i64) = state
            .db
            .lock()
            .query_row(
                "SELECT path, COALESCE(is_root, 0), locked FROM folders WHERE id = ?1",
                rusqlite::params![root_id],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        assert_eq!(is_root, 1, "the parent must be the reserved note root");
        assert_eq!(root_locked, 0, "the reserved note root is never sealed");
        assert_eq!(
            child.path,
            format!("{root_path}/Drafts"),
            "the path was composed from a different container than the parent link names"
        );
        assert!(
            vault.join(&child.path).is_dir(),
            "no directory at the recorded path: {}",
            child.path
        );
        assert!(
            !vault.join("Notes/Drafts").exists(),
            "a plaintext directory was created inside the sealed container"
        );

        // And that root is inside the project, so the notes it holds stay reachable.
        let root_parent: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT parent_id FROM folders WHERE id = ?1",
                rusqlite::params![root_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            root_parent,
            state.db.workspace_project_id().unwrap(),
            "the relocated note root must still be adopted"
        );
    }

    /// Moving a container to "no parent" resolves the same reserved root the creates do, gates it,
    /// and writes it — it never blanks the parent link and never targets a locked "Notes".
    ///
    /// The move is the third writer, and it had both halves of the create's defect: the destination
    /// path came from the literal "Notes" while `ensure_default_note_folder` decided the link, and the
    /// seal check ran only for an explicit destination. It also passed the caller's `None` straight
    /// into the re-parent, which blanks `parent_id` — leaving a container the tree cannot reach.
    #[test]
    fn moving_a_container_to_no_parent_lands_in_the_reserved_root() {
        let vault = tmp_vault("move-to-default");
        let state = build_state_with_vault("move-to-default", &vault);

        // "Notes" is occupied by a LOCKED container, so the reserved root is elsewhere.
        make_open_folder(&state.db, "f-notes-taken", "Notes");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-notes-taken'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join("Notes")).unwrap();
        lock_folder_inner(&state, "f-notes-taken".into()).unwrap();

        let root_id = state.db.ensure_notes_root().unwrap();
        let root_path: String = state
            .db
            .lock()
            .query_row(
                "SELECT path FROM folders WHERE id = ?1",
                rusqlite::params![root_id],
                |r| r.get(0),
            )
            .unwrap();

        // A container nested one level down, then moved back out to "no parent".
        let outer = create_note_folder_inner(&state, "Outer", None).unwrap();
        let inner = create_note_folder_inner(&state, "Inner", Some(&outer.id)).unwrap();
        move_note_folder_inner(&state, &inner.id, None).unwrap();

        let (path, parent): (String, Option<String>) = state
            .db
            .lock()
            .query_row(
                "SELECT path, parent_id FROM folders WHERE id = ?1",
                rusqlite::params![inner.id],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            parent.as_deref(),
            Some(root_id.as_str()),
            "a defaulted move must write the resolved root, not blank the link"
        );
        assert_eq!(
            path,
            format!("{root_path}/Inner"),
            "the path must name the container the link points at"
        );
        assert!(
            !path.starts_with("Notes/"),
            "the container was moved into the locked container: {path}"
        );
        assert!(
            vault.join(&path).is_dir(),
            "no directory at the recorded path: {path}"
        );
        assert!(
            !vault.join("Notes/Inner").exists(),
            "a plaintext directory was created inside the sealed container"
        );
    }

    /// A move is refused when the SOURCE is sealed — including a sealed DESCENDANT that
    /// the source's parent links do not reach.
    ///
    /// The guard has to ask the question the move's own rewrite asks. That rewrite matches
    /// by path prefix; a parent-link walk would disagree with it on exactly the rows this
    /// step repairs, because every note container a shipped build created carries a correct
    /// path and a NULL parent link. So a locked descendant would be invisible to the guard
    /// and moved anyway — its `path` rewritten while its blobs and key stay behind.
    #[test]
    fn moving_a_container_with_a_sealed_descendant_is_refused() {
        let vault = tmp_vault("move-sealed-source");
        let state = build_state_with_vault("move-sealed-source", &vault);

        // (a) the container itself is sealed.
        make_open_folder(&state.db, "f-self", "Notes/Self");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-self'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join("Notes/Self")).unwrap();
        lock_folder_inner(&state, "f-self".into()).unwrap();

        let err = move_note_folder_inner(&state, "f-self", None)
            .expect_err("a sealed container must not be moved");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        // (b) an OPEN container holding a sealed descendant, linked ONLY by path — the shape
        // every shipped note container is in.
        let outer = create_note_folder_inner(&state, "Outer", None).unwrap();
        make_open_folder(&state.db, "f-inner", &format!("{}/Inner", outer.path));
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note', parent_id = NULL WHERE id = 'f-inner'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join(format!("{}/Inner", outer.path))).unwrap();
        lock_folder_inner(&state, "f-inner".into()).unwrap();

        // Control: the descendant really is invisible to a parent-link walk, or this oracle
        // would pass for the wrong reason.
        assert!(
            state.db.child_folders(&outer.id).unwrap().is_empty(),
            "the fixture must reproduce the NULL-parent shape it exists to cover"
        );

        let before: String = state
            .db
            .lock()
            .query_row(
                "SELECT path FROM folders WHERE id = ?1",
                rusqlite::params![outer.id],
                |r| r.get(0),
            )
            .unwrap();
        let err = move_note_folder_inner(&state, &outer.id, Some("f-self"))
            .expect_err("a sealed descendant must refuse the move");
        assert!(matches!(err, AppError::Locked(_)), "got {err:?}");

        let after: String = state
            .db
            .lock()
            .query_row(
                "SELECT path FROM folders WHERE id = ?1",
                rusqlite::params![outer.id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(before, after, "a refused move must not rewrite any path");
    }

    /// A container whose vault directory cannot be made does not survive as a row.
    ///
    /// The directory is created LAST, so this is the one remaining step that can fail after
    /// the row is durable — and a row without the directory its path names is a container the
    /// user was told was not created. `create_dir_all` fails here for a real reason: a plain
    /// FILE already occupies the path, which is what a vault synced from elsewhere can leave.
    #[test]
    fn a_container_whose_directory_cannot_be_made_leaves_no_row() {
        let vault = tmp_vault("dir-fails-undo");
        let state = build_state_with_vault("dir-fails-undo", &vault);
        let project = state.db.workspace_project_id().unwrap().expect("adopted");

        // A regular file where the container's directory would go.
        std::fs::write(vault.join("Q3"), b"not a directory").unwrap();

        let err = create_folder_inner(&state, "Q3".into(), None)
            .expect_err("a container whose directory cannot be made must not be created");
        assert!(matches!(err, AppError::Export(_)), "got {err:?}");

        let rows: i64 = state
            .db
            .lock()
            .query_row(
                "SELECT COUNT(*) FROM folders WHERE parent_id = ?1 AND name = 'Q3'",
                rusqlite::params![project],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            rows, 0,
            "a container survived without the directory its path names"
        );

        // The pre-existing file is untouched: it was never ours to remove.
        assert_eq!(
            std::fs::read(vault.join("Q3")).unwrap(),
            b"not a directory",
            "the undo took something the failed creation never made"
        );
    }

    /// A failed creation removes every directory it created — and nothing else.
    ///
    /// `create_dir_all` makes components until one breaks, so the cleanup has to remove more
    /// than the leaf. Two ways to get that wrong, both of which this fixture reproduces:
    ///
    ///   - inferring what to remove by walking upward over anything EMPTY takes the user's own
    ///     empty directory, and — since emptiness never stops the walk — eventually the vault;
    ///   - stopping at the first component that will not remove strands everything above it,
    ///     because the deepest recorded component is usually the one that was never created.
    ///
    /// So the failure is placed DEEP, beneath components that do get created, next to a
    /// directory the user already had.
    #[test]
    fn a_failed_creation_removes_only_what_it_created() {
        let vault = tmp_vault("cleanup-floor");
        let state = build_state_with_vault("cleanup-floor", &vault);
        let project = state.db.workspace_project_id().unwrap().unwrap();

        // The user's own empty directory, on the path the creation will travel.
        let mine = vault.join("Mine");
        std::fs::create_dir_all(&mine).unwrap();
        make_child_folder(&state.db, "f-mine", "Mine", "Mine", &project);

        // A container two levels down whose directories do NOT exist yet, with a FILE where the
        // last one would go — so `create_dir_all` creates the middle and then fails.
        make_child_folder(&state.db, "f-mid", "Mid", "Mine/Mid", "f-mine");
        std::fs::create_dir_all(mine.join("Mid")).unwrap();
        std::fs::remove_dir(mine.join("Mid")).unwrap();
        std::fs::write(mine.join("blocker"), b"x").unwrap();

        // Compose a path whose LAST component collides with that file.
        make_child_folder(&state.db, "f-blocked", "blocker", "Mine/blocker", "f-mine");
        let err = create_folder_inner(&state, "Deep".into(), Some("f-blocked".into()))
            .expect_err("the fixture must fail, or this oracle proves nothing");
        assert!(matches!(err, AppError::Export(_)), "got {err:?}");

        assert!(vault.is_dir(), "the cleanup removed the vault directory");
        assert!(
            mine.is_dir(),
            "the cleanup removed a directory it did not create"
        );
        assert!(
            mine.join("blocker").is_file(),
            "the cleanup removed a file it did not create"
        );
    }

    /// Deleting a folder must not move its authored notes into a LOCKED container.
    ///
    /// `reparent_authored_notes_to_default` USED TO resolve its destination with
    /// `ensure_default_note_folder`, whose comment asserted the result was safe: "the default
    /// folder is OPEN (root Notes is never locked), so a plain reassign is correct". That is
    /// not what the resolver does — it returns whatever row holds the path "Notes", creating
    /// it if absent and returning it REGARDLESS of `locked`, and it never consults `is_root`.
    ///
    /// So on a database where the user has locked a container at "Notes", deleting any note
    /// folder reassigns its notes there and exports their plaintext into its directory:
    /// unsealed content inside a sealed tree, which the at-rest re-blank sweep never visits
    /// because it keys off the container being marked locked.
    #[test]
    fn deleting_a_folder_never_files_its_notes_into_a_locked_container() {
        let vault = tmp_vault("delete-into-locked");
        let state = build_state_with_vault("delete-into-locked", &vault);

        // The user's own locked container sitting on the "Notes" path.
        make_open_folder(&state.db, "f-notes-taken", "Notes");
        state
            .db
            .lock()
            .execute(
                "UPDATE folders SET kind = 'note' WHERE id = 'f-notes-taken'",
                rusqlite::params![],
            )
            .unwrap();
        std::fs::create_dir_all(vault.join("Notes")).unwrap();
        lock_folder_inner(&state, "f-notes-taken".into()).unwrap();

        // A note folder holding one authored note with a real exported .md.
        let doomed = create_note_folder_inner(&state, "Drafts", None).unwrap();
        let note = create_note_inner(&state, Some(&doomed.id), "Roadmap").unwrap();
        update_note_doc_inner(&state, &note, "Roadmap", "# Roadmap\nShip Q3.").unwrap();

        delete_folder_inner(&state, doomed.id.clone()).unwrap();

        let landed: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT folder_id FROM documents WHERE id = ?1",
                rusqlite::params![note],
                |r| r.get(0),
            )
            .unwrap();
        // Not merely "somewhere else": the RESERVED root, which is the always-open home for
        // unfiled notes and the only destination that cannot later be sealed out from under
        // them. Asserting only "not the locked one" would accept any folder at all.
        let root = state.db.ensure_notes_root().unwrap();
        assert_eq!(
            landed.as_deref(),
            Some(root.as_str()),
            "an orphaned note must land in the reserved note root"
        );
        assert!(
            !vault.join("Notes/Roadmap.md").exists(),
            "plaintext was exported into a sealed container's directory"
        );
    }

    /// Renaming a note container must not strand its authored notes' `.md` outside the seal.
    ///
    /// The rename physically moves the vault subtree, so every recorded export path under it
    /// is stale the moment it returns. Meeting notes are re-derived by
    /// `reexport_notes_under_subtree`; authored notes live in `documents.exported_path`, which
    /// nothing on that path rewrites. The seal then removes plaintext BY RECORDED PATH ONLY
    /// (`note_exported_path_rows_in_folder` → `remove_note_export_if_unchanged`) with no
    /// directory sweep to catch what it missed — so the note the user just sealed stays
    /// readable on disk under its new name.
    ///
    /// This is the 2026-07-11 NOTES-2 leak reappearing on the path that never called its fix.
    #[test]
    fn renaming_a_note_container_still_seals_its_authored_notes_md() {
        let vault = tmp_vault("rename-then-seal");
        let state = build_state_with_vault("rename-then-seal", &vault);
        let fid = create_note_folder_inner(&state, "Ideas", None).unwrap().id;
        let id = create_note_inner(&state, Some(&fid), "Roadmap").unwrap();
        update_note_doc_inner(&state, &id, "Roadmap", "# Roadmap\nShip Q3.").unwrap();

        let before = get_note_inner(&state, &id)
            .unwrap()
            .exported_path
            .expect("note exported to vault");
        assert!(std::path::Path::new(&before).exists());

        rename_folder_inner(&state, fid.clone(), "Plans".into()).unwrap();
        assert!(
            !std::path::Path::new(&before).exists(),
            "control: the rename must actually move the file, or this oracle proves nothing"
        );

        lock_folder_inner(&state, fid.clone()).unwrap();

        // Nothing readable may survive anywhere under the vault.
        fn walk(dir: &std::path::Path, out: &mut Vec<String>) {
            let Ok(entries) = std::fs::read_dir(dir) else {
                return;
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    walk(&path, out);
                } else if path.extension().and_then(|e| e.to_str()) == Some("md") {
                    out.push(path.to_string_lossy().into_owned());
                }
            }
        }
        let mut survivors = Vec::new();
        walk(&vault, &mut survivors);
        assert!(
            survivors.is_empty(),
            "plaintext survived the seal after a rename: {survivors:?}"
        );

        // And the RECORDED path is cleared. An empty vault with a stale path still pointing at
        // a file is the state a later relock would chase and miss; the disk and the row have to
        // agree that nothing is exported.
        assert!(
            state
                .db
                .note_exported_path_rows_in_folder(&fid)
                .unwrap()
                .is_empty(),
            "exported_path survived the seal"
        );
    }

    /// A note root created AFTER adoption is inside the project, not beside it.
    #[test]
    fn a_note_root_created_after_adoption_is_inside_the_project() {
        let state = build_state("late-note-root");
        let project = state.db.workspace_project_id().unwrap().expect("adopted");
        let root = state.db.ensure_notes_root().unwrap();
        let parent: Option<String> = state
            .db
            .lock()
            .query_row(
                "SELECT parent_id FROM folders WHERE id = ?1",
                rusqlite::params![root],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            parent.as_deref(),
            Some(project.as_str()),
            "unfiled notes would be unreachable in the tree otherwise"
        );
    }

    #[test]
